const t=[{id:"m1-alphabet",module:1,order:1,level:"A1",title:"Alifbo va tovushlar",subtitle:"33 harf, harf-tovush mosligi",theory:[{heading:"Rus alifbosi",body:"Rus alifbosida 33 harf bor: 10 unli (а, е, ё, и, о, у, ы, э, ю, я), 21 undosh va 2 belgi (ь, ъ). Ko'p harflar kirill yozuvidagi o'zbekchaga o'xshaydi, lekin ы, э, щ, ъ harflari yangi."},{heading:"O'zbek tilida yo'q tovushlar",body:"ы — til orqa qismida aytiladigan 'i' (мы, ты, сын). щ — yumshoq va cho'ziq 'shsh' (щи, борщ). Bu ikkisini alohida mashq qilish kerak.",table:[["Harf","Tovush","Misol"],["ы","qattiq 'i'","мы — biz, сын — o‘g‘il"],["щ","yumshoq 'shsh'","щи — karam sho‘rva, ещё — yana"],["э","ochiq 'e'","это — bu, экран — ekran"],["ё","'yo' (doim urg'uli)","ёлка — archa, всё — hammasi"]]}],comparisonWithUzbek:"O'zbek kirill alifbosini bilsangiz, rus alifbosining 90% i tanish. Farqlar: rus tilida ў, қ, ғ, ҳ yo'q; o'zbek tilida ы, щ, э (so'z boshida emas), ъ (ajratuvchi) kam ishlatiladi.",examples:[{ru:"мы",uz:"biz",note:"ы — qattiq 'i'"},{ru:"ты",uz:"sen"},{ru:"сын",uz:"o'g'il"},{ru:"ещё",uz:"yana",note:"щ — yumshoq 'shsh'"},{ru:"э́то",uz:"bu"},{ru:"ёлка",uz:"archa",note:"ё har doim urg'uli"}],commonMistakes:[{wrong:"мi (мы o‘rniga)",right:"мы",why_uz:"ы ni oddiy 'i' deb o'qimaslik kerak — til orqaroqda turadi."},{wrong:"шы",right:"ши",why_uz:"ж va ш dan keyin doim и yoziladi, ы emas (жи-ши qoidasi)."},{wrong:"що",right:"что",why_uz:"что so'zida ч 'sh' bo'lib o'qiladi: [shto]."}],exercises:[{id:"m1-alphabet-1",type:"choose",prompt:"Qaysi so'zda ы tovushi bor?",answer:"сын",choices:["сын","синий","семь","сюда"],explanation_uz:"сын — o'g'il; ы qattiq talaffuz qilinadi."},{id:"m1-alphabet-2",type:"choose",prompt:"щ harfi qanday o'qiladi?",answer:"yumshoq cho'ziq shsh",choices:["yumshoq cho'ziq shsh","qattiq sh","ch","j"],explanation_uz:"щ = yumshoq, cho'ziq 'shsh': щи, ещё."},{id:"m1-alphabet-3",type:"choose",prompt:"«мы» so'zi nimani anglatadi?",answer:"biz",choices:["biz","sen","ular","siz"],explanation_uz:"мы — biz."},{id:"m1-alphabet-4",type:"fillBlank",prompt:"ж va ш dan keyin doim ___ yoziladi (жи-ши qoidasi).",answer:"и",explanation_uz:"жи-ши qoidasi: жить, машина."},{id:"m1-alphabet-5",type:"choose",prompt:"ё harfi haqida qaysi gap to'g'ri?",answer:"Har doim urg'uli",choices:["Har doim urg'uli","Hech qachon urg'uli emas","Faqat fe’llarda ishlatiladi","O'qilmaydi"],explanation_uz:"ё bor so'zda urg'u doim ё ga tushadi: ёлка, идёт."},{id:"m1-alphabet-6",type:"translate",prompt:"Tarjima qiling: «бу» (ruscha ko'rsatish so'zi)",answer:"это",explanation_uz:"Bu — это. Это дом — Bu uy."},{id:"m1-alphabet-7",type:"choose",prompt:"«что» so'zi qanday o'qiladi?",answer:"[што]",choices:["[што]","[что]","[щто]","[чито]"],explanation_uz:"что so'zida ч tarixan 'sh' bo'lib o'qiladi."},{id:"m1-alphabet-8",type:"choose",prompt:"Rus alifbosida nechta harf bor?",answer:"33",choices:["33","29","36","26"],explanation_uz:"10 unli + 21 undosh + ь va ъ = 33."}]},{id:"m1-stress",module:1,order:2,level:"A1",title:"Urg'u va reduktsiya",subtitle:"Urg'usiz о → а, е → и",theory:[{heading:"Urg'u nima uchun muhim",body:"Rus tilida urg'u erkin va harakatchan: u so'z ma'nosini o'zgartirishi mumkin (за́мок — qal'a, замо́к — qulf). Har yangi so'zni urg'usi bilan yodlang."},{heading:"Reduktsiya",body:"Urg'usiz bo'g'inda unlilar kuchsizlanadi: о → [a] (молоко́ → [malako]), е/я → [i] (язы́к → [yizik]). Yozuvda o'zgarmaydi, faqat talaffuzda!",table:[["Yozilishi","Aytilishi","Ma'nosi"],["молоко́","[малако́]","sut"],["хорошо́","[харашо́]","yaxshi"],["язы́к","[йизы́к]","til"],["сейча́с","[сича́с]","hozir"]]}],comparisonWithUzbek:"O'zbek tilida urg'u deyarli doim oxirgi bo'g'inda va unlilar reduktsiya qilinmaydi. Rus tilida esa urg'usiz 'o' ni 'a' deb aytish majburiy — aks holda aksent kuchli seziladi.",examples:[{ru:"вода́",uz:"suv",note:"[вада́] — o urg'usiz, a bo'ladi"},{ru:"окно́",uz:"deraza",note:"[акно́]"},{ru:"го́род",uz:"shahar",note:"[го́рат] — ikkinchi o urg'usiz"},{ru:"за́мок / замо́к",uz:"qal'a / qulf",note:"urg'u ma'noni o'zgartiradi"},{ru:"пишу́ — пи́шешь",uz:"yozaman — yozasan",note:"urg'u ko'chadi"}],commonMistakes:[{wrong:"[молоко] deb aytish",right:"[малако́]",why_uz:"Urg'usiz о doim [a] ga yaqin aytiladi."},{wrong:"urg'usiz yodlash",right:"urg'u bilan yodlash",why_uz:"Noto'g'ri urg'u tushunishni qiyinlashtiradi: писа́ть (yozmoq) vs пи́сать."}],exercises:[{id:"m1-stress-1",type:"choose",prompt:"«молоко» so'zida urg'u qayerda?",answer:"oxirgi bo‘g‘inda (молоко́)",choices:["oxirgi bo‘g‘inda (молоко́)","birinchi bo‘g‘inda","o‘rtada","urg'u yo'q"],explanation_uz:"молоко́ — [малако́]."},{id:"m1-stress-2",type:"choose",prompt:"Urg'usiz «о» qanday aytiladi?",answer:"[a] ga yaqin",choices:["[a] ga yaqin","[o] bo‘lib qoladi","[u] ga yaqin","aytilmaydi"],explanation_uz:"Bu reduktsiya deyiladi: вода́ → [вада́]."},{id:"m1-stress-3",type:"choose",prompt:"«за́мок» nimani anglatadi?",answer:"qal'a",choices:["qal'a","qulf","shahar","deraza"],explanation_uz:"за́мок — qal'a, замо́к — qulf. Urg'u ma'noni o'zgartiradi."},{id:"m1-stress-4",type:"choose",prompt:"«хорошо» qanday o'qiladi?",answer:"[харашо́]",choices:["[харашо́]","[хорошо́]","[хурушо́]","[хорошу́]"],explanation_uz:"Ikkala urg'usiz о ham [a] bo'ladi."},{id:"m1-stress-5",type:"fillBlank",prompt:"ё harfi bor so'zda urg'u doim ___ harfiga tushadi.",answer:"ё",explanation_uz:"идёт, ёлка, всё — ё doim urg‘uli."},{id:"m1-stress-6",type:"choose",prompt:"Qaysi juftlikda urg'u ma'noni o'zgartiradi?",answer:"за́мок — замо́к",choices:["за́мок — замо́к","дом — дома́шний","мама — папа","да — нет"],explanation_uz:"за́мок (qal'a) va замо́к (qulf) — bir xil yozilади, har xil ma'no."},{id:"m1-stress-7",type:"choose",prompt:"«сейчас» og'zaki nutqda qanday eshitiladi?",answer:"[сича́с]",choices:["[сича́с]","[сейча́с]","[сэйча́с]","[сючас]"],explanation_uz:"Urg'usiz е [i] ga yaqinlashadi."},{id:"m1-stress-8",type:"translate",prompt:"Tarjima qiling: вода́",answer:"suv",explanation_uz:"вода́ — suv, [вада́] deb aytiladi."}]},{id:"m1-soft-hard",module:1,order:3,level:"A1",title:"Qattiq va yumshoq undoshlar, ь va ъ",subtitle:"Yumshoq belgi nima uchun kerak",theory:[{heading:"Yumshoqlik",body:"Deyarli har bir rus undoshi qattiq yoki yumshoq bo'lishi mumkin. Undoshni yumshatadigan narsalar: е, ё, и, ю, я unlilari va ь belgisi. мать [mat'] — мат [mat] — bular har xil so'zlar!",table:[["Qattiq","Yumshoq","Farq"],["мат (so‘kinish)","мать (ona)","ь yumshatadi"],["брат (aka)","брать (olmoq)","ь yumshatadi"],["лук (piyoz)","люк (lyuk)","ю yumshatadi"],["нос (burun)","нёс (olib bordi)","ё yumshatadi"]]},{heading:"ь va ъ belgilari",body:"ь (yumshoq belgi) — oldingi undoshni yumshatadi yoki ajratadi (семья — oila). ъ (qattiq belgi) — prefiks bilan ildiz orasida ajratish uchun: подъезд, объявление. Ikkalasi ham tovush emas!"}],comparisonWithUzbek:"O'zbek tilida undosh yumshoqligi ma'no farqlamaydi, shuning uchun мать/мат farqini eshitish boshida qiyin. 'Yumshoq' undoshni aytishda til o'rta qismi tanglayga ko'tariladi — go'yo undoshdan keyin juda qisqa 'y' qo'shilganday.",examples:[{ru:"мать",uz:"ona",note:"т yumshoq [t']"},{ru:"брать",uz:"olmoq",note:"брат (aka) bilan adashtirmang"},{ru:"семья́",uz:"oila",note:"ь ajratib turadi: [sim-ya]"},{ru:"подъе́зд",uz:"kirish (eshik)",note:"ъ ajratuvchi"},{ru:"де́нь",uz:"kun",note:"н yumshoq"}],commonMistakes:[{wrong:"брат олмоқ ma’nosida",right:"брать",why_uz:"ь siz брат = aka, ь bilan брать = olmoq (fe'l)."},{wrong:"семя (urug‘)",right:"семья (oila)",why_uz:"ь tushib qolsa boshqa so‘z bo‘lib qoladi."},{wrong:"ь ni alohida tovush deb o‘qish",right:"ь faqat yumshatadi",why_uz:"ь hech qachon alohida aytilmaydi."}],exercises:[{id:"m1-soft-1",type:"choose",prompt:"«мать» nimani anglatadi?",answer:"ona",choices:["ona","so‘kinish","mato","asal"],explanation_uz:"мать — ona; мат — boshqa so'z."},{id:"m1-soft-2",type:"choose",prompt:"Qaysi belgi undoshni yumshatadi?",answer:"ь",choices:["ь","ъ","ы","э"],explanation_uz:"ь — yumshoq belgi (мягкий знак)."},{id:"m1-soft-3",type:"choose",prompt:"«olmoq» fe'li ruscha qanday yoziladi?",answer:"брать",choices:["брать","брат","бранить","братт"],explanation_uz:"брать — olmoq, брат — aka."},{id:"m1-soft-4",type:"choose",prompt:"ъ belgisi qayerda ishlatiladi?",answer:"prefiks va ildiz orasida ajratish uchun",choices:["prefiks va ildiz orasida ajratish uchun","so'z oxirida yumshatish uchun","urg'u belgilash uchun","ko'plik yasash uchun"],explanation_uz:"подъезд, объявление — ъ ajratib turadi."},{id:"m1-soft-5",type:"fillBlank",prompt:"Oila — сем___я",answer:"ь",explanation_uz:"семья — ь ajratuvchi vazifasida."},{id:"m1-soft-6",type:"choose",prompt:"Qaysi unlilar undoshni yumshatadi?",answer:"е, ё, и, ю, я",choices:["е, ё, и, ю, я","а, о, у, ы, э","faqat и","faqat я"],explanation_uz:"Bu 5 unli oldingi undoshni yumshatadi; а, о, у, ы, э — qattiq qoldiradi."},{id:"m1-soft-7",type:"choose",prompt:"«лук» va «люк» farqi nimada?",answer:"л qattiq/yumshoq",choices:["л qattiq/yumshoq","urg'uda","ma'nosi bir xil","к da"],explanation_uz:"лук [luk] — piyoz, люк [l‘uk] — lyuk: ю л ni yumshatadi."},{id:"m1-soft-8",type:"translate",prompt:"Tarjima qiling: день",answer:"kun",explanation_uz:"день — kun; so'z oxiridagi н yumshoq."}]},{id:"m1-pronouns",module:1,order:4,level:"A1",title:"Shaxs olmoshlari va «это»",subtitle:"я, ты, он, она, оно, мы, вы, они",theory:[{heading:"Shaxs olmoshlari",body:"8 ta shaxs olmoshi bor. вы ikki vazifada: ko'plik 'siz(lar)' va hurmat 'Siz'. Notanish va katta yoshli odamlarga doim вы deyiladi.",table:[["Ruscha","O'zbekcha","Izoh"],["я","men",""],["ты","sen","yaqin do'st, bola"],["он / она́ / оно́","u","rodga qarab"],["мы","biz",""],["вы","siz / sizlar","hurmat ham"],["они́","ular",""]]},{heading:"«Это» bilan gaplar",body:"Это + ot = 'Bu — ...'. Eng sodda gap qolipi: Это дом (Bu uy). Savol: Что это? (Bu nima?), Кто это? (Bu kim?)."}],comparisonWithUzbek:"O'zbek tilidagi 'u' rus tilida uchga bo'linadi: он (erkak rod), она (ayol rod), оно (o'rta rod). Predmetlar ham rodga ega: стол — он, книга — она, окно — оно.",examples:[{ru:"Э́то дом.",uz:"Bu — uy."},{ru:"Кто э́то? — Э́то мой брат.",uz:"Bu kim? — Bu mening akam."},{ru:"Что э́то? — Э́то кни́га.",uz:"Bu nima? — Bu kitob."},{ru:"Где он? — Он до́ма.",uz:"U qayerda? — U uyda."},{ru:"Вы студе́нт?",uz:"Siz talabamisiz?",note:"hurmat shakli"}],commonMistakes:[{wrong:"Он книга",right:"Она (книга)",why_uz:"книга — ayol rod, shuning uchun 'она'."},{wrong:"ты ni hammaga ishlatish",right:"notanishlarga вы",why_uz:"Rus madaniyatida notanish odamga ты deyish qo'pollik."},{wrong:"Это есть дом",right:"Это дом",why_uz:"Hozirgi zamonda 'есть' (is) ishlatilmaydi."}],exercises:[{id:"m1-pron-1",type:"choose",prompt:"«biz» ruscha qanday?",answer:"мы",choices:["мы","вы","они","я"],explanation_uz:"мы — biz."},{id:"m1-pron-2",type:"choose",prompt:"книга haqida gapirganda qaysi olmosh ishlatiladi?",answer:"она",choices:["она","он","оно","они"],explanation_uz:"книга — ayol rod → она."},{id:"m1-pron-3",type:"choose",prompt:"Notanish katta odamga qanday murojaat qilinadi?",answer:"вы",choices:["вы","ты","он","они"],explanation_uz:"вы — hurmat shakli."},{id:"m1-pron-4",type:"fillBlank",prompt:"___ это? — Это моя сестра.",answer:"Кто",explanation_uz:"Odam haqida so'ralganda Кто (kim) ishlatiladi."},{id:"m1-pron-5",type:"fillBlank",prompt:"___ это? — Это стол.",answer:"Что",explanation_uz:"Predmet haqida — Что (nima)."},{id:"m1-pron-6",type:"translate",prompt:"Tarjima qiling: «Bu — kitob.»",answer:"Это книга",explanation_uz:"Это + ot. 'есть' kerak emas."},{id:"m1-pron-7",type:"choose",prompt:"окно haqida qaysi olmosh?",answer:"оно",choices:["оно","он","она","оны"],explanation_uz:"окно — o'rta rod → оно."},{id:"m1-pron-8",type:"sentenceBuilder",prompt:"Gap tuzing: «Bu mening akam»",answer:"Это мой брат",tokens:["брат","Это","мой"],explanation_uz:"Это мой брат."}]},{id:"m1-no-be",module:1,order:5,level:"A1",title:"«Bo'lmoq» fe'lisiz gaplar",subtitle:"Я студент. Он врач.",theory:[{heading:"Hozirgi zamonda 'to be' yo'q",body:"Ingliz tilidagi am/is/are rus tilining hozirgi zamonida ishlatilmaydi: Я студент (Men talabaman), Он врач (U shifokor). O'tgan zamonda был/была́/бы́ло/бы́ли, kelasi zamonda буду/будешь... paydo bo'ladi.",table:[["Zamon","Misol","Tarjima"],["Hozirgi","Я до́ма","Men uydaman"],["O'tgan","Я был до́ма","Men uyda edim"],["Kelasi","Я бу́ду до́ма","Men uyda bo'laman"]]},{heading:"Tire qachon qo‘yiladi",body:"Ikkala tomon ham ot bo'lsa, yozuvda tire qo'yish mumkin: Москва́ — столи́ца Росси́и (Moskva — Rossiya poytaxti)."}],comparisonWithUzbek:"O'zbek tiliga juda o'xshash! 'Men talabaman' — Я студент: o'zbekcha -man qo'shimchasi ham, ruscha 'to be' ham hozirgi zamonda alohida so'z emas. Bu mavzu o'zbeklar uchun oson.",examples:[{ru:"Я студе́нт.",uz:"Men talabaman."},{ru:"Он врач.",uz:"U shifokor."},{ru:"Мы до́ма.",uz:"Biz uydamiz."},{ru:"Она́ была́ в Москве́.",uz:"U Moskvada bo'lgan edi.",note:"o'tgan zamonda быть keladi"},{ru:"За́втра я бу́ду на рабо́те.",uz:"Ertaga men ishda bo‘laman."}],commonMistakes:[{wrong:"Я есть студент",right:"Я студент",why_uz:"Hozirgi zamonda 'есть' bog'lovchi sifatida ishlatilmaydi."},{wrong:"Он быть врач",right:"Он врач",why_uz:"Infinitiv быть hozirgi zamonda kerak emas."},{wrong:"Она был дома",right:"Она была дома",why_uz:"O'tgan zamonda быть rodga moslashadi: он был, она была."}],exercises:[{id:"m1-be-1",type:"translate",prompt:"Tarjima qiling: «Men talabaman»",answer:"Я студент",explanation_uz:"Hozirgi zamonda bog'lovchi yo'q."},{id:"m1-be-2",type:"choose",prompt:"Qaysi gap to'g'ri?",answer:"Он врач",choices:["Он врач","Он есть врач","Он быть врач","Он врачом"],explanation_uz:"Hozirgi zamon: Он врач."},{id:"m1-be-3",type:"fillBlank",prompt:"Вчера я ___ дома. (быть, erkak)",answer:"был",explanation_uz:"O'tgan zamon erkak rod: был."},{id:"m1-be-4",type:"fillBlank",prompt:"Завтра мы ___ в школе. (быть)",answer:"будем",explanation_uz:"Kelasi zamon: мы будем."},{id:"m1-be-5",type:"transform",prompt:"O'tgan zamonga o'tkazing: «Она дома»",answer:"Она была дома",explanation_uz:"она → была."},{id:"m1-be-6",type:"translate",prompt:"Tarjima qiling: «Biz uydamiz»",answer:"Мы дома",explanation_uz:"Мы дома — juda sodda!"},{id:"m1-be-7",type:"errorHunt",prompt:"Xatoni toping va to'g'rilang: «Я есть учитель»",answer:"Я учитель",explanation_uz:"'есть' ortiqcha."},{id:"m1-be-8",type:"sentenceBuilder",prompt:"Gap tuzing: «Moskva — Rossiya poytaxti»",answer:"Москва столица России",tokens:["столица","Москва","России"],explanation_uz:"Москва — столица России."}]},{id:"m1-intonation",module:1,order:6,level:"A1",title:"Savol intonatsiyasi",subtitle:"So'roq so'zsiz savol berish",theory:[{heading:"Intonatsiya bilan savol",body:"Rus tilida 'ha/yo'q' savoli ko'pincha faqat intonatsiya bilan beriladi — so'z tartibi o'zgarmaydi: Это дом. (darak) / Это дом? (savol). Savolda ovoz so'ralayotgan so'zda keskin ko'tariladi."},{heading:"So'roq so'zli savol",body:"Кто, что, где, куда, когда, почему, как, сколько bilan boshlanadigan savolda ovoz so'roq so'zida ko'tarilib, keyin pasayadi: Где ты живёшь?",table:[["So'roq so'zi","Ma'nosi","Misol"],["кто","kim","Кто это?"],["что","nima","Что это?"],["где","qayerda","Где ты?"],["куда","qayerga","Куда ты идёшь?"],["когда","qachon","Когда урок?"],["как","qanday","Как дела?"]]}],comparisonWithUzbek:"O'zbek tilida savol uchun '-mi' qo'shimchasi bor: 'Bu uymi?'. Rus tilida bunday qo'shimcha yo'q — faqat intonatsiya: Это дом?. (Rasmiy uslubda 'ли' yuklamasi ham bor, keyinroq o'rganiladi.)",examples:[{ru:"Это дом?",uz:"Bu uymi?",note:"ovoz 'дом' da ko'tariladi"},{ru:"Ты студе́нт?",uz:"Sen talabamisan?"},{ru:"Как дела́?",uz:"Qalaysan? / Ishlar qanday?"},{ru:"Где ты живёшь?",uz:"Qayerda yashaysan?"},{ru:"Ско́лько э́то сто́ит?",uz:"Bu qancha turadi?"}],commonMistakes:[{wrong:"Это дом ми?",right:"Это дом?",why_uz:"Rus tilida '-mi' yo'q, intonatsiya kifoya."},{wrong:"Где ты живёшь? (tekis ohangda)",right:"ovozni где da ko'tarish",why_uz:"Noto'g'ri intonatsiya savol ekanini bildirmaydi."}],exercises:[{id:"m1-int-1",type:"choose",prompt:"«Qayerda» ruscha qanday?",answer:"где",choices:["где","куда","когда","кто"],explanation_uz:"где — qayerda (joy), куда — qayerga (yo‘nalish)."},{id:"m1-int-2",type:"choose",prompt:"«Qancha turadi?» qanday so‘raladi?",answer:"Сколько это стоит?",choices:["Сколько это стоит?","Когда это стоит?","Где это стоит?","Что это стоит?"],explanation_uz:"сколько — qancha."},{id:"m1-int-3",type:"translate",prompt:"Tarjima qiling: «Bu uymi?»",answer:"Это дом?",explanation_uz:"Faqat intonatsiya — '-mi' uchun alohida so'z yo'q."},{id:"m1-int-4",type:"fillBlank",prompt:"___ ты идёшь? — В школу.",answer:"Куда",explanation_uz:"Javob yo'nalish (maktabGA) bo'lgani uchun куда."},{id:"m1-int-5",type:"fillBlank",prompt:"___ дела? — Хорошо!",answer:"Как",explanation_uz:"Как дела? — eng mashhur savol."},{id:"m1-int-6",type:"choose",prompt:"Intonatsiya savoli «Ты дома?»da ovoz qayerda ko'tariladi?",answer:"дома so‘zida",choices:["дома so‘zida","ты so‘zida","hech qayerda","gap oxirida pasayadi"],explanation_uz:"So'ralayotgan so'zda ovoz ko'tariladi."},{id:"m1-int-7",type:"translate",prompt:"Tarjima qiling: «Qachon dars?»",answer:"Когда урок?",explanation_uz:"когда — qachon."},{id:"m1-int-8",type:"errorHunt",prompt:"Xatoni toping: «Это книга ми?»",answer:"Это книга?",explanation_uz:"'ми' degan yuklama rus tilida yo'q."}],miniDialogue:[{speaker:"A",ru:"Привет! Как дела?",uz:"Salom! Qalaysan?"},{speaker:"B",ru:"Хорошо, спасибо. А у тебя?",uz:"Yaxshi, rahmat. O‘zingchi?"},{speaker:"A",ru:"Тоже хорошо. Ты сейчас дома?",uz:"Men ham yaxshi. Hozir uydamisan?"},{speaker:"B",ru:"Нет, я на работе.",uz:"Yo‘q, ishdaman."}]}],s=[{id:"m2-gender",module:2,order:1,level:"A1",title:"Rod: мужской, женский, средний",subtitle:"Oxirgi harfga qarab aniqlash",theory:[{heading:"Asosiy qoida",body:"Otning rodini oxirgi harfidan aniqlaymiz. Bu rus grammatikasining poydevori — sifat, fe'l (o'tgan zamon) va olmoshlar rodga moslashadi.",table:[["Rod","Oxiri","Misollar"],["мужской (он)","undosh, -й, ba’zi -ь","стол, музей, словарь"],["женский (она)","-а, -я, ba’zi -ь","книга, неделя, ночь"],["средний (оно)","-о, -е, -мя","окно, море, время"]]},{heading:"Istisnolar",body:"1) Erkak kishini bildiruvchi -а/-я li so'zlar мужской: папа, дедушка, дядя, мужчина. 2) кофе — мужской (у kirib kelgan so'z). 3) время, имя — средний (-мя). 4) -ь bilan tugaganlar lug'atdan yodlanadi: день (м), ночь (ж), словарь (м), тетрадь (ж)."}],comparisonWithUzbek:"O'zbek tilida rod tushunchasi umuman yo'q — bu ruschadagi eng katta yangi odat. Har yangi otni rodi bilan birga yodlang: 'книга — она', 'стол — он' deb.",examples:[{ru:"стол — он",uz:"stol",note:"undosh bilan tugadi → м"},{ru:"кни́га — она́",uz:"kitob",note:"-а → ж"},{ru:"окно́ — оно́",uz:"deraza",note:"-о → с"},{ru:"па́па — он",uz:"dada",note:"istisno: erkak kishi"},{ru:"ночь — она́",uz:"tun",note:"-ь, ammo ж"},{ru:"вре́мя — оно́",uz:"vaqt",note:"-мя → с"},{ru:"ко́фе — он",uz:"kofe",note:"istisno"}],commonMistakes:[{wrong:"папа — она",right:"папа — он",why_uz:"-а bilan tugasa ham erkak kishini bildirgani uchun мужской."},{wrong:"кофе — оно",right:"кофе — он",why_uz:"кофе istisno tarzda мужской: вкусный кофе."},{wrong:"время — она",right:"время — оно",why_uz:"-мя bilan tugagan 10 ta ot средний rod."}],exercises:[{id:"m2-gen-1",type:"caseDetector",prompt:"книга — qaysi rod?",answer:"женский",choices:["мужской","женский","средний"],explanation_uz:"-а bilan tugaydi → женский."},{id:"m2-gen-2",type:"caseDetector",prompt:"стол — qaysi rod?",answer:"мужской",choices:["мужской","женский","средний"],explanation_uz:"Undosh bilan tugaydi → мужской."},{id:"m2-gen-3",type:"caseDetector",prompt:"окно — qaysi rod?",answer:"средний",choices:["мужской","женский","средний"],explanation_uz:"-о → средний."},{id:"m2-gen-4",type:"caseDetector",prompt:"папа — qaysi rod?",answer:"мужской",choices:["мужской","женский","средний"],explanation_uz:"Erkak kishini bildiradi → мужской (istisno)."},{id:"m2-gen-5",type:"caseDetector",prompt:"время — qaysi rod?",answer:"средний",choices:["мужской","женский","средний"],explanation_uz:"-мя bilan tugagan otlar средний."},{id:"m2-gen-6",type:"caseDetector",prompt:"ночь — qaysi rod?",answer:"женский",choices:["мужской","женский","средний"],explanation_uz:"ночь — ж (yodlash kerak), день — м."},{id:"m2-gen-7",type:"caseDetector",prompt:"музей — qaysi rod?",answer:"мужской",choices:["мужской","женский","средний"],explanation_uz:"-й bilan tugaydi → мужской."},{id:"m2-gen-8",type:"caseDetector",prompt:"кофе — qaysi rod?",answer:"мужской",choices:["мужской","женский","средний"],explanation_uz:"кофе — istisno, мужской."},{id:"m2-gen-9",type:"fillBlank",prompt:"кни́га — он___ (olmosh)",answer:"а",explanation_uz:"книга → она."},{id:"m2-gen-10",type:"choose",prompt:"Qaysi qatorda hammasi женский rod?",answer:"мама, неделя, ночь",choices:["мама, неделя, ночь","стол, книга, окно","папа, мама, море","день, ночь, время"],explanation_uz:"мама (-а), неделя (-я), ночь (ж istisno)."}]},{id:"m2-plural",module:2,order:2,level:"A1",title:"Ko'plik shakli",subtitle:"столы, книги, окна",theory:[{heading:"Asosiy qoidalar",body:"Ko'plik yasash rodga va oxirgi harfga bog'liq.",table:[["Birlik","Ko'plik","Qoida"],["стол","столы́","qattiq undosh → -ы"],["кни́га","кни́ги","г,к,х,ж,ш,ч,щ dan keyin → -и"],["музе́й","музе́и","-й → -и"],["слова́рь","словари́","-ь → -и"],["окно́","о́кна","-о → -а"],["мо́ре","моря́","-е → -я"]]},{heading:"Muhim istisnolar",body:"человек → люди (odamlar), ребёнок → дети (bolalar), друг → друзья, брат → братья, стул → стулья, дом → дома́, город → города́, глаз → глаза́. Ba'zi so'zlar faqat ko'plikda: деньги (pul), очки (ko'zoynak), часы (soat)."}],comparisonWithUzbek:"O'zbek tilida bitta universal '-lar' bor. Rus tilida qo'shimcha rod va oxirgi tovushga qarab tanlanadi, urg'u ham ko'chishi mumkin (стол → столы́).",examples:[{ru:"стол → столы́",uz:"stol → stollar"},{ru:"кни́га → кни́ги",uz:"kitob → kitoblar",note:"г dan keyin -и"},{ru:"окно́ → о́кна",uz:"deraza → derazalar",note:"urg'u ko'chdi"},{ru:"челове́к → лю́ди",uz:"odam → odamlar",note:"istisno!"},{ru:"ребёнок → де́ти",uz:"bola → bolalar",note:"istisno!"},{ru:"друг → друзья́",uz:"do'st → do'stlar",note:"istisno"},{ru:"го́род → города́",uz:"shahar → shaharlar",note:"-а bilan"}],commonMistakes:[{wrong:"человеки",right:"люди",why_uz:"человек ko'pligi mutlaqo boshqa so'z: люди."},{wrong:"ребёнки",right:"дети",why_uz:"ребёнок → дети (istisno)."},{wrong:"книгы",right:"книги",why_uz:"г, к, х dan keyin ы emas, и yoziladi."},{wrong:"окны",right:"окна",why_uz:"O'rta rod -о → -а bo'ladi."}],exercises:[{id:"m2-pl-1",type:"transform",prompt:"Ko'plikka o'tkazing: стол",answer:"столы",explanation_uz:"стол → столы́."},{id:"m2-pl-2",type:"transform",prompt:"Ko'plikka o'tkazing: книга",answer:"книги",explanation_uz:"г dan keyin -и: книги."},{id:"m2-pl-3",type:"transform",prompt:"Ko'plikka o'tkazing: окно",answer:"окна",explanation_uz:"окно → о́кна."},{id:"m2-pl-4",type:"transform",prompt:"Ko'plikka o'tkazing: человек",answer:"люди",explanation_uz:"Istisno: человек → люди."},{id:"m2-pl-5",type:"transform",prompt:"Ko'plikka o'tkazing: ребёнок",answer:"дети",explanation_uz:"Istisno: ребёнок → дети."},{id:"m2-pl-6",type:"transform",prompt:"Ko'plikka o'tkazing: друг",answer:"друзья",explanation_uz:"друг → друзья́."},{id:"m2-pl-7",type:"transform",prompt:"Ko'plikka o'tkazing: словарь",answer:"словари",explanation_uz:"-ь → -и: словари́."},{id:"m2-pl-8",type:"choose",prompt:"Qaysi so'z faqat ko'plikda ishlatiladi?",answer:"деньги",choices:["деньги","дом","мама","город"],explanation_uz:"деньги (pul) birlikda ishlatilmaydi."},{id:"m2-pl-9",type:"transform",prompt:"Ko'plikka o'tkazing: город",answer:"города",explanation_uz:"город → города́ (-а bilan)."},{id:"m2-pl-10",type:"errorHunt",prompt:"Xatoni toping: «В классе пять человеки»",answer:"В классе пять человек",explanation_uz:"Sanoqdan keyin человек o'zgarmaydi: пять человек."}]},{id:"m2-animacy",module:2,order:3,level:"A1",title:"Jonli va jonsiz otlar",subtitle:"кто? — что?",theory:[{heading:"Nega kerak",body:"Rus tilida otlar jonli (одушевлённые — odamlar, hayvonlar) va jonsiz (неодушевлённые) ga bo'linadi. Jonlilarga savol: кто? (kim?), jonsizlarga: что? (nima?). Diqqat: rus tilida hayvonlar ham кто!"},{heading:"Tushum kelishigiga ta'siri",body:"Bu farq винительный падеж (tushum kelishigi)da muhim: jonli мужской otlar родительный shaklini oladi: Я вижу стол (jonsiz, o'zgarmadi) — Я вижу брата (jonli, брат → брата).",table:[["","Jonsiz","Jonli"],["Bosh kelishik","стол","брат"],["Tushum (вижу...)","стол","бра́та"]]}],comparisonWithUzbek:"O'zbek tilida 'kim' faqat odamga, hayvonga 'nima' deyiladi. Rus tilida esa mushuk ham, qush ham кто. Tushumdagi -а o'zgarishi o'zbekcha '-ni' ga o'xshab ishlaydi, lekin faqat jonli erkak rodda ko'rinadi.",examples:[{ru:"Кто э́то? — Э́то ко́шка.",uz:"Bu kim? — Bu mushuk.",note:"hayvon ham кто!"},{ru:"Что э́то? — Э́то стол.",uz:"Bu nima? — Bu stol."},{ru:"Я ви́жу дом.",uz:"Men uyni ko'ryapman.",note:"jonsiz — o'zgarmaydi"},{ru:"Я ви́жу бра́та.",uz:"Men akamni ko'ryapman.",note:"jonli м → -а"},{ru:"Он зна́ет Ива́на.",uz:"U Ivanni biladi."}],commonMistakes:[{wrong:"Что это? (mushuk haqida)",right:"Кто это?",why_uz:"Rus tilida hayvonlar jonli hisoblanadi — кто."},{wrong:"Я вижу брат",right:"Я вижу брата",why_uz:"Jonli мужской ot tushumda -а oladi."}],exercises:[{id:"m2-an-1",type:"choose",prompt:"собака (it) haqida qanday so‘raladi?",answer:"Кто это?",choices:["Кто это?","Что это?","Где это?","Как это?"],explanation_uz:"Hayvonlar ham кто."},{id:"m2-an-2",type:"choose",prompt:"машина haqida qanday so‘raladi?",answer:"Что это?",choices:["Что это?","Кто это?","Куда это?","Чей это?"],explanation_uz:"Jonsiz predmet — что."},{id:"m2-an-3",type:"fillBlank",prompt:"Я вижу брат___. (aka)",answer:"а",explanation_uz:"Jonli м ot tushumda: брата."},{id:"m2-an-4",type:"choose",prompt:"«Я вижу ...» — стол so‘zi qanday shaklda bo‘ladi?",answer:"стол (o‘zgarmaydi)",choices:["стол (o‘zgarmaydi)","стола","столу","столом"],explanation_uz:"Jonsiz м ot tushumda o'zgarmaydi: вижу стол."},{id:"m2-an-5",type:"transform",prompt:"Tushum kelishigiga qo‘ying: «Иван» (Я знаю ...)",answer:"Ивана",explanation_uz:"Jonli ism: Ивана."},{id:"m2-an-6",type:"translate",prompt:"Tarjima qiling: «Men itni ko‘ryapman» (собака)",answer:"Я вижу собаку",explanation_uz:"ж rod tushumda -у: собаку."},{id:"m2-an-7",type:"errorHunt",prompt:"Xatoni toping: «Я вижу друг»",answer:"Я вижу друга",explanation_uz:"друг jonli → друга."}]},{id:"m2-possessive",module:2,order:4,level:"A1",title:"Egalik olmoshlari",subtitle:"мой, моя, моё, мои",theory:[{heading:"Rodga moslashish",body:"Egalik olmoshi egalik qilinayotgan narsaning rodiga moslashadi (egasiga emas!): мой стол, моя книга, моё окно, мои книги.",table:[["","м","ж","с","ko'plik"],["mening","мой","моя́","моё","мои́"],["sening","твой","твоя́","твоё","твои́"],["bizning","наш","на́ша","на́ше","на́ши"],["sizning","ваш","ва́ша","ва́ше","ва́ши"]]},{heading:"O'zgarmaydiganlar",body:"его́ (uning — erkak), её (uning — ayol), их (ularning) hech qachon o'zgarmaydi: его дом, его книга, его окна."},{heading:"Savol: чей?",body:"Kimniki? savoli ham rodga moslashadi: чей (м), чья (ж), чьё (с), чьи (ko'plik). Чья это книга? — Моя."}],comparisonWithUzbek:"O'zbekcha 'mening' har doim bir xil, ruscha мой/моя/моё/мои narsaning rodiga qarab tanlanadi. Lekin его/её/их — o'zbekchadagidek o'zgarmas, bu oson.",examples:[{ru:"мой брат",uz:"mening akam"},{ru:"моя́ сестра́",uz:"mening singlim"},{ru:"моё окно́",uz:"mening derazam"},{ru:"мои́ роди́тели",uz:"mening ota-onam"},{ru:"его́ маши́на",uz:"uning mashinasi",note:"его o'zgarmaydi"},{ru:"Чья э́то кни́га? — Моя́.",uz:"Bu kimning kitobi? — Meniki."}],commonMistakes:[{wrong:"мой книга",right:"моя книга",why_uz:"книга — ж rod, shuning uchun моя."},{wrong:"евоный / еёный",right:"его / её",why_uz:"его/её ga qo'shimcha qo'shilmaydi — ular o'zgarmas."},{wrong:"наша окно",right:"наше окно",why_uz:"окно — с rod → наше."}],exercises:[{id:"m2-poss-1",type:"fillBlank",prompt:"___ книга (mening)",answer:"моя",explanation_uz:"книга ж → моя."},{id:"m2-poss-2",type:"fillBlank",prompt:"___ стол (mening)",answer:"мой",explanation_uz:"стол м → мой."},{id:"m2-poss-3",type:"fillBlank",prompt:"___ окно (bizning)",answer:"наше",explanation_uz:"окно с → наше."},{id:"m2-poss-4",type:"fillBlank",prompt:"___ родители (sening)",answer:"твои",explanation_uz:"ko'plik → твои."},{id:"m2-poss-5",type:"choose",prompt:"«uning (ayol) kitobi» qanday bo'ladi?",answer:"её книга",choices:["её книга","еёная книга","его книга","ей книга"],explanation_uz:"её o'zgarmaydi."},{id:"m2-poss-6",type:"fillBlank",prompt:"___ это машина? — Это машина брата.",answer:"Чья",explanation_uz:"машина ж → чья."},{id:"m2-poss-7",type:"errorHunt",prompt:"Xatoni toping: «Это мой сестра»",answer:"Это моя сестра",explanation_uz:"сестра ж → моя."},{id:"m2-poss-8",type:"translate",prompt:"Tarjima qiling: «Bizning uyimiz katta» (дом, большой)",answer:"Наш дом большой",explanation_uz:"дом м → наш."},{id:"m2-poss-9",type:"sentenceBuilder",prompt:"Gap tuzing: «Bu mening kitobim»",answer:"Это моя книга",tokens:["книга","моя","Это"],explanation_uz:"Это моя книга."}]}],l=[{id:"m3-cases-intro",module:3,order:1,level:"A1",title:"Kelishik tizimiga kirish",subtitle:"6 kelishik nima uchun kerak",theory:[{heading:"Kelishik nima",body:"Rus tilida ot gapdagi vazifasiga qarab oxirini o'zgartiradi. 6 kelishik bor. Har biri o'z savoliga ega — savolni bilsangiz, kelishikni topasiz.",table:[["Kelishik","Savollar","O'zbek muqobili","Misol"],["Имени́тельный (И.п)","кто? что?","bosh kelishik","Это кни́га"],["Роди́тельный (Р.п)","кого? чего?","qaratqich (-ning)","нет кни́ги"],["Да́тельный (Д.п)","кому? чему?","jo'nalish (-ga)","даю́ бра́ту"],["Вини́тельный (В.п)","кого? что?","tushum (-ni)","чита́ю кни́гу"],["Твори́тельный (Т.п)","кем? чем?","bilan / vosita","пишу́ ру́чкой"],["Предло́жный (П.п)","о ком? о чём? где?","o'rin (-da, haqida)","в кни́ге"]]},{heading:"Qanday o'rganamiz",body:"Har kelishikni alohida mavzuda, eng ko'p ishlatiladigan vaziyatlari bilan o'rganamiz. Tartib amaliy chastota bo'yicha: П.п (qayerda) → В.п (nimani) → Р.п (yo'q/kimning) → Д.п (kimga) → Т.п (nima bilan)."}],comparisonWithUzbek:"Yaxshi yangilik: o'zbek tilida ham 6 kelishik bor! Bosh=И.п, qaratqich(-ning)=Р.п, jo'nalish(-ga)=Д.п, tushum(-ni)=В.п, o'rin(-da)=П.п, chiqish(-dan)=Р.п (из/от bilan). Farq: rus tilida qo'shimcha rod va songa qarab o'zgaradi hamda ko'pincha predlog bilan keladi.",examples:[{ru:"Кни́га на столе́.",uz:"Kitob stolDA.",note:"П.п = -da"},{ru:"Я чита́ю кни́гу.",uz:"Men kitobNI o‘qiyapman.",note:"В.п = -ni"},{ru:"У меня́ нет кни́ги.",uz:"Menda kitob yo‘q.",note:"Р.п"},{ru:"Я даю́ кни́гу дру́гу.",uz:"Kitobni do‘stimGA beryapman.",note:"Д.п = -ga"},{ru:"Я пишу́ ру́чкой.",uz:"Ruchka BILAN yozyapman.",note:"Т.п"}],commonMistakes:[{wrong:"Hammasi birdan yodlashga urinish",right:"Bitta kelishik — bitta hafta",why_uz:"Kelishiklarni vaziyat bilan bog‘lab birin-ketin o‘rganish samaraliroq."},{wrong:"Я читаю книга",right:"Я читаю книгу",why_uz:"To'g'ridan-to'g'ri obyekt В.п da: -а → -у."}],exercises:[{id:"m3-intro-1",type:"choose",prompt:"Rus tilida nechta kelishik bor?",answer:"6",choices:["6","4","5","7"],explanation_uz:"6 kelishik."},{id:"m3-intro-2",type:"caseDetector",prompt:"«Книга на столе́» — столе qaysi kelishikda?",answer:"Предложный",choices:["Предложный","Именительный","Винительный","Дательный"],explanation_uz:"Joy (qayerda?) — П.п."},{id:"m3-intro-3",type:"caseDetector",prompt:"«Я читаю кни́гу» — книгу qaysi kelishikda?",answer:"Винительный",choices:["Винительный","Родительный","Дательный","Творительный"],explanation_uz:"Nimani o‘qiyapman? — В.п."},{id:"m3-intro-4",type:"choose",prompt:"O'zbekcha '-ga' qaysi kelishikka mos?",answer:"Дательный",choices:["Дательный","Родительный","Творительный","Предложный"],explanation_uz:"Кому? — kimGA? — Д.п."},{id:"m3-intro-5",type:"choose",prompt:"O'zbekcha '-da' qaysi kelishikka mos?",answer:"Предложный",choices:["Предложный","Винительный","Дательный","Именительный"],explanation_uz:"Где? — qayerDA? — П.п (в/на bilan)."},{id:"m3-intro-6",type:"caseDetector",prompt:"«Я пишу ру́чкой» — ручкой qaysi kelishikda?",answer:"Творительный",choices:["Творительный","Дательный","Предложный","Родительный"],explanation_uz:"Чем? — nima bilan? — Т.п."},{id:"m3-intro-7",type:"choose",prompt:"«нет» so‘zidan keyin qaysi kelishik keladi?",answer:"Родительный",choices:["Родительный","Винительный","Дательный","Именительный"],explanation_uz:"нет + Р.п: нет времени, нет денег."},{id:"m3-intro-8",type:"caseDetector",prompt:"«Это моя кни́га» — книга qaysi kelishikda?",answer:"Именительный",choices:["Именительный","Винительный","Родительный","Предложный"],explanation_uz:"Ega/bosh shakl — И.п."}]},{id:"m3-prepositional",module:3,order:2,level:"A1",title:"Предложный: joy va mavzu",subtitle:"в школе, на работе, о маме",theory:[{heading:"Qachon ishlatiladi",body:"Предложный падеж doim predlog bilan keladi: 1) joy — в (ichida) / на (ustida, tadbirda): в школе, на столе, на работе; 2) mavzu — о (haqida): о маме, о России. Asosiy qo'shimcha: -е.",table:[["Bosh shakl","П.п","Misol"],["шко́ла","в шко́ле","maktabda"],["стол","на столе́","stol ustida"],["Москва́","в Москве́","Moskvada"],["мо́ре","на мо́ре","dengizda"],["Росси́я","в Росси́и","-ия → -ии"],["санато́рий","в санато́рии","-ий → -ии"]]},{heading:"в yoki на?",body:"в — ichida (yopiq joy): в доме, в школе, в городе. на — yuzada yoki tadbir/ochiq joy: на столе, на улице, на работе, на уроке, на почте, на вокзале. на bilan keladigan so'zlarni yodlang: работа, урок, почта, вокзал, завод, стадион, концерт, улица."},{heading:"Istisno: -у bilan",body:"Ba'zi qisqa so'zlar в/на bilan -у oladi: в лесу́ (o'rmonda), в саду́ (bog'da), на полу́ (polda), в году́ (yilda), на мосту́ (ko'prikda)."}],comparisonWithUzbek:"O'zbekcha '-da' ga teng: maktabDA = в школе. Farq: rus tilida predlog (в/на) + oxiri -е birga ishlaydi. 'Haqida' ma'nosi ham shu kelishik: kitob haqida = о книге.",examples:[{ru:"Я живу́ в Ташке́нте.",uz:"Men Toshkentda yashayman."},{ru:"Кни́га на столе́.",uz:"Kitob stol ustida."},{ru:"Па́па на рабо́те.",uz:"Dadam ishda.",note:"работа doim на bilan"},{ru:"Мы говори́м о фи́льме.",uz:"Biz film haqida gaplashyapmiz."},{ru:"Она́ у́чится в университе́те.",uz:"U universitetda o‘qiydi."},{ru:"Де́ти гуля́ют в саду́.",uz:"Bolalar bog‘da sayr qilyapti.",note:"istisno: -у"}],commonMistakes:[{wrong:"в работе",right:"на работе",why_uz:"работа 'на' guruhidan: на работе, на работу."},{wrong:"в Москва",right:"в Москве",why_uz:"Joy bildirilganda П.п: -а → -е."},{wrong:"о Россие",right:"о России",why_uz:"-ия bilan tugagan otlar П.п da -ии: Россия → о России."},{wrong:"в лесе",right:"в лесу",why_uz:"лес istisno: в лесу́."}],exercises:[{id:"m3-pp-1",type:"fillBlank",prompt:"Я живу в Ташкент___.",answer:"е",explanation_uz:"в Ташкенте — П.п."},{id:"m3-pp-2",type:"fillBlank",prompt:"Мама ___ работе. (predlog)",answer:"на",explanation_uz:"работа → на работе."},{id:"m3-pp-3",type:"transform",prompt:"П.п ga qo‘ying: школа (в ...)",answer:"школе",explanation_uz:"в школе."},{id:"m3-pp-4",type:"transform",prompt:"П.п ga qo‘ying: Россия (в ...)",answer:"России",explanation_uz:"-ия → -ии."},{id:"m3-pp-5",type:"choose",prompt:"Qaysi predlog: «___ столе» (stol ustida)?",answer:"на",choices:["на","в","о","у"],explanation_uz:"Yuzada — на."},{id:"m3-pp-6",type:"fillBlank",prompt:"Мы говорим ___ маме. (haqida)",answer:"о",explanation_uz:"о + П.п = haqida."},{id:"m3-pp-7",type:"transform",prompt:"П.п ga qo‘ying: лес (в ...)",answer:"лесу",explanation_uz:"Istisno: в лесу́."},{id:"m3-pp-8",type:"errorHunt",prompt:"Xatoni toping: «Брат учится в университет»",answer:"Брат учится в университете",explanation_uz:"Joy — П.п: в университете."},{id:"m3-pp-9",type:"translate",prompt:"Tarjima qiling: «Kitob sumkada» (книга, сумка)",answer:"Книга в сумке",explanation_uz:"в сумке — ichida."},{id:"m3-pp-10",type:"choose",prompt:"Qaysi so'z «на» bilan keladi?",answer:"урок",choices:["урок","дом","школа","город"],explanation_uz:"на уроке — darsda."}]},{id:"m3-accusative",module:3,order:3,level:"A1",title:"Винительный: to'g'ri obyekt",subtitle:"читаю книгу, вижу брата",theory:[{heading:"Qachon ishlatiladi",body:"Ish-harakat to'g'ridan-to'g'ri o'tadigan narsa (nimani? kimni?): читать книгу, смотреть фильм, любить маму. Shuningdek yo'nalish (куда?): в школу, на работу.",table:[["Rod","O'zgarish","Misol"],["ж (-а/-я)","-у/-ю","книга → книгу, неделя → неделю"],["м jonsiz","o'zgarmaydi","вижу стол"],["м jonli","Р.п kabi: -а/-я","вижу брата"],["с","o'zgarmaydi","вижу окно"],["ko'plik jonsiz","o'zgarmaydi","вижу столы"]]},{heading:"Yo'nalish: куда?",body:"идти/ехать + в/на + В.п = qayerGA: иду в школу, еду на работу. Solishtiring: Я в школе (qayerda? П.п) — Я иду в школу (qayerga? В.п)."}],comparisonWithUzbek:"O'zbekcha '-ni' ga teng: kitobNI o'qiyapman = читаю книгу. Yana '-ga' (yo'nalish) ham shu kelishik bilan: maktabGA boryapman = иду в школу. Bitta ruscha kelishik o'zbekcha ikkita qo'shimchani qoplaydi.",examples:[{ru:"Я чита́ю кни́гу.",uz:"Men kitobni o‘qiyapman."},{ru:"Он смо́трит фильм.",uz:"U film ko‘ryapti.",note:"м jonsiz — o'zgarmadi"},{ru:"Я люблю́ ма́му.",uz:"Men onamni yaxshi ko‘raman."},{ru:"Мы ви́дим бра́та.",uz:"Biz akani ko‘ryapmiz.",note:"jonli м → -а"},{ru:"Я иду́ в шко́лу.",uz:"Men maktabga ketyapman.",note:"yo'nalish"},{ru:"Он е́дет на рабо́ту.",uz:"U ishga ketyapti."}],commonMistakes:[{wrong:"читаю книга",right:"читаю книгу",why_uz:"ж rod В.п da -у oladi."},{wrong:"Я иду в школе",right:"Я иду в школу",why_uz:"Yo'nalish (qayerga?) — В.п; joy (qayerda?) — П.п."},{wrong:"вижу брат",right:"вижу брата",why_uz:"Jonli м ot В.п da Р.п shaklini oladi."},{wrong:"люблю мама",right:"люблю маму",why_uz:"мама → маму."}],exercises:[{id:"m3-acc-1",type:"transform",prompt:"В.п ga qo‘ying: книга (читаю ...)",answer:"книгу",explanation_uz:"-а → -у."},{id:"m3-acc-2",type:"transform",prompt:"В.п ga qo‘ying: брат (вижу ...)",answer:"брата",explanation_uz:"Jonli м → -а."},{id:"m3-acc-3",type:"fillBlank",prompt:"Я люблю мам___.",answer:"у",explanation_uz:"маму."},{id:"m3-acc-4",type:"choose",prompt:"«Я смотрю ...» (фильм) — qanday shakl?",answer:"фильм (o‘zgarmaydi)",choices:["фильм (o‘zgarmaydi)","фильма","фильму","фильмом"],explanation_uz:"Jonsiz м В.п da o'zgarmaydi."},{id:"m3-acc-5",type:"fillBlank",prompt:"Я иду в школ___. (qayerga?)",answer:"у",explanation_uz:"Yo'nalish: в школу."},{id:"m3-acc-6",type:"caseDetector",prompt:"«Я в школе» va «Я иду в школу» — ikkinchisida qaysi kelishik?",answer:"Винительный",choices:["Винительный","Предложный","Дательный","Родительный"],explanation_uz:"Куда? (yo'nalish) — В.п."},{id:"m3-acc-7",type:"errorHunt",prompt:"Xatoni toping: «Он читает газета»",answer:"Он читает газету",explanation_uz:"газета → газету."},{id:"m3-acc-8",type:"translate",prompt:"Tarjima qiling: «Men akamni bilaman» (знать, брат)",answer:"Я знаю брата",explanation_uz:"Jonli м → брата."},{id:"m3-acc-9",type:"transform",prompt:"В.п ga qo‘ying: неделя (жду ...)",answer:"неделю",explanation_uz:"-я → -ю."},{id:"m3-acc-10",type:"translate",prompt:"Tarjima qiling: «U ishga ketyapti» (ехать, работа)",answer:"Он едет на работу",explanation_uz:"на работу — В.п."}]},{id:"m3-genitive",module:3,order:4,level:"A2",title:"Родительный: yo'qlik, egalik, sanoq",subtitle:"нет времени, у меня есть, два брата",theory:[{heading:"Uch asosiy vazifa",body:"1) Yo'qlik: нет + Р.п (нет времени — vaqt yo'q). 2) Egalik/mansublik: книга брата (akamning kitobi), у меня есть... 3) Sanoq: 2-4 dan keyin Р.п birlik, 5+ dan keyin Р.п ko'plik.",table:[["Rod","Р.п birlik","Misol"],["м","-а/-я","стол → стола, брат → брата"],["ж","-ы/-и","книга → книги, неделя → недели"],["с","-а/-я","окно → окна, море → моря"]]},{heading:"Sanoq qoidasi",body:"1 — И.п (один стол), 2-4 — Р.п birlik (два стола), 5-20 — Р.п ko'plik (пять столов). Bu qoida 22, 23... uchun ham: двадцать два стола.",table:[["Son","Shakl","Misol"],["1, 21, 31...","И.п birlik","один год"],["2-4, 22-24...","Р.п birlik","два го́да"],["5-20, 25-30...","Р.п ko'plik","пять лет"]]},{heading:"У меня есть...",body:"Rus tilida 'menda bor' qolipi: У + Р.п + есть + И.п: У меня есть брат. Inkori: У меня нет брата (нет + Р.п!). Olmoshlar: у меня, у тебя, у него, у неё, у нас, у вас, у них."}],comparisonWithUzbek:"O'zbekcha '-ning' va 'yo'q' konstruksiyalariga mos: 'akamNING kitobi' = книга брата (tartib teskari!), 'vaqt YO'Q' = нет времени. 'Menda ... bor' = У меня есть — bu ham o'zbekchaga juda yaqin.",examples:[{ru:"У меня́ есть брат.",uz:"Mening akam bor."},{ru:"У меня́ нет вре́мени.",uz:"Vaqtim yo‘q.",note:"нет + Р.п"},{ru:"Э́то кни́га бра́та.",uz:"Bu akamning kitobi.",note:"tartib: narsa + egasi"},{ru:"два сто́ла, пять столо́в",uz:"ikkita stol, beshta stol",note:"sanoq qoidasi"},{ru:"Мне два́дцать два го́да.",uz:"Men 22 yoshdaman.",note:"2 → года"},{ru:"стака́н воды́",uz:"bir stakan suv",note:"miqdor + Р.п"}],commonMistakes:[{wrong:"нет время",right:"нет времени",why_uz:"нет dan keyin doim Р.п: время → времени."},{wrong:"два столов",right:"два стола",why_uz:"2-4 dan keyin Р.п BIRLIK: два стола."},{wrong:"пять стола",right:"пять столов",why_uz:"5+ dan keyin Р.п KO'PLIK: пять столов."},{wrong:"У меня есть нет брата",right:"У меня нет брата",why_uz:"Inkorda 'есть' tushib qoladi."}],exercises:[{id:"m3-gen-1",type:"fillBlank",prompt:"У меня нет врем___. (время)",answer:"ени",explanation_uz:"время → времени (Р.п)."},{id:"m3-gen-2",type:"fillBlank",prompt:"два стол___",answer:"а",explanation_uz:"2-4 → Р.п birlik: стола."},{id:"m3-gen-3",type:"fillBlank",prompt:"пять стол___",answer:"ов",explanation_uz:"5+ → Р.п ko'plik: столов."},{id:"m3-gen-4",type:"transform",prompt:"Р.п ga qo‘ying: книга (нет ...)",answer:"книги",explanation_uz:"-а → -и."},{id:"m3-gen-5",type:"translate",prompt:"Tarjima qiling: «Mening singlim bor» (сестра)",answer:"У меня есть сестра",explanation_uz:"У меня есть + И.п."},{id:"m3-gen-6",type:"translate",prompt:"Tarjima qiling: «Akam yo‘q» (брат)",answer:"У меня нет брата",explanation_uz:"нет + Р.п: брата."},{id:"m3-gen-7",type:"choose",prompt:"«bu akamning mashinasi» qanday?",answer:"это машина брата",choices:["это машина брата","это брата машина","это машина брат","это брату машина"],explanation_uz:"Egalik: narsa + egasi (Р.п)."},{id:"m3-gen-8",type:"fillBlank",prompt:"Мне двадцать два год___.",answer:"а",explanation_uz:"22 → oxiri 2 → года."},{id:"m3-gen-9",type:"fillBlank",prompt:"Мне тридцать лет. — «лет» qaysi so‘zning shakli? (год/лето)",answer:"год",explanation_uz:"5+ bilan год o'rniga лет ishlatiladi."},{id:"m3-gen-10",type:"errorHunt",prompt:"Xatoni toping: «У меня нет деньги»",answer:"У меня нет денег",explanation_uz:"деньги → денег (Р.п)."},{id:"m3-gen-11",type:"translate",prompt:"Tarjima qiling: «bir stakan choy» (стакан, чай)",answer:"стакан чая",explanation_uz:"Miqdor + Р.п: чая."}]},{id:"m3-dative",module:3,order:5,level:"A2",title:"Дательный: kimga, yosh, нравится",subtitle:"даю брату, мне нравится, мне 20 лет",theory:[{heading:"Qachon ishlatiladi",body:"1) Kimga berish/aytish/yordam: даю брату, звоню маме, помогаю другу. 2) Yosh: Мне 20 лет. 3) Yoqish: Мне нравится музыка. 4) Holat: Мне холодно (menga sovuq). 5) надо/нужно/можно bilan: Мне надо идти.",table:[["Rod","Д.п","Misol"],["м","-у/-ю","брат → брату, учитель → учителю"],["ж","-е (-ии)","мама → маме, Мария → Марии"],["с","-у/-ю","окно → окну"]]},{heading:"Olmoshlar Д.п da",body:"я→мне, ты→тебе, он→ему, она→ей, мы→нам, вы→вам, они→им. Bular juda ko‘p ishlatiladi: Мне нравится. Тебе помочь? Ему 30 лет."},{heading:"нравится qolipi",body:"O'zbekcha 'menga yoqadi' bilan bir xil qurilgan: МНЕ (kimga — Д.п) нравится КНИГА (nima — И.п). Yoqayotgan narsa ko'plikda bo'lsa: нравятся: Мне нравятся эти песни."}],comparisonWithUzbek:"O'zbekcha '-ga' bilan deyarli bir xil: akamGA beryapman = даю брату, menGA yoqadi = мне нравится, menGA sovuq = мне холодно. Yosh aytish ham: 'menga 20 yosh' deyish mumkin — Мне 20 лет.",examples:[{ru:"Я даю́ кни́гу бра́ту.",uz:"Kitobni akamga beryapman."},{ru:"Мне нра́вится э́та пе́сня.",uz:"Menga bu qo‘shiq yoqadi."},{ru:"Мне два́дцать лет.",uz:"Men yigirma yoshdaman."},{ru:"Я звоню́ ма́ме.",uz:"Onamga qo‘ng‘iroq qilyapman."},{ru:"Помоги́ мне, пожа́луйста.",uz:"Iltimos, menga yordam ber."},{ru:"Ему́ хо́лодно.",uz:"Unga sovuq."}],commonMistakes:[{wrong:"Я нравлюсь музыка",right:"Мне нравится музыка",why_uz:"Yoqtiruvchi odam Д.п da (мне), yoqadigan narsa И.п da."},{wrong:"Я имею 20 лет",right:"Мне 20 лет",why_uz:"Yosh faqat Д.п bilan aytiladi."},{wrong:"звоню мама",right:"звоню маме",why_uz:"звонить + Д.п: kimGA qo'ng'iroq."},{wrong:"помогаю брата",right:"помогаю брату",why_uz:"помогать + Д.п (В.п emas!)."}],exercises:[{id:"m3-dat-1",type:"transform",prompt:"Д.п ga qo‘ying: брат (даю ...)",answer:"брату",explanation_uz:"м → -у."},{id:"m3-dat-2",type:"transform",prompt:"Д.п ga qo‘ying: мама (звоню ...)",answer:"маме",explanation_uz:"ж → -е."},{id:"m3-dat-3",type:"fillBlank",prompt:"___ нравится этот фильм. (men)",answer:"Мне",explanation_uz:"я → мне."},{id:"m3-dat-4",type:"translate",prompt:"Tarjima qiling: «Men 25 yoshdaman»",answer:"Мне двадцать пять лет",explanation_uz:"Yosh: Д.п + son + лет."},{id:"m3-dat-5",type:"choose",prompt:"она → Д.п?",answer:"ей",choices:["ей","её","ему","ней"],explanation_uz:"она → ей."},{id:"m3-dat-6",type:"errorHunt",prompt:"Xatoni toping: «Я помогаю сестра»",answer:"Я помогаю сестре",explanation_uz:"помогать + Д.п: сестре."},{id:"m3-dat-7",type:"fillBlank",prompt:"Мне нрав___ эти песни. (yoqadi)",answer:"ятся",explanation_uz:"Ko'plik narsa → нравятся."},{id:"m3-dat-8",type:"translate",prompt:"Tarjima qiling: «Unga (erkak) 30 yosh»",answer:"Ему тридцать лет",explanation_uz:"он → ему."},{id:"m3-dat-9",type:"fillBlank",prompt:"___ надо идти. (men)",answer:"Мне",explanation_uz:"надо bilan Д.п: Мне надо."},{id:"m3-dat-10",type:"caseDetector",prompt:"«Я пишу письмо другу» — другу qaysi kelishikda?",answer:"Дательный",choices:["Дательный","Винительный","Родительный","Творительный"],explanation_uz:"Kimga yozyapman? — Д.п."}]},{id:"m3-instrumental",module:3,order:6,level:"A2",title:"Творительный: bilan, kasb, vosita",subtitle:"с другом, работаю врачом, пишу ручкой",theory:[{heading:"Qachon ishlatiladi",body:"1) Birgalik: с + Т.п (с другом — do'st bilan). 2) Vosita (predlogsiz!): пишу ручкой (ruchka bilan yozaman). 3) Kasb: работать/быть/стать + Т.п: работаю врачом. 4) Ba'zi fe'llar bilan: заниматься спортом, интересоваться музыкой.",table:[["Rod","Т.п","Misol"],["м","-ом/-ем","брат → братом, учитель → учителем"],["ж","-ой/-ей","мама → мамой, неделя → неделей"],["с","-ом/-ем","окно → окном, море → морем"]]},{heading:"Olmoshlar Т.п da",body:"я→мной, ты→тобой, он→им, она→ей, мы→нами, вы→вами, они→ими. со мной — men bilan (с → со)."},{heading:"Diqqat: vosita predlogsiz",body:"O'zbekcha 'bilan' ikki xil tarjima qilinadi: odam bilan = с + Т.п (с братом), lekin asbob-vosita bilan = predlogsiz Т.п (пишу ручкой, режу ножом). 'с ручкой' deyish — 'ruchkani olib yurgan holda' degani!"}],comparisonWithUzbek:"O'zbekcha 'bilan'ga mos, lekin muhim farq bor: vosita (ruchka, pichoq) predlogsiz qo'llanadi. Kasb aytish ham shu kelishikda: 'shifokor bo'lib ishlayman' = работаю врачом.",examples:[{ru:"Я иду́ в кино́ с дру́гом.",uz:"Do‘stim bilan kinoga boryapman."},{ru:"Я пишу́ ру́чкой.",uz:"Ruchka bilan yozyapman.",note:"predlogsiz!"},{ru:"Он рабо́тает врачо́м.",uz:"U shifokor bo‘lib ishlaydi."},{ru:"Она́ ста́ла учи́телем.",uz:"U o‘qituvchi bo‘ldi."},{ru:"Я занима́юсь спо́ртом.",uz:"Men sport bilan shug‘ullanaman."},{ru:"Пойдём со мной!",uz:"Men bilan yur!"}],commonMistakes:[{wrong:"пишу с ручкой",right:"пишу ручкой",why_uz:"Vosita predlogsiz Т.п da. 'с' faqat birgalik uchun."},{wrong:"работаю врач",right:"работаю врачом",why_uz:"работать + kasb Т.п da."},{wrong:"с моя мама",right:"с моей мамой",why_uz:"с dan keyin Т.п: с мамой."},{wrong:"занимаюсь спорт",right:"занимаюсь спортом",why_uz:"заниматься + Т.п."}],exercises:[{id:"m3-ins-1",type:"transform",prompt:"Т.п ga qo‘ying: друг (иду с ...)",answer:"другом",explanation_uz:"м → -ом."},{id:"m3-ins-2",type:"transform",prompt:"Т.п ga qo‘ying: мама (говорю с ...)",answer:"мамой",explanation_uz:"ж → -ой."},{id:"m3-ins-3",type:"fillBlank",prompt:"Я пишу ручк___. (vosita)",answer:"ой",explanation_uz:"Predlogsiz: ручкой."},{id:"m3-ins-4",type:"fillBlank",prompt:"Он работает врач___.",answer:"ом",explanation_uz:"Kasb: врачом."},{id:"m3-ins-5",type:"choose",prompt:"«men bilan» ruscha qanday?",answer:"со мной",choices:["со мной","с я","с меня","со мне"],explanation_uz:"я → мной, с → со."},{id:"m3-ins-6",type:"errorHunt",prompt:"Xatoni toping: «Я режу хлеб с ножом»",answer:"Я режу хлеб ножом",explanation_uz:"Vosita predlogsiz: ножом."},{id:"m3-ins-7",type:"translate",prompt:"Tarjima qiling: «Men sport bilan shug‘ullanaman»",answer:"Я занимаюсь спортом",explanation_uz:"заниматься + Т.п."},{id:"m3-ins-8",type:"fillBlank",prompt:"Она хочет стать учител___.",answer:"ем",explanation_uz:"стать + Т.п: учителем."},{id:"m3-ins-9",type:"caseDetector",prompt:"«Мы едем с братом» — братом qaysi kelishikda?",answer:"Творительный",choices:["Творительный","Дательный","Родительный","Предложный"],explanation_uz:"с + Т.п — birgalik."},{id:"m3-ins-10",type:"translate",prompt:"Tarjima qiling: «U onasi bilan yashaydi» (жить, мама)",answer:"Он живёт с мамой",explanation_uz:"с мамой."}]},{id:"m3-cases-review",module:3,order:7,level:"A2",title:"Kelishiklar: umumiy jadval va aralash drill",subtitle:"Hammasini birlashtiramiz",theory:[{heading:"To'liq jadval (birlik)",body:"Uchta namunaviy so'z bilan barcha kelishiklar:",table:[["Kelishik","стол (м)","кни́га (ж)","окно́ (с)"],["И.п (кто/что)","стол","кни́га","окно́"],["Р.п (кого/чего)","стола́","кни́ги","окна́"],["Д.п (кому/чему)","столу́","кни́ге","окну́"],["В.п (кого/что)","стол","кни́гу","окно́"],["Т.п (кем/чем)","столо́м","кни́гой","окно́м"],["П.п (о ком/о чём)","о столе́","о кни́ге","об окне́"]]},{heading:"Kelishikni qanday topish",body:"1) Fe'l yoki predlogga qarang (нет→Р.п, помогать→Д.п, с→Т.п, в/на joy→П.п, в/на yo'nalish→В.п). 2) Savol bering (kimga? → Д.п). 3) O'zbekcha qo'shimcha bilan tekshiring (-ning→Р.п, -ga→Д.п/В.п, -ni→В.п, -da→П.п, bilan→Т.п)."}],comparisonWithUzbek:"Eslab qoling: -ning → Р.п, -ga (berish) → Д.п, -ga (borish) → в/на + В.п, -ni → В.п, -da → П.п, -dan → из/от + Р.п, bilan → с + Т.п (yoki predlogsiz vosita).",examples:[{ru:"Э́то дом. Нет до́ма. Иду́ к до́му. Ви́жу дом. Дово́лен до́мом. Говорю́ о до́ме.",uz:"Bitta so'z — olti shakl",note:"dom har kelishikda"},{ru:"Я даю́ кни́гу сестры́ бра́ту.",uz:"Singlimning kitobini akamga beryapman.",note:"Р.п + В.п + Д.п bitta gapda"}],commonMistakes:[{wrong:"Kelishikni tasodifiy tanlash",right:"Fe'l/predlogdan aniqlash",why_uz:"Har bir fe'l o'z kelishigini 'talab qiladi' — fe'l bilan birga yodlang: помогать кому, ждать кого/чего."}],exercises:[{id:"m3-rev-1",type:"caseDetector",prompt:"«У меня нет сестры́» — сестры qaysi kelishik?",answer:"Родительный",choices:["Родительный","Дательный","Винительный","Творительный"],explanation_uz:"нет + Р.п."},{id:"m3-rev-2",type:"caseDetector",prompt:"«Я звоню́ дру́гу» — другу qaysi kelishik?",answer:"Дательный",choices:["Дательный","Родительный","Предложный","Винительный"],explanation_uz:"звонить кому — Д.п."},{id:"m3-rev-3",type:"caseDetector",prompt:"«Мы говори́м о фи́льме» — фильме qaysi kelishik?",answer:"Предложный",choices:["Предложный","Творительный","Дательный","Родительный"],explanation_uz:"о + П.п."},{id:"m3-rev-4",type:"caseDetector",prompt:"«Я е́ду с бра́том» — братом qaysi kelishik?",answer:"Творительный",choices:["Творительный","Дательный","Винительный","Предложный"],explanation_uz:"с + Т.п."},{id:"m3-rev-5",type:"caseDetector",prompt:"«Он лю́бит му́зыку» — музыку qaysi kelishik?",answer:"Винительный",choices:["Винительный","Родительный","Дательный","Творительный"],explanation_uz:"любить кого/что — В.п."},{id:"m3-rev-6",type:"fillBlank",prompt:"Я читаю книг___ в библиотек___. (-у/-е)",answer:"у, е",explanation_uz:"книгу (В.п), в библиотеке (П.п)."},{id:"m3-rev-7",type:"transform",prompt:"Barcha kerakli shaklga qo‘ying: «Я даю (книга) (брат)»",answer:"Я даю книгу брату",explanation_uz:"nimani → книгу (В.п), kimga → брату (Д.п)."},{id:"m3-rev-8",type:"errorHunt",prompt:"Xatoni toping: «Я живу в Ташкент с моя семья»",answer:"Я живу в Ташкенте с моей семьёй",explanation_uz:"в Ташкенте (П.п), с моей семьёй (Т.п)."},{id:"m3-rev-9",type:"choose",prompt:"o'zbekcha '-da' → ruscha qaysi qolip?",answer:"в/на + П.п",choices:["в/на + П.п","в/на + В.п","с + Т.п","у + Р.п"],explanation_uz:"Joy: в школе, на работе."},{id:"m3-rev-10",type:"translate",prompt:"Tarjima qiling: «Onamga gul beryapman» (давать, цветы, мама)",answer:"Я даю цветы маме",explanation_uz:"цветы (В.п), маме (Д.п)."},{id:"m3-rev-11",type:"caseDetector",prompt:"«стака́н ча́я» — чая qaysi kelishik?",answer:"Родительный",choices:["Родительный","Винительный","Дательный","Именительный"],explanation_uz:"Miqdor + Р.п."},{id:"m3-rev-12",type:"transform",prompt:"«Мы е́дем на (мо́ре)» — kerakli shakl?",answer:"море",explanation_uz:"Yo'nalish В.п: с rod o'zgarmaydi — на море."}]}],m=[{id:"m4-conjugation",module:4,order:1,level:"A1",title:"I va II tuslanish",subtitle:"читать → читаю, говорить → говорю",theory:[{heading:"I tuslanish (е-tipi)",body:"Ko'pchilik -ать/-ять fe'llari: читать, работать, знать, делать, понимать, гулять.",table:[["Shaxs","чита́ть","рабо́тать"],["я","чита́ю","рабо́таю"],["ты","чита́ешь","рабо́таешь"],["он/она́","чита́ет","рабо́тает"],["мы","чита́ем","рабо́таем"],["вы","чита́ете","рабо́таете"],["они́","чита́ют","рабо́тают"]]},{heading:"II tuslanish (и-tipi)",body:"Ko'pchilik -ить fe'llari: говорить, любить, учить, смотреть (istisno -еть), слышать.",table:[["Shaxs","говори́ть","люби́ть"],["я","говорю́","люблю́"],["ты","говори́шь","лю́бишь"],["он/она́","говори́т","лю́бит"],["мы","говори́м","лю́бим"],["вы","говори́те","лю́бите"],["они́","говоря́т","лю́бят"]]},{heading:"Qanday farqlash",body:"Asosiy mo'ljal: -ить → II tuslanish (говорить), qolganlari → I tuslanish (читать). Istisnolarni yodlang: смотреть, видеть, слышать, ненавидеть — II; брить, стелить — I. любить da л qo'shiladi: люблю."}],comparisonWithUzbek:"O'zbek tilida ham fe'l shaxsga qarab o'zgaradi (o'qiyMAN, o'qiySAN, o'qiyDI) — shuning uchun bu tizim sizga tanish. Faqat qo'shimchalar boshqa va ikkita tip bor.",examples:[{ru:"Я чита́ю кни́гу.",uz:"Men kitob o‘qiyapman."},{ru:"Ты говори́шь по-ру́сски?",uz:"Sen ruscha gapirasanmi?"},{ru:"Он рабо́тает в ба́нке.",uz:"U bankda ishlaydi."},{ru:"Мы лю́бим спорт.",uz:"Biz sportni yaxshi ko‘ramiz."},{ru:"Они́ живу́т в Москве́.",uz:"Ular Moskvada yashashadi.",note:"жить: живу, живёшь..."}],commonMistakes:[{wrong:"я читать",right:"я читаю",why_uz:"Infinitiv shaxsga moslanishi shart: я читаю."},{wrong:"он говорят",right:"он говорит",why_uz:"он → -ит, они → -ят."},{wrong:"я любю",right:"я люблю",why_uz:"любить — я shaklida л orttiriladi: люблю."},{wrong:"ты читает",right:"ты читаешь",why_uz:"ты doim -шь bilan: читаешь, говоришь."}],exercises:[{id:"m4-conj-1",type:"conjugationDrill",prompt:"читать → я ...",answer:"читаю",explanation_uz:"I tuslanish: -ю."},{id:"m4-conj-2",type:"conjugationDrill",prompt:"читать → ты ...",answer:"читаешь",explanation_uz:"-ешь."},{id:"m4-conj-3",type:"conjugationDrill",prompt:"говорить → он ...",answer:"говорит",explanation_uz:"II tuslanish: -ит."},{id:"m4-conj-4",type:"conjugationDrill",prompt:"работать → мы ...",answer:"работаем",explanation_uz:"-ем."},{id:"m4-conj-5",type:"conjugationDrill",prompt:"любить → я ...",answer:"люблю",explanation_uz:"л orttiriladi: люблю."},{id:"m4-conj-6",type:"conjugationDrill",prompt:"говорить → они ...",answer:"говорят",explanation_uz:"II tuslanish они → -ят."},{id:"m4-conj-7",type:"choose",prompt:"Qaysi fe’l II tuslanishga kiradi?",answer:"смотреть",choices:["смотреть","читать","знать","гулять"],explanation_uz:"смотреть — istisno, II tuslanish: смотрю, смотришь."},{id:"m4-conj-8",type:"errorHunt",prompt:"Xatoni toping: «Ты говорит по-русски?»",answer:"Ты говоришь по-русски?",explanation_uz:"ты → говоришь."},{id:"m4-conj-9",type:"conjugationDrill",prompt:"жить → я ...",answer:"живу",explanation_uz:"жить: живу, живёшь, живёт..."},{id:"m4-conj-10",type:"translate",prompt:"Tarjima qiling: «Biz Toshkentda yashaymiz»",answer:"Мы живём в Ташкенте",explanation_uz:"мы живём."}]},{id:"m4-irregular",module:4,order:2,level:"A1",title:"Eng muhim noto'g'ri fe'llar",subtitle:"хотеть, мочь, есть, пить, идти",theory:[{heading:"хотеть (xohlamoq) — aralash tip",body:"Birlikda I tipdek, ko'plikda II tipdek tuslanadi.",table:[["я хочу́","мы хоти́м"],["ты хо́чешь","вы хоти́те"],["он хо́чет","они́ хотя́т"]]},{heading:"мочь (qila olmoq)",body:"г/ж almashinadi: я могу́, ты мо́жешь, он мо́жет, мы мо́жем, вы мо́жете, они́ мо́гут."},{heading:"есть (yemoq) va пить (ichmoq)",body:"есть: ем, ешь, ест, еди́м, еди́те, едя́т. пить: пью, пьёшь, пьёт, пьём, пьёте, пьют."},{heading:"идти (bormoq) va ехать (transportda bormoq)",body:"идти: иду́, идёшь, идёт, идём, идёте, иду́т. ехать: е́ду, е́дешь, е́дет, е́дем, е́дете, е́дут."}],comparisonWithUzbek:"Bu fe'llar eng ko'p ishlatiladiganlar — ularni alohida-alohida, qo'shiq kabi yodlab olish kerak: хочу-хочешь-хочет... O'zbek tilidagi 'yemoq/ichmoq' kabi kundalik fe'llar.",examples:[{ru:"Я хочу́ чай.",uz:"Men choy xohlayman."},{ru:"Ты мо́жешь помо́чь?",uz:"Yordam bera olasanmi?"},{ru:"Что ты ешь?",uz:"Nima yeyapsan?"},{ru:"Я пью ко́фе ка́ждое у́тро.",uz:"Har kuni ertalab kofe ichaman."},{ru:"Куда́ ты идёшь?",uz:"Qayerga ketyapsan?"}],commonMistakes:[{wrong:"я хотю",right:"я хочу",why_uz:"хотеть → хочу (т→ч)."},{wrong:"он можут",right:"он может",why_uz:"он → может, они → могут."},{wrong:"я ем (пить ma’nosida)",right:"я пью",why_uz:"есть — yemoq, пить — ichmoq."},{wrong:"я идю",right:"я иду",why_uz:"идти → иду."}],exercises:[{id:"m4-irr-1",type:"conjugationDrill",prompt:"хотеть → я ...",answer:"хочу",explanation_uz:"я хочу."},{id:"m4-irr-2",type:"conjugationDrill",prompt:"хотеть → они ...",answer:"хотят",explanation_uz:"Ko'plikda II tip: хотят."},{id:"m4-irr-3",type:"conjugationDrill",prompt:"мочь → ты ...",answer:"можешь",explanation_uz:"г→ж: можешь."},{id:"m4-irr-4",type:"conjugationDrill",prompt:"есть → я ...",answer:"ем",explanation_uz:"я ем."},{id:"m4-irr-5",type:"conjugationDrill",prompt:"пить → ты ...",answer:"пьёшь",explanation_uz:"пьёшь — ь bilan."},{id:"m4-irr-6",type:"conjugationDrill",prompt:"идти → мы ...",answer:"идём",explanation_uz:"мы идём."},{id:"m4-irr-7",type:"translate",prompt:"Tarjima qiling: «Men suv ichmoqchiman» (хотеть, пить, вода)",answer:"Я хочу пить воду",explanation_uz:"хотеть + infinitiv."},{id:"m4-irr-8",type:"errorHunt",prompt:"Xatoni toping: «Они может прийти»",answer:"Они могут прийти",explanation_uz:"они → могут."},{id:"m4-irr-9",type:"conjugationDrill",prompt:"ехать → он ...",answer:"едет",explanation_uz:"он едет."},{id:"m4-irr-10",type:"choose",prompt:"«Nima yeyapsan?» ruscha qanday?",answer:"Что ты ешь?",choices:["Что ты ешь?","Что ты есть?","Что ты едишь?","Что ты пьёшь?"],explanation_uz:"ты ешь."}]},{id:"m4-past",module:4,order:3,level:"A1",title:"O'tgan zamon",subtitle:"читал, читала, читало, читали",theory:[{heading:"Yasalishi",body:"Infinitivdan -ть olib tashlanib -л qo'shiladi. O'tgan zamon shaxsga emas, RODGA moslashadi!",table:[["Kim","Qo'shimcha","Misol"],["он (м)","-л","он чита́л"],["она́ (ж)","-ла","она́ чита́ла"],["оно́ (с)","-ло","оно́ бы́ло"],["ko'plik","-ли","они́ чита́ли"]]},{heading:"Muhim jihatlar",body:"я/ты uchun ham rod muhim: я читал (erkak), я читала (ayol). Istisnolar: идти → шёл/шла/шли, мочь → мог/могла́/могли́, есть → ел/е́ла/е́ли."}],comparisonWithUzbek:"O'zbek tilida o'tgan zamon shaxsga moslashadi (o'qiDIM, o'qiDING), rus tilida esa rodga (читал/читала). Ayol kishi o'zi haqida doim -ла bilan gapiradi: Я была дома.",examples:[{ru:"Вчера́ я чита́л кни́гу.",uz:"Kecha kitob o‘qidim. (erkak)"},{ru:"Она́ рабо́тала в шко́ле.",uz:"U maktabda ishlagan."},{ru:"Мы смотре́ли фильм.",uz:"Biz film ko‘rdik."},{ru:"Он шёл домо́й.",uz:"U uyga ketayotgan edi.",note:"идти → шёл"},{ru:"Я была́ в Москве́.",uz:"Men Moskvada bo‘lganman. (ayol)"}],commonMistakes:[{wrong:"Она читал",right:"Она читала",why_uz:"Ayol rod → -ла."},{wrong:"Они читала",right:"Они читали",why_uz:"Ko'plik → -ли."},{wrong:"Он идал",right:"Он шёл",why_uz:"идти ning o'tgan zamoni butunlay boshqa: шёл/шла/шли."}],exercises:[{id:"m4-past-1",type:"transform",prompt:"O'tgan zamonga o'tkazing: «Он читает»",answer:"Он читал",explanation_uz:"м → -л."},{id:"m4-past-2",type:"transform",prompt:"O'tgan zamonga o'tkazing: «Она работает»",answer:"Она работала",explanation_uz:"ж → -ла."},{id:"m4-past-3",type:"transform",prompt:"O'tgan zamonga o'tkazing: «Мы смотрим фильм»",answer:"Мы смотрели фильм",explanation_uz:"ko'plik → -ли."},{id:"m4-past-4",type:"fillBlank",prompt:"Вчера я (ayol) ___ дома. (быть)",answer:"была",explanation_uz:"ж → была."},{id:"m4-past-5",type:"choose",prompt:"идти fe'lining o'tgan zamoni (м)?",answer:"шёл",choices:["шёл","идал","идёл","ходил"],explanation_uz:"идти → шёл (istisno)."},{id:"m4-past-6",type:"errorHunt",prompt:"Xatoni toping: «Мама вчера читал книгу»",answer:"Мама вчера читала книгу",explanation_uz:"мама ж → читала."},{id:"m4-past-7",type:"conjugationDrill",prompt:"мочь → она ... (o‘tgan zamon)",answer:"могла",explanation_uz:"мог/могла/могли."},{id:"m4-past-8",type:"translate",prompt:"Tarjima qiling: «Biz kecha ishladik»",answer:"Мы вчера работали",explanation_uz:"работали."}]},{id:"m4-future",module:4,order:4,level:"A2",title:"Kelasi zamon",subtitle:"буду читать / прочитаю",theory:[{heading:"Ikki xil kelasi zamon",body:"1) Murakkab (НСВ): быть + infinitiv — davomli/takroriy ish: Я буду читать (o'qib o'tiraman). 2) Sodda (СВ): sovershenniy fe'lning hozirgi zamon shakli — bitta tugallangan ish: Я прочитаю (o'qib bo'laman).",table:[["Shaxs","быть","Misol"],["я","бу́ду","бу́ду чита́ть"],["ты","бу́дешь","бу́дешь чита́ть"],["он","бу́дет","бу́дет чита́ть"],["мы","бу́дем","бу́дем чита́ть"],["вы","бу́дете","бу́дете чита́ть"],["они́","бу́дут","бу́дут чита́ть"]]},{heading:"Diqqat",body:"СВ fe'l (прочитать, сделать, купить) hozirgi zamon shaklida kelajakni bildiradi: Я прочитаю завтра — ertaga o'qib bo'laman. СВ bilan буду ishlatib BO'LMAYDI: «буду прочитать» — xato!"}],comparisonWithUzbek:"O'zbekcha 'o'qiyman (ertaga)' ikkala ruscha shaklga ham to'g'ri keladi. Farq nima muhimligida: jarayon bo'lsa буду читать, natija bo'lsa прочитаю.",examples:[{ru:"За́втра я бу́ду рабо́тать.",uz:"Ertaga ishlayman (kun davomida)."},{ru:"Я прочита́ю э́ту кни́гу за́втра.",uz:"Bu kitobni ertaga o‘qib bo‘laman."},{ru:"Мы бу́дем смотре́ть фильм ве́чером.",uz:"Kechqurun film ko‘ramiz."},{ru:"Он ку́пит хлеб по́сле рабо́ты.",uz:"U ishdan keyin non sotib oladi.",note:"СВ — sodda kelasi"}],commonMistakes:[{wrong:"буду прочитать",right:"прочитаю YOKI буду читать",why_uz:"буду faqat НСВ infinitiv bilan keladi."},{wrong:"я будет",right:"я буду",why_uz:"быть tuslanadi: я буду, он будет."}],exercises:[{id:"m4-fut-1",type:"fillBlank",prompt:"Завтра мы ___ отдыхать. (быть)",answer:"будем",explanation_uz:"мы будем."},{id:"m4-fut-2",type:"choose",prompt:"Qaysi gap to'g'ri?",answer:"Я буду читать вечером",choices:["Я буду читать вечером","Я буду прочитать вечером","Я буду читаю вечером","Я читаю буду вечером"],explanation_uz:"буду + НСВ infinitiv."},{id:"m4-fut-3",type:"transform",prompt:"Kelasi zamonga o'tkazing: «Он работает»",answer:"Он будет работать",explanation_uz:"будет + infinitiv."},{id:"m4-fut-4",type:"choose",prompt:"«Ertaga sotib olaman (bitta ish, natija)» — qaysi shakl?",answer:"куплю",choices:["куплю","буду купить","покупаю","буду куплю"],explanation_uz:"СВ sodda kelasi: куплю."},{id:"m4-fut-5",type:"fillBlank",prompt:"Ты ___ дома вечером? (быть)",answer:"будешь",explanation_uz:"ты будешь."},{id:"m4-fut-6",type:"errorHunt",prompt:"Xatoni toping: «Завтра я буду сделать домашнее задание»",answer:"Завтра я сделаю домашнее задание",explanation_uz:"сделать — СВ, буду bilan kelmaydi."},{id:"m4-fut-7",type:"translate",prompt:"Tarjima qiling: «Kechqurun televizor ko‘raman (jarayon)»",answer:"Вечером я буду смотреть телевизор",explanation_uz:"Davomli ish — буду смотреть."}]},{id:"m4-aspect-intro",module:4,order:5,level:"A2",title:"Fe'l aspekti I: НСВ va СВ nima?",subtitle:"читать — прочитать",theory:[{heading:"Ikki aspekt",body:"Deyarli har bir ruscha fe'l juft bo'lib yashaydi: НСВ (несовершенный вид) — jarayon, takror, davomiylik; СВ (совершенный вид) — bitta tugallangan natija. читать (o'qish jarayoni) — прочитать (o'qib bo'lish).",table:[["НСВ (jarayon)","СВ (natija)","Ma'no"],["чита́ть","прочита́ть","o'qimoq"],["де́лать","сде́лать","qilmoq"],["писа́ть","написа́ть","yozmoq"],["покупа́ть","купи́ть","sotib olmoq"],["говори́ть","сказа́ть","gapirmoq/aytmoq"],["смотре́ть","посмотре́ть","ko'rmoq"]]},{heading:"Zamonlar bilan",body:"НСВ uchchala zamonda ham bor: читал — читаю — буду читать. СВ da hozirgi zamon YO'Q (natija hozir bo'lishi mumkin emas): прочитал — [—] — прочитаю."}],comparisonWithUzbek:"O'zbekchada bunga yaqin narsa: 'o'qiyotgan edim' (jarayon, НСВ) va 'o'qib bo'ldim / o'qib chiqdim' (natija, СВ). Ruscha СВ ko'pincha o'zbekcha '-b bo'lmoq', '-b chiqmoq', '-b qo'ymoq' ko'makchi fe'llariga mos keladi.",examples:[{ru:"Вчера́ я чита́л весь день.",uz:"Kecha kun bo‘yi o‘qidim (jarayon).",note:"НСВ"},{ru:"Вчера́ я прочита́л э́ту кни́гу.",uz:"Kecha bu kitobni o‘qib bo‘ldim.",note:"СВ — natija"},{ru:"Я ка́ждый день де́лаю заря́дку.",uz:"Har kuni badantarbiya qilaman.",note:"takror → НСВ"},{ru:"Я сде́лал дома́шнее зада́ние.",uz:"Uy vazifasini qilib bo‘ldim.",note:"СВ"}],commonMistakes:[{wrong:"Я прочитаю каждый день",right:"Я читаю каждый день",why_uz:"Takroriy ish faqat НСВ bilan."},{wrong:"Я сейчас прочитаю книгу (hozir o‘qiyapman ma’nosida)",right:"Я сейчас читаю книгу",why_uz:"СВ da hozirgi zamon yo'q — hozir bo'layotgan ish НСВ."}],exercises:[{id:"m4-asp1-1",type:"choose",prompt:"«прочитать» qaysi aspekt?",answer:"СВ (natija)",choices:["СВ (natija)","НСВ (jarayon)"],explanation_uz:"про- prefiksi natijani bildiradi."},{id:"m4-asp1-2",type:"choose",prompt:"«Har kuni» bilan qaysi aspekt keladi?",answer:"НСВ",choices:["НСВ","СВ"],explanation_uz:"Takror — doim НСВ: каждый день читаю."},{id:"m4-asp1-3",type:"choose",prompt:"делать fe’lining СВ jufti?",answer:"сделать",choices:["сделать","поделать","наделать","доделать"],explanation_uz:"делать — сделать."},{id:"m4-asp1-4",type:"choose",prompt:"говорить fe’lining СВ jufti?",answer:"сказать",choices:["сказать","поговорить","разговаривать","заговорить"],explanation_uz:"Aytmoq ma'nosida: сказать."},{id:"m4-asp1-5",type:"choose",prompt:"Qaysi aspektda hozirgi zamon YO‘Q?",answer:"СВ",choices:["СВ","НСВ"],explanation_uz:"Natija hozir sodir bo'la olmaydi."},{id:"m4-asp1-6",type:"fillBlank",prompt:"Вчера я ___ это письмо за час. (написать, м)",answer:"написал",explanation_uz:"Tugallangan natija → СВ написал."},{id:"m4-asp1-7",type:"fillBlank",prompt:"Я часто ___ письма. (писать)",answer:"пишу",explanation_uz:"часто → НСВ пишу."},{id:"m4-asp1-8",type:"choose",prompt:"покупать fe’lining СВ jufti?",answer:"купить",choices:["купить","скупать","закупать","покупить"],explanation_uz:"покупать — купить (juftlik boshqa ildizdan)."}]},{id:"m4-aspect-usage",module:4,order:6,level:"A2",title:"Fe'l aspekti II: qachon qaysi birini",subtitle:"Signal so‘zlar va vaziyatlar",theory:[{heading:"НСВ signallari",body:"часто (tez-tez), всегда (doim), обычно (odatda), каждый день (har kuni), долго (uzoq), весь день (kun bo'yi), сейчас (hozir) — bularning hammasi НСВ talab qiladi."},{heading:"СВ signallari",body:"уже (allaqachon), наконец (nihoyat), вдруг (to'satdan), быстро + natija, за час (bir soat ichida), bitta marta tugallangan ish — СВ.",table:[["Vaziyat","Aspekt","Misol"],["Jarayon hozir","НСВ","Я сейча́с чита́ю"],["Takror odat","НСВ","Я ча́сто чита́ю"],["Natija bor","СВ","Я прочита́л кни́гу"],["Davomiylik","НСВ","Я до́лго чита́л"],["Bo'lib o'tgan fakt","НСВ","Ты чита́л «Войну и мир»?"]]},{heading:"Infinitiv bilan",body:"начать/продолжать/закончить + faqat НСВ: начал читать. хотеть/мочь — ikkalasi ham mumkin, ma'noga qarab: хочу читать (o'qib o'tirishni) / хочу прочитать (o'qib bo'lishni)."}],comparisonWithUzbek:"Signal so'z usuli eng ishonchli yo'l: 'har kuni/odatda/hozir' ko'rsangiz НСВ, 'allaqachon/nihoyat/...-b bo'ldi' ko'rsangiz СВ deb o'ylang.",examples:[{ru:"Я уже́ сде́лал уро́ки.",uz:"Men darslarni allaqachon qilib bo‘ldim.",note:"уже → СВ"},{ru:"Он до́лго писа́л письмо́.",uz:"U xatni uzoq yozdi.",note:"долго → НСВ"},{ru:"Она́ начала́ учи́ть ру́сский.",uz:"U rus tilini o‘rgana boshladi.",note:"начать + НСВ"},{ru:"Вдруг он позвони́л.",uz:"To‘satdan u qo‘ng‘iroq qildi.",note:"вдруг → СВ"}],commonMistakes:[{wrong:"Я начал прочитать",right:"Я начал читать",why_uz:"начать dan keyin faqat НСВ."},{wrong:"Я долго прочитал",right:"Я долго читал",why_uz:"долго — davomiylik → НСВ."},{wrong:"Я уже делал уроки (tugatdim ma’nosida)",right:"Я уже сделал уроки",why_uz:"Natija tayyor bo'lsa СВ."}],exercises:[{id:"m4-asp2-1",type:"choose",prompt:"Я обычно ___ в 7 часов. (вставать/встать)",answer:"встаю",choices:["встаю","встану","встал","вставал"],explanation_uz:"обычно → НСВ hozirgi zamon."},{id:"m4-asp2-2",type:"choose",prompt:"Я уже ___ эту книгу. (читать/прочитать)",answer:"прочитал",choices:["прочитал","читал","читаю","буду читать"],explanation_uz:"уже + natija → СВ."},{id:"m4-asp2-3",type:"choose",prompt:"Он начал ___ письмо. (писать/написать)",answer:"писать",choices:["писать","написать"],explanation_uz:"начать + НСВ."},{id:"m4-asp2-4",type:"choose",prompt:"Мы долго ___ фильм. (смотреть/посмотреть)",answer:"смотрели",choices:["смотрели","посмотрели"],explanation_uz:"долго → НСВ."},{id:"m4-asp2-5",type:"choose",prompt:"Вдруг она ___ . (звонить/позвонить)",answer:"позвонила",choices:["позвонила","звонила"],explanation_uz:"вдруг → СВ — to'satdan bitta hodisa."},{id:"m4-asp2-6",type:"fillBlank",prompt:"Каждое утро я ___ кофе. (пить)",answer:"пью",explanation_uz:"Takror odat → НСВ пью."},{id:"m4-asp2-7",type:"errorHunt",prompt:"Xatoni toping: «Я каждый день прочитаю газету»",answer:"Я каждый день читаю газету",explanation_uz:"каждый день → НСВ."},{id:"m4-asp2-8",type:"translate",prompt:"Tarjima qiling: «Men xatni yozib bo‘ldim» (письмо)",answer:"Я написал письмо",explanation_uz:"Natija → СВ написал."}]},{id:"m4-reflexive",module:4,order:7,level:"A2",title:"Refleksiv fe'llar (-ся)",subtitle:"учиться, заниматься, нравиться",theory:[{heading:"-ся nima",body:"-ся (undoshdan keyin) / -сь (unlidan keyin) qo'shimchasi fe'lga 'o'z-o'ziga' yoki holat ma'nosini beradi: учиться (o'qimoq — o'quv yurtida), мыться (yuvinmoq), встречаться (uchrashmoq).",table:[["Shaxs","учи́ться","занима́ться"],["я","учу́сь","занима́юсь"],["ты","у́чишься","занима́ешься"],["он","у́чится","занима́ется"],["мы","у́чимся","занима́емся"],["вы","у́читесь","занима́етесь"],["они́","у́чатся","занима́ются"]]},{heading:"Eng muhim -ся fe'llari",body:"учиться (где? — o'qimoq), заниматься (чем? — shug'ullanmoq), нравиться (yoqmoq), называться (atalmoq), находиться (joylashmoq), встречаться (uchrashmoq), улыбаться (jilmaymoq), бояться (qo'rqmoq)."}],comparisonWithUzbek:"O'zbekcha '-in/-lan' nisbat qo'shimchalariga o'xshaydi: yuvmoq → yuvINmoq = мыть → мыться; tayyorlamoq → tayyorLANmoq = готовить → готовиться.",examples:[{ru:"Я учу́сь в университе́те.",uz:"Men universitetda o‘qiyman."},{ru:"Он занима́ется спо́ртом.",uz:"U sport bilan shug‘ullanadi."},{ru:"Как называ́ется э́та у́лица?",uz:"Bu ko‘cha qanday ataladi?"},{ru:"Где нахо́дится вокза́л?",uz:"Vokzal qayerda joylashgan?"},{ru:"Я бою́сь соба́к.",uz:"Men itlardan qo‘rqaman.",note:"бояться + Р.п"}],commonMistakes:[{wrong:"Я учу в университете",right:"Я учусь в университете",why_uz:"учить — o'rgatmoq/yodlamoq, учиться — o'qimoq (o'quv yurtida)."},{wrong:"он учится-ся",right:"он учится",why_uz:"-ся bir marta."},{wrong:"я занимаюсь спорт",right:"я занимаюсь спортом",why_uz:"заниматься + Т.п."}],exercises:[{id:"m4-refl-1",type:"conjugationDrill",prompt:"учиться → я ...",answer:"учусь",explanation_uz:"Unlidan keyin -сь: учусь."},{id:"m4-refl-2",type:"conjugationDrill",prompt:"учиться → он ...",answer:"учится",explanation_uz:"он учится."},{id:"m4-refl-3",type:"conjugationDrill",prompt:"заниматься → мы ...",answer:"занимаемся",explanation_uz:"занимаемся."},{id:"m4-refl-4",type:"choose",prompt:"«Universitetda o'qiyman» — qaysi fe'l?",answer:"учусь",choices:["учусь","учу","учить","учил"],explanation_uz:"O'quv yurtida o'qish — учиться."},{id:"m4-refl-5",type:"fillBlank",prompt:"Как называ___ этот фильм?",answer:"ется",explanation_uz:"называется."},{id:"m4-refl-6",type:"errorHunt",prompt:"Xatoni toping: «Я учу в школе» (o‘quvchiman ma’nosida)",answer:"Я учусь в школе",explanation_uz:"учиться kerak."},{id:"m4-refl-7",type:"translate",prompt:"Tarjima qiling: «Vokzal qayerda joylashgan?»",answer:"Где находится вокзал?",explanation_uz:"находиться — joylashmoq."},{id:"m4-refl-8",type:"fillBlank",prompt:"Дети бо___ темноты. (qo‘rqmoq)",answer:"ятся",explanation_uz:"боятся + Р.п."}]},{id:"m4-imperative",module:4,order:8,level:"A2",title:"Buyruq mayli",subtitle:"Читай! Скажите! Не забудь!",theory:[{heading:"Yasalishi",body:"они shaklidan -ют/-ят olib tashlab: unli qolsa +й (читают → читай), undosh qolsa +и (говорят → говори). вы uchun -те qo'shiladi: читайте, говорите.",table:[["Infinitiv","ты","вы"],["чита́ть","чита́й","чита́йте"],["говори́ть","говори́","говори́те"],["слу́шать","слу́шай","слу́шайте"],["писа́ть","пиши́","пиши́те"],["сказа́ть","скажи́","скажи́те"]]},{heading:"Aspekt buyruqda",body:"Iltimos/buyruq (bajarilsin) → СВ: Скажите, пожалуйста! Прочитай это! Taqiq (qilma!) → НСВ: Не говори! Не читай! Umumiy taklif → НСВ: Заходите! (Kiring!)"}],comparisonWithUzbek:"O'zbekcha 'qil!/qiling!' ga mos: ты → -й/-и (qil), вы → -йте/-ите (qiling). Taqiqda НСВ ishlatilishi yangi qoida: 'Не опаздывай!' (Kechikma!).",examples:[{ru:"Скажи́те, пожа́луйста, где метро́?",uz:"Ayting, iltimos, metro qayerda?"},{ru:"Слу́шай внима́тельно!",uz:"Diqqat bilan eshit!"},{ru:"Не забу́дь ключи́!",uz:"Kalitlarni unutma!"},{ru:"Заходи́те, пожа́луйста!",uz:"Kiring, iltimos!"},{ru:"Дава́й пойдём в кино́!",uz:"Kel, kinoga boraylik!",note:"давай + kelasi/infinitiv"}],commonMistakes:[{wrong:"Говорите мне (bir do‘stga)",right:"Скажи мне",why_uz:"Bir tanish odamga ты shakli: скажи."},{wrong:"Не скажи никому",right:"Не говори никому",why_uz:"Taqiq → НСВ: не говори."},{wrong:"Читать это!",right:"Читай это! / Прочитай это!",why_uz:"Buyruqda maxsus shakl kerak, infinitiv emas."}],exercises:[{id:"m4-imp-1",type:"transform",prompt:"Buyruq shakliga (ты): читать",answer:"читай",explanation_uz:"читают → чита + й."},{id:"m4-imp-2",type:"transform",prompt:"Buyruq shakliga (вы): говорить",answer:"говорите",explanation_uz:"говори + те."},{id:"m4-imp-3",type:"transform",prompt:"Buyruq shakliga (ты): писать",answer:"пиши",explanation_uz:"пишут → пиш + и."},{id:"m4-imp-4",type:"choose",prompt:"«Kechikma!» qanday aytiladi?",answer:"Не опаздывай!",choices:["Не опаздывай!","Не опоздай!","Не опоздать!","Не опаздываешь!"],explanation_uz:"Taqiq → НСВ buyruq."},{id:"m4-imp-5",type:"fillBlank",prompt:"___ , пожалуйста, где банк? (сказать, вы)",answer:"Скажите",explanation_uz:"Iltimos → СВ: Скажите."},{id:"m4-imp-6",type:"translate",prompt:"Tarjima qiling: «Eshiting, iltimos!» (слушать)",answer:"Слушайте, пожалуйста!",explanation_uz:"слушайте."},{id:"m4-imp-7",type:"errorHunt",prompt:"Xatoni toping: «Не покупай! → Не купи!» qaysi to‘g‘ri taqiq?",answer:"Не покупай!",explanation_uz:"Taqiqda НСВ: не покупай."},{id:"m4-imp-8",type:"translate",prompt:"Tarjima qiling: «Kel, choy ichaylik!» (давать, пить, чай)",answer:"Давай выпьем чай!",explanation_uz:"Давай + СВ kelasi: выпьем."}],miniDialogue:[{speaker:"A",ru:"Извините, скажите, пожалуйста, где аптека?",uz:"Kechirasiz, ayting, iltimos, dorixona qayerda?"},{speaker:"B",ru:"Идите прямо, потом поверните направо.",uz:"To‘g‘riga yuring, keyin o‘ngga buriling."},{speaker:"A",ru:"Спасибо большое!",uz:"Katta rahmat!"},{speaker:"B",ru:"Пожалуйста! Не за что.",uz:"Marhamat! Arzimaydi."}]}],h=[{id:"m5-idti-khodit",module:5,order:1,level:"A2",title:"идти — ходить, ехать — ездить",subtitle:"Bir yo'nalish va ko'p yo'nalish",theory:[{heading:"Ikki guruh",body:"Rus tilida 'bormoq' ikki fe'l bilan aytiladi: идти — HOZIR bitta yo'nalishda ketyapti; ходить — takror qatnaydi yoki borib-keladi. Xuddi shunday transportda: ехать (hozir ketyapti) — ездить (qatnaydi).",table:[["Vaziyat","Piyoda","Transportda"],["Hozir, bir yo'nalish","иду́","е́ду"],["Takror / borib-kelish","хожу́","е́зжу"],["Misol 1","Я иду́ в шко́лу (hozir)","Я е́ду на рабо́ту (hozir)"],["Misol 2","Я хожу́ в шко́лу ка́ждый день","Я е́зжу на рабо́ту на метро́"]]},{heading:"ходить tuslanishi",body:"хожу́, хо́дишь, хо́дит, хо́дим, хо́дите, хо́дят. ездить: е́зжу, е́здишь, е́здит... идти: иду́, идёшь... ехать: е́ду, е́дешь..."},{heading:"O'tgan zamonda",body:"ходил = borib keldi (u yerda bo'lib qaytdi): Вчера я ходил в кино (kinoga borib keldim). шёл = ketayotgan edi (jarayon): Когда я шёл домой, я встретил друга."}],comparisonWithUzbek:"O'zbekcha 'boryapman' (hozir) = иду/еду, 'boraman/qatnayman' (har kuni) = хожу/езжу, 'borib keldim' = ходил/ездил. Piyoda yoki transport farqi ham majburiy: yayov → идти/ходить, mashina-metro-avtobus → ехать/ездить.",examples:[{ru:"Я иду́ в магази́н.",uz:"Men do‘konga ketyapman (hozir, piyoda)."},{ru:"Я хожу́ в спортза́л три ра́за в неде́лю.",uz:"Sportzalga haftada uch marta qatnayman."},{ru:"Мы е́дем в Самарка́нд.",uz:"Biz Samarqandga ketyapmiz (transportda)."},{ru:"Он е́здит на рабо́ту на авто́бусе.",uz:"U ishga avtobusda qatnaydi."},{ru:"Вчера́ я ходи́л к врачу́.",uz:"Kecha shifokorga borib keldim."}],commonMistakes:[{wrong:"Я иду в школу каждый день",right:"Я хожу в школу каждый день",why_uz:"Takror ish → ходить."},{wrong:"Я еду на работу пешком",right:"Я иду на работу пешком",why_uz:"Piyoda → идти; ехать faqat transport."},{wrong:"Вчера я шёл в кино (borib keldim ma’nosida)",right:"Вчера я ходил в кино",why_uz:"Borib-qaytish fakti → ходил."}],exercises:[{id:"m5-ik-1",type:"choose",prompt:"Я сейчас ___ в школу. (piyoda)",answer:"иду",choices:["иду","хожу","еду","езжу"],explanation_uz:"Hozir bitta yo'nalish, piyoda → иду."},{id:"m5-ik-2",type:"choose",prompt:"Я ___ в бассейн каждую субботу.",answer:"хожу",choices:["хожу","иду","еду","шёл"],explanation_uz:"Takror → хожу."},{id:"m5-ik-3",type:"choose",prompt:"Мы ___ в Москву на поезде. (hozir)",answer:"едем",choices:["едем","идём","ездим","ходим"],explanation_uz:"Transport + hozir → едем."},{id:"m5-ik-4",type:"choose",prompt:"Он ___ на работу на метро каждый день.",answer:"ездит",choices:["ездит","едет","ходит","идёт"],explanation_uz:"Transport + takror → ездит."},{id:"m5-ik-5",type:"choose",prompt:"Вчера я ___ в театр. (borib keldim)",answer:"ходил",choices:["ходил","шёл","иду","хожу"],explanation_uz:"Borib-qaytish fakti → ходил."},{id:"m5-ik-6",type:"choose",prompt:"Когда я ___ домой, начался дождь.",answer:"шёл",choices:["шёл","ходил","иду","хожу"],explanation_uz:"Jarayon o'tgan zamonda → шёл."},{id:"m5-ik-7",type:"conjugationDrill",prompt:"ходить → я ...",answer:"хожу",explanation_uz:"д→ж: хожу."},{id:"m5-ik-8",type:"conjugationDrill",prompt:"ездить → я ...",answer:"езжу",explanation_uz:"езжу."},{id:"m5-ik-9",type:"translate",prompt:"Tarjima qiling: «Men universitetga avtobusda qatnayman»",answer:"Я езжу в университет на автобусе",explanation_uz:"takror + transport → езжу."},{id:"m5-ik-10",type:"errorHunt",prompt:"Xatoni toping: «Я еду в школу пешком каждый день»",answer:"Я хожу в школу пешком каждый день",explanation_uz:"Piyoda + takror → хожу."}]},{id:"m5-other-pairs",module:5,order:2,level:"A2",title:"Boshqa harakat fe'l juftlari",subtitle:"бежать/бегать, лететь/летать, нести/носить",theory:[{heading:"Asosiy juftliklar",body:"Hammasi bir xil printsip: birinchisi — hozir bir yo'nalishda, ikkinchisi — takror/ko'p yo'nalishda.",table:[["Bir yo'nalish","Ko'p yo'nalish","Ma'no"],["бежа́ть","бе́гать","yugurmoq"],["лете́ть","лета́ть","uchmoq"],["плыть","пла́вать","suzmoq"],["нести́","носи́ть","olib bormoq (qo‘lda)"],["везти́","вози́ть","olib bormoq (transportda)"],["вести́","води́ть","boshlab bormoq / haydamoq"]]},{heading:"Misollar bilan",body:"Я бегу на работу (kechikyapman — hozir yuguryapman). Я бегаю по утрам (har kuni ertalab yuguraman). Самолёт летит в Москву (hozir). Я часто летаю в Москву (tez-tez)."}],comparisonWithUzbek:"O'zbekcha 'yuguryapman' vs 'yuguraman (odat)' farqiga mos. носить yana 'kiyib yurmoq' ma'nosida ham ishlatiladi: Она носит очки — U ko'zoynak taqadi.",examples:[{ru:"Я бегу́ на авто́бус!",uz:"Avtobusga yuguryapman!"},{ru:"Я бе́гаю ка́ждое у́тро.",uz:"Har kuni ertalab yuguraman."},{ru:"Самолёт лети́т в Ташке́нт.",uz:"Samolyot Toshkentga uchyapti."},{ru:"Она́ но́сит очки́.",uz:"U ko‘zoynak taqib yuradi.",note:"kiyim/taqinchoq — doim носить"},{ru:"Он во́дит маши́ну.",uz:"U mashina haydaydi."}],commonMistakes:[{wrong:"Я бегаю на автобус (hozir)",right:"Я бегу на автобус",why_uz:"Hozir bitta yo'nalish → бегу."},{wrong:"Она несёт очки (taqadi ma’nosida)",right:"Она носит очки",why_uz:"Kiyib/taqib yurish — носить."}],exercises:[{id:"m5-op-1",type:"choose",prompt:"Смотри! Птица ___ . (uchyapti)",answer:"летит",choices:["летит","летает","лечу","летал"],explanation_uz:"Hozir, bir yo'nalish → летит."},{id:"m5-op-2",type:"choose",prompt:"Я ___ по утрам в парке.",answer:"бегаю",choices:["бегаю","бегу","бежал","бежит"],explanation_uz:"Odat → бегаю."},{id:"m5-op-3",type:"choose",prompt:"Она ___ очки.",answer:"носит",choices:["носит","несёт","возит","водит"],explanation_uz:"Taqib yurish → носит."},{id:"m5-op-4",type:"choose",prompt:"Куда ты ___ эту сумку? (hozir, qo‘lda)",answer:"несёшь",choices:["несёшь","носишь","везёшь","водишь"],explanation_uz:"Hozir qo'lda olib ketyapti → несёшь."},{id:"m5-op-5",type:"choose",prompt:"Папа ___ детей в школу на машине каждый день.",answer:"возит",choices:["возит","везёт","носит","водит"],explanation_uz:"Transportda + takror → возит."},{id:"m5-op-6",type:"choose",prompt:"«U mashina hayday oladi» — qaysi fe’l?",answer:"водит",choices:["водит","ведёт","возит","везёт"],explanation_uz:"водить машину — mashina haydamoq."},{id:"m5-op-7",type:"translate",prompt:"Tarjima qiling: «Men suzishni bilaman / suzaman» (umuman)",answer:"Я плаваю",explanation_uz:"Umumiy qobiliyat → ko'p yo'nalishli плавать."},{id:"m5-op-8",type:"errorHunt",prompt:"Xatoni toping: «Я часто лечу в Москву»",answer:"Я часто летаю в Москву",explanation_uz:"часто → летаю."}]},{id:"m5-prefixes",module:5,order:3,level:"A2",title:"Prefiksli harakat fe'llari",subtitle:"прийти, уйти, выйти, перейти",theory:[{heading:"Prefiks = yo‘nalish",body:"идти/ехать ga prefiks qo'shilsa, harakat yo'nalishi aniqlashadi va fe'l СВ bo'ladi.",table:[["Prefiks","Ma'no","Misol"],["при-","kelmoq","прийти́, прие́хать — Он пришёл домо́й"],["у-","ketib qolmoq","уйти́, уе́хать — Она́ ушла́"],["в-/во-","kirmoq","войти́ — Войди́те!"],["вы-","chiqmoq","вы́йти — Он вы́шел из до́ма"],["пере-","o'tmoq (narigi tomonga)","перейти́ у́лицу"],["до-","yetib bormoq","дойти́ до це́нтра"],["за-","kirib o'tmoq","зайти́ к дру́гу"],["по-","boshlamoq/jo‘namoq","пойти́ — Пошли́!"]]},{heading:"Predloglar bilan mosligi",body:"при- + в/на/к, у- + из/с/от, вы- + из, до- + до: Он пришёл В школу. Он ушёл ИЗ школы. Я дошёл ДО площади. Prefiks va predlog ko'pincha juft ishlaydi."}],comparisonWithUzbek:"O'zbekcha ko'makchi fe'llarga juda o'xshash: kirIB bormoq=зайти, chiqIB ketmoq=выйти, yetIB bormoq=дойти, o'tIB olmoq=перейти. Prefiks o'zbek tilidagi ko'makchi fe'l vazifasini bajaradi.",examples:[{ru:"Он пришёл домо́й в семь часо́в.",uz:"U uyga soat yettida keldi."},{ru:"Она́ ушла́ с рабо́ты.",uz:"U ishdan ketib qoldi."},{ru:"Вы́йдите на сле́дующей остано́вке?",uz:"Keyingi bekatda tushasizmi?"},{ru:"Как перейти́ у́лицу?",uz:"Ko‘chadan qanday o‘tsa bo‘ladi?"},{ru:"Зайди́ ко мне ве́чером.",uz:"Kechqurun menikiga kirib o‘t."},{ru:"Пошли́ в кино́!",uz:"Yur, kinoga!"}],commonMistakes:[{wrong:"Он пришёл из дома (uyga keldi ma’nosida)",right:"Он пришёл домой",why_uz:"при- kelish nuqtasi bilan: домой/в школу."},{wrong:"Я выйду из автобуса на остановке (told to wait?)",right:"to'g'ri, lekin выйти + из",why_uz:"вы- doim из bilan: выйти из дома."},{wrong:"уйти в школу",right:"уйти из школы / пойти в школу",why_uz:"у- 'ketib qolish' — qayerDAN ekanini bildiradi."}],exercises:[{id:"m5-pre-1",type:"choose",prompt:"«U keldi» qaysi prefiks?",answer:"пришёл",choices:["пришёл","ушёл","вышел","перешёл"],explanation_uz:"при- = kelish."},{id:"m5-pre-2",type:"choose",prompt:"«U ketib qoldi (ayol)» qanday?",answer:"ушла",choices:["ушла","пришла","вошла","зашла"],explanation_uz:"у- = ketish."},{id:"m5-pre-3",type:"fillBlank",prompt:"Он ___шел из комнаты. (chiqdi)",answer:"вы",explanation_uz:"вышел из — chiqdi."},{id:"m5-pre-4",type:"fillBlank",prompt:"Как ___йти улицу? (o‘tmoq)",answer:"пере",explanation_uz:"перейти улицу."},{id:"m5-pre-5",type:"choose",prompt:"«Yetib bordim» qanday?",answer:"дошёл",choices:["дошёл","зашёл","пошёл","отошёл"],explanation_uz:"до- = yetib borish."},{id:"m5-pre-6",type:"choose",prompt:"вы- prefiksi qaysi predlog bilan keladi?",answer:"из",choices:["из","в","к","до"],explanation_uz:"выйти из дома."},{id:"m5-pre-7",type:"translate",prompt:"Tarjima qiling: «Kechqurun do‘stimnikiga kirib o‘taman» (зайти, друг)",answer:"Вечером я зайду к другу",explanation_uz:"зайти к + Д.п."},{id:"m5-pre-8",type:"errorHunt",prompt:"Xatoni toping: «Он пришёл из школу»",answer:"Он пришёл из школы",explanation_uz:"из + Р.п: из школы."},{id:"m5-pre-9",type:"choose",prompt:"«Ketdik!» (taklif) qanday aytiladi?",answer:"Пошли!",choices:["Пошли!","Пришли!","Ушли!","Зашли!"],explanation_uz:"Пошли! / Пойдём! — yur, ketdik."}]},{id:"m5-transport",module:5,order:4,level:"A2",title:"Transport bilan gaplar",subtitle:"на автобусе, на метро, пешком",theory:[{heading:"на + П.п",body:"Transport vositasi на + П.п bilan: на автобусе, на машине, на метро, на поезде, на такси, на велосипеде. Piyoda — пешком (predlogsiz ravish).",table:[["Vosita","Ruscha","Misol"],["avtobusda","на авто́бусе","Я е́ду на авто́бусе"],["mashinada","на маши́не","Мы е́дем на маши́не"],["metroda","на метро́","metro o'zgarmaydi"],["poyezdda","на по́езде","Он е́дет на по́езде"],["piyoda","пешко́м","Я иду́ пешко́м"]]},{heading:"Qancha vaqt ketadi",body:"Yo'l vaqti: До центра 20 минут на метро (Markazgacha metroda 20 daqiqa). Дорога занимает час (Yo'l bir soat oladi)."}],comparisonWithUzbek:"O'zbekcha 'avtobusDA' = на автобусе — bu yerda ruscha на + П.п aynan '-da' ga mos. 'Piyoda' uchun esa alohida so'z: пешком.",examples:[{ru:"Я е́зжу на рабо́ту на метро́.",uz:"Ishga metroda qatnayman."},{ru:"Мы пое́дем туда́ на такси́.",uz:"U yerga taksida boramiz."},{ru:"Идти́ пешко́м 10 мину́т.",uz:"Piyoda 10 daqiqa."},{ru:"Ско́лько вре́мени е́хать до аэропо́рта?",uz:"Aeroportgacha qancha vaqt yuriladi?"}],commonMistakes:[{wrong:"ехать с автобусом",right:"ехать на автобусе",why_uz:"Transport — на + П.п, с bilan emas."},{wrong:"идти на пешком",right:"идти пешком",why_uz:"пешком predlogsiz."},{wrong:"на метре",right:"на метро",why_uz:"метро o'zgarmas so'z."}],exercises:[{id:"m5-tr-1",type:"fillBlank",prompt:"Я еду на работу ___ автобусе.",answer:"на",explanation_uz:"на + П.п."},{id:"m5-tr-2",type:"transform",prompt:"Kerakli shaklga: «Я еду на (машина)»",answer:"машине",explanation_uz:"на машине."},{id:"m5-tr-3",type:"choose",prompt:"«piyoda» ruscha qanday?",answer:"пешком",choices:["пешком","на ногах","с ногами","ножно"],explanation_uz:"идти пешком."},{id:"m5-tr-4",type:"choose",prompt:"metro bilan qaysi shakl?",answer:"на метро",choices:["на метро","на метре","в метро (transport sifatida)","с метро"],explanation_uz:"метро o'zgarmaydi: на метро."},{id:"m5-tr-5",type:"translate",prompt:"Tarjima qiling: «Biz Samarqandga poyezdda boramiz»",answer:"Мы поедем в Самарканд на поезде",explanation_uz:"на поезде."},{id:"m5-tr-6",type:"errorHunt",prompt:"Xatoni toping: «Я еду домой с такси»",answer:"Я еду домой на такси",explanation_uz:"на такси."}],miniDialogue:[{speaker:"A",ru:"Как ты ездишь на работу?",uz:"Ishga qanday qatnaysan?"},{speaker:"B",ru:"Обычно на метро, это быстро.",uz:"Odatda metroda, bu tez."},{speaker:"A",ru:"А сколько времени ехать?",uz:"Qancha vaqt yuriladi?"},{speaker:"B",ru:"Минут двадцать. А потом я иду пешком пять минут.",uz:"Yigirma daqiqacha. Keyin besh daqiqa piyoda yuraman."}]}],u=[{id:"m6-agreement",module:6,order:1,level:"A2",title:"Sifat moslashuvi",subtitle:"новый, новая, новое, новые",theory:[{heading:"Rod va songa moslashish",body:"Sifat doim o'zi aniqlayotgan otga moslashadi: rod, son va kelishikda.",table:[["Rod","Qo'shimcha","Misol"],["м","-ый/-ий/-ой","но́вый дом, си́ний костю́м, большо́й го́род"],["ж","-ая/-яя","но́вая кни́га, си́няя ру́чка"],["с","-ое/-ее","но́вое окно́, си́нее мо́ре"],["ko'plik","-ые/-ие","но́вые дома́, си́ние ру́чки"]]},{heading:"Imlo qoidalari",body:"г, к, х, ж, ш, ч, щ dan keyin ы emas и: русский, хороший, большие. Urg'u oxirida bo'lsa м rod -ой: большой, молодой."},{heading:"Kelishiklarda",body:"Sifat ot bilan birga turlanadi: новый дом → в новом доме → около нового дома → новому дому. ж rod: новая → новую (В.п) → новой (Р/Д/Т/П)."}],comparisonWithUzbek:"O'zbek tilida sifat o'zgarmaydi: 'yangi uy, yangi kitob, yangi uylar'. Rus tilida esa har safar moslashadi — bu doimiy mashq talab qiladigan odat.",examples:[{ru:"но́вый телефо́н",uz:"yangi telefon"},{ru:"кра́сная маши́на",uz:"qizil mashina"},{ru:"вку́сное я́блоко",uz:"mazali olma"},{ru:"интере́сные кни́ги",uz:"qiziqarli kitoblar"},{ru:"Я живу́ в большо́м го́роде.",uz:"Men katta shaharda yashayman.",note:"П.п: -ом"},{ru:"Я чита́ю интере́сную кни́гу.",uz:"Qiziqarli kitob o‘qiyapman.",note:"В.п: -ую"}],commonMistakes:[{wrong:"новый книга",right:"новая книга",why_uz:"книга ж → новая."},{wrong:"красная яблоко",right:"красное яблоко",why_uz:"яблоко с → красное."},{wrong:"большый",right:"большой",why_uz:"Urg'u oxirida → -ой; ж/ш dan keyin imlo."},{wrong:"русскые",right:"русские",why_uz:"к dan keyin и."}],exercises:[{id:"m6-agr-1",type:"fillBlank",prompt:"нов___ книга",answer:"ая",explanation_uz:"ж → новая."},{id:"m6-agr-2",type:"fillBlank",prompt:"нов___ дом",answer:"ый",explanation_uz:"м → новый."},{id:"m6-agr-3",type:"fillBlank",prompt:"нов___ окно",answer:"ое",explanation_uz:"с → новое."},{id:"m6-agr-4",type:"fillBlank",prompt:"нов___ машины",answer:"ые",explanation_uz:"ko'plik → новые."},{id:"m6-agr-5",type:"choose",prompt:"To'g'ri birikmani tanlang:",answer:"большой город",choices:["большой город","большая город","большое город","большый город"],explanation_uz:"город м, urg‘u oxirida → большой."},{id:"m6-agr-6",type:"transform",prompt:"Moslang: «Я читаю (интересный) книгу»",answer:"интересную",explanation_uz:"В.п ж → -ую."},{id:"m6-agr-7",type:"transform",prompt:"Moslang: «Мы живём в (новый) доме»",answer:"новом",explanation_uz:"П.п м → -ом."},{id:"m6-agr-8",type:"errorHunt",prompt:"Xatoni toping: «У неё красивая глаза»",answer:"У неё красивые глаза",explanation_uz:"глаза ko'plik → красивые."},{id:"m6-agr-9",type:"translate",prompt:"Tarjima qiling: «mazali choy» (вкусный, чай)",answer:"вкусный чай",explanation_uz:"чай м → вкусный."},{id:"m6-agr-10",type:"fillBlank",prompt:"син___ море",answer:"ее",explanation_uz:"Yumshoq turdagi sifat с → синее."}]},{id:"m6-short-form",module:6,order:2,level:"A2",title:"Qisqa shakl: рад, готов, должен",subtitle:"Я рад. Она готова. Мы должны.",theory:[{heading:"Qisqa shakl nima",body:"Ba'zi sifatlar kesim vazifasida qisqa shaklda ishlatiladi: готов (tayyor), рад (xursand), занят (band), болен (kasal), должен (kerak/qarzdor), нужен (kerak), свободен (bo'sh).",table:[["","м","ж","с","ko'plik"],["tayyor","гото́в","гото́ва","гото́во","гото́вы"],["band","за́нят","занята́","за́нято","за́няты"],["kerak (shaxs)","до́лжен","должна́","должно́","должны́"],["xursand","рад","ра́да","ра́до","ра́ды"]]},{heading:"должен + infinitiv",body:"Majburiyat: Я должен работать (ishlashim kerak). Rodga moslashadi: Она должна идти. Мы должны учиться."},{heading:"нужен qolipi",body:"Kerak bo'lgan NARSA ega bo'ladi: Мне нужен телефон (м), Мне нужна ручка (ж), Мне нужно время (с), Мне нужны деньги (ko'plik)."}],comparisonWithUzbek:"'Men ishlashim kerak' = Я должен работать (kim kerakligi — rodda). 'Menga telefon kerak' = Мне нужен телефон — bu yerda нужен telefonga (narsaga) moslashadi, o'zbekchadagidek o'zgarmas emas.",examples:[{ru:"Я гото́в.",uz:"Men tayyorman."},{ru:"Она́ за́нята.",uz:"U band."},{ru:"Мы должны́ мно́го рабо́тать.",uz:"Biz ko‘p ishlashimiz kerak."},{ru:"Мне ну́жен слова́рь.",uz:"Menga lug‘at kerak."},{ru:"Мне нужна́ по́мощь.",uz:"Menga yordam kerak."},{ru:"Рад познако́миться!",uz:"Tanishganimdan xursandman!"}],commonMistakes:[{wrong:"Она должен идти",right:"Она должна идти",why_uz:"должен rodga moslashadi."},{wrong:"Мне нужен помощь",right:"Мне нужна помощь",why_uz:"помощь ж → нужна."},{wrong:"Я есть готовый",right:"Я готов",why_uz:"Kesim vazifasida qisqa shakl."}],exercises:[{id:"m6-sf-1",type:"fillBlank",prompt:"Она готов___ к экзамену.",answer:"а",explanation_uz:"ж → готова."},{id:"m6-sf-2",type:"fillBlank",prompt:"Мы должн___ помочь.",answer:"ы",explanation_uz:"ko'plik → должны."},{id:"m6-sf-3",type:"choose",prompt:"Мне ___ ручка. (kerak)",answer:"нужна",choices:["нужна","нужен","нужно","нужны"],explanation_uz:"ручка ж → нужна."},{id:"m6-sf-4",type:"choose",prompt:"Мне ___ деньги.",answer:"нужны",choices:["нужны","нужен","нужна","нужно"],explanation_uz:"деньги ko'plik → нужны."},{id:"m6-sf-5",type:"translate",prompt:"Tarjima qiling: «Men ketishim kerak» (erkak)",answer:"Я должен идти",explanation_uz:"должен + infinitiv."},{id:"m6-sf-6",type:"errorHunt",prompt:"Xatoni toping: «Извини, я занятый»",answer:"Извини, я занят",explanation_uz:"Kesimda qisqa shakl: занят."},{id:"m6-sf-7",type:"fillBlank",prompt:"Мне нужн___ время.",answer:"о",explanation_uz:"время с → нужно."},{id:"m6-sf-8",type:"translate",prompt:"Tarjima qiling: «U (ayol) band»",answer:"Она занята",explanation_uz:"занята."}]},{id:"m6-comparative",module:6,order:3,level:"A2",title:"Qiyosiy daraja",subtitle:"больше, лучше, интереснее",theory:[{heading:"Yasalishi",body:"Oddiy usul: asos + -ее: интересный → интереснее, красивый → красивее. Yoki более + sifat: более интересный.",table:[["Sifat","Qiyosiy","Ma'no"],["хоро́ший","лу́чше","yaxshiroq"],["плохо́й","ху́же","yomonroq"],["большо́й","бо́льше","kattaroq/ko‘proq"],["ма́ленький","ме́ньше","kichikroq/kamroq"],["ста́рый","ста́рше","kattaroq (yosh)"],["молодо́й","моло́же","yoshroq"],["дорого́й","доро́же","qimmatroq"],["дешёвый","деше́вле","arzonroq"]]},{heading:"Solishtirish: чем yoki Р.п",body:"Ikki usul: 1) чем bilan: Москва больше, чем Ташкент. 2) Р.п bilan: Москва больше Ташкента. Ikkalasi ham to'g'ri."}],comparisonWithUzbek:"O'zbekcha '-roq' ga mos: kattaROQ = больше, yaxshiROQ = лучше. 'X dan kattaroq' = больше, чем X yoki больше X-a (Р.п) — '-dan' aynan Р.п ga mos keladi.",examples:[{ru:"Э́тот фильм интере́снее.",uz:"Bu film qiziqarliroq."},{ru:"Сего́дня тепле́е, чем вчера́.",uz:"Bugun kechagidan iliqroq."},{ru:"Брат ста́рше меня́.",uz:"Akam mendan katta.",note:"Р.п usuli"},{ru:"Э́то сто́ит доро́же.",uz:"Bu qimmatroq turadi."},{ru:"Говори́ гро́мче!",uz:"Balandroq gapir!"}],commonMistakes:[{wrong:"более лучше",right:"лучше",why_uz:"более maxsus shakllar bilan qo'shilmaydi."},{wrong:"хорошее (yaxshiroq ma’nosida)",right:"лучше",why_uz:"хороший ning qiyosiy darajasi maxsus: лучше."},{wrong:"старше чем меня",right:"старше меня / старше, чем я",why_uz:"чем dan keyin И.п, чем siz Р.п."}],exercises:[{id:"m6-cmp-1",type:"transform",prompt:"Qiyosiy daraja: хороший",answer:"лучше",explanation_uz:"Maxsus shakl."},{id:"m6-cmp-2",type:"transform",prompt:"Qiyosiy daraja: большой",answer:"больше",explanation_uz:"больше."},{id:"m6-cmp-3",type:"transform",prompt:"Qiyosiy daraja: интересный",answer:"интереснее",explanation_uz:"-ее bilan."},{id:"m6-cmp-4",type:"choose",prompt:"Akam mendan katta: «Брат ___ меня»",answer:"старше",choices:["старше","старее","более старый","старший"],explanation_uz:"старше + Р.п."},{id:"m6-cmp-5",type:"transform",prompt:"Qiyosiy daraja: дорогой",answer:"дороже",explanation_uz:"г→ж: дороже."},{id:"m6-cmp-6",type:"errorHunt",prompt:"Xatoni toping: «Этот фильм более лучше»",answer:"Этот фильм лучше",explanation_uz:"более + лучше birga kelmaydi."},{id:"m6-cmp-7",type:"translate",prompt:"Tarjima qiling: «Bugun kechagidan sovuqroq» (холодно)",answer:"Сегодня холоднее, чем вчера",explanation_uz:"холоднее."},{id:"m6-cmp-8",type:"choose",prompt:"«arzonroq» qanday?",answer:"дешевле",choices:["дешевле","дешевее","более дёшево","дешевше"],explanation_uz:"дешёвый → дешевле."}]},{id:"m6-superlative",module:6,order:4,level:"A2",title:"Orttirma daraja",subtitle:"самый большой, лучший",theory:[{heading:"самый + sifat",body:"Eng keng tarqalgan usul: самый (eng) + to'liq sifat, ikkalasi ham otga moslashadi: самый большой город, самая красивая девушка, самое высокое здание."},{heading:"Maxsus shakllar",body:"лучший (eng yaxshi), худший (eng yomon), старший (katta — oila a'zosi), младший (kichik): мой лучший друг, старший брат."}],comparisonWithUzbek:"O'zbekcha 'eng' = самый. Tartib bir xil: 'eng katta uy' = самый большой дом. Faqat самый ham sifatdek moslashishini unutmang.",examples:[{ru:"Э́то са́мый большо́й го́род.",uz:"Bu eng katta shahar."},{ru:"Она́ са́мая у́мная в кла́ссе.",uz:"U sinfda eng aqllisi."},{ru:"Мой лу́чший друг живёт в Москве́.",uz:"Eng yaqin do‘stim Moskvada yashaydi."},{ru:"ста́рший брат",uz:"katta aka",note:"oilada"}],commonMistakes:[{wrong:"самый лучше",right:"самый лучший / лучше всех",why_uz:"самый + to‘liq shakl."},{wrong:"самая большой город",right:"самый большой город",why_uz:"самый ham otga moslashadi: город м."}],exercises:[{id:"m6-sup-1",type:"fillBlank",prompt:"Это сам___ красивая площадь.",answer:"ая",explanation_uz:"площадь ж → самая."},{id:"m6-sup-2",type:"choose",prompt:"«eng yaxshi do‘st» qanday?",answer:"лучший друг",choices:["лучший друг","самый лучше друг","более хороший друг","наилучше друг"],explanation_uz:"лучший — maxsus shakl."},{id:"m6-sup-3",type:"translate",prompt:"Tarjima qiling: «Bu eng qimmat restoran» (дорогой, ресторан)",answer:"Это самый дорогой ресторан",explanation_uz:"самый дорогой."},{id:"m6-sup-4",type:"choose",prompt:"«katta aka» (oilada)?",answer:"старший брат",choices:["старший брат","самый старый брат","старше брат","большой брат"],explanation_uz:"Oilada: старший/младший."},{id:"m6-sup-5",type:"errorHunt",prompt:"Xatoni toping: «Это самая высокое здание»",answer:"Это самое высокое здание",explanation_uz:"здание с → самое."}]},{id:"m6-adverbs",module:6,order:5,level:"A2",title:"Ravishlar",subtitle:"хорошо, быстро, по-русски",theory:[{heading:"Yasalishi",body:"Ko'p ravishlar sifatdan -о bilan yasaladi: хороший → хорошо, быстрый → быстро, плохой → плохо. Tillar uchun по- + -ски: по-русски, по-узбекски.",table:[["Sifat","Ravish","Ma'no"],["бы́стрый","бы́стро","tez"],["ме́дленный","ме́дленно","sekin"],["хоро́ший","хорошо́","yaxshi"],["громкий","гро́мко","baland (ovoz)"],["ру́сский","по-ру́сски","ruscha"]]},{heading:"тоже va также",body:"тоже — 'ham' (ega o'xshash): Я тоже студент. также — 'shuningdek' (ish-harakat qo'shiladi): Он играет на гитаре, а также поёт."},{heading:"Holat gaplari",body:"Ravish + Д.п shaxs holatni bildiradi: Мне холодно (menga sovuq), Ему скучно (unga zerikarli), Нам весело (bizga quvnoq)."}],comparisonWithUzbek:"'Ruscha gapiraman' = говорю по-русски (по- bilan!). 'Menga sovuq' = Мне холодно — qolip o'zbekchadagi bilan bir xil (kimga + holat).",examples:[{ru:"Он бы́стро говори́т.",uz:"U tez gapiradi."},{ru:"Я хорошо́ говорю́ по-ру́сски.",uz:"Men ruscha yaxshi gapiraman."},{ru:"Говори́те ме́дленнее, пожа́луйста.",uz:"Sekinroq gapiring, iltimos."},{ru:"Мне хо́лодно.",uz:"Menga sovuq. / Sovqotyapman."},{ru:"Я то́же хочу́ чай.",uz:"Men ham choy xohlayman."}],commonMistakes:[{wrong:"говорю русский",right:"говорю по-русски",why_uz:"Tilda gapirish — по-русски; русский язык — tilning o'zi."},{wrong:"Я холодный (sovqotdim ma’nosida)",right:"Мне холодно",why_uz:"Holat — Д.п + ravish."},{wrong:"Он говорит хороший",right:"Он говорит хорошо",why_uz:"Fe'lni ravish aniqlaydi: хорошо."}],exercises:[{id:"m6-adv-1",type:"transform",prompt:"Ravish yasang: быстрый",answer:"быстро",explanation_uz:"-о bilan."},{id:"m6-adv-2",type:"fillBlank",prompt:"Я говорю ___-русски.",answer:"по",explanation_uz:"по-русски."},{id:"m6-adv-3",type:"choose",prompt:"«Menga sovuq» qanday?",answer:"Мне холодно",choices:["Мне холодно","Я холодный","Я холодно","Мне холодный"],explanation_uz:"Д.п + ravish."},{id:"m6-adv-4",type:"choose",prompt:"Я ___ студент. (ham)",answer:"тоже",choices:["тоже","также","и","ещё"],explanation_uz:"тоже — ham."},{id:"m6-adv-5",type:"errorHunt",prompt:"Xatoni toping: «Она поёт хорошая»",answer:"Она поёт хорошо",explanation_uz:"Fe'l + ravish: хорошо."},{id:"m6-adv-6",type:"translate",prompt:"Tarjima qiling: «Sekinroq gapiring, iltimos»",answer:"Говорите медленнее, пожалуйста",explanation_uz:"медленнее — qiyosiy ravish."},{id:"m6-adv-7",type:"fillBlank",prompt:"Ему ску___. (zerikarli)",answer:"чно",explanation_uz:"Ему скучно."}]}],d=[{id:"m7-questions",module:7,order:1,level:"A2",title:"So'roq so'zlari to'liq",subtitle:"почему, зачем, сколько, какой",theory:[{heading:"To'liq ro'yxat",body:"Asosiy so'roq so'zlari va nozik farqlar:",table:[["So'z","Ma'no","Misol"],["кто / что","kim / nima","Кто звони́л?"],["где / куда́ / отку́да","qayerda / qayerga / qayerdan","Отку́да вы?"],["когда́","qachon","Когда́ начнётся?"],["почему́","nima uchun (sabab)","Почему́ ты опозда́л?"],["заче́м","nima maqsadda","Заче́м тебе́ э́то?"],["ско́лько","qancha/nechta","Ско́лько сто́ит?"],["како́й/кака́я/како́е","qanday/qaysi","Како́й цвет?"],["чей/чья/чьё","kimniki","Чья э́то су́мка?"],["как","qanday qilib","Как дое́хать до...?"]]},{heading:"почему vs зачем",body:"почему — sabab so'raydi (nega shunday bo'ldi?), зачем — maqsad so'raydi (nima uchun kerak?). Почему ты грустный? — Зачем ты купил это?"},{heading:"какой moslashadi",body:"какой sifatdek rod/son/kelishikka moslashadi: Какой фильм? Какая музыка? Какое время? Какие книги? В каком городе ты живёшь?"}],comparisonWithUzbek:"O'zbekcha 'nega' ikkala savolga ham ishlatiladi, ruscha почему (sabab) va зачем (maqsad) farqlanadi. 'Qanaqa/qaysi' = какой — moslashishini unutmang.",examples:[{ru:"Почему́ ты не пришёл?",uz:"Nega kelmading? (sabab)"},{ru:"Заче́м тебе́ две маши́ны?",uz:"Senga ikkita mashina nimaga kerak? (maqsad)"},{ru:"Ско́лько вам лет?",uz:"Yoshingiz nechada?"},{ru:"Како́й твой люби́мый фильм?",uz:"Sevimli filming qaysi?"},{ru:"Отку́да вы прие́хали?",uz:"Qayerdan keldingiz?"}],commonMistakes:[{wrong:"Куда ты живёшь?",right:"Где ты живёшь?",why_uz:"Yashash — joy (где), yo'nalish emas."},{wrong:"Какой музыка?",right:"Какая музыка?",why_uz:"музыка ж → какая."},{wrong:"Сколько лет вы?",right:"Сколько вам лет?",why_uz:"Yosh — Д.п: вам."}],exercises:[{id:"m7-q-1",type:"fillBlank",prompt:"___ вы приехали? — Из Ташкента.",answer:"Откуда",explanation_uz:"Javob «-dan» → откуда."},{id:"m7-q-2",type:"choose",prompt:"«Nega yig‘layapsan?» (sabab)",answer:"Почему ты плачешь?",choices:["Почему ты плачешь?","Зачем ты плачешь?","Как ты плачешь?","Что ты плачешь?"],explanation_uz:"Sabab → почему."},{id:"m7-q-3",type:"fillBlank",prompt:"___ это стоит? — Сто рублей.",answer:"Сколько",explanation_uz:"Narx → сколько."},{id:"m7-q-4",type:"fillBlank",prompt:"___ музыка тебе нравится?",answer:"Какая",explanation_uz:"музыка ж → какая."},{id:"m7-q-5",type:"choose",prompt:"«Bu kimning telefoni?»",answer:"Чей это телефон?",choices:["Чей это телефон?","Чья это телефон?","Кто это телефон?","Какой это телефон?"],explanation_uz:"телефон м → чей."},{id:"m7-q-6",type:"errorHunt",prompt:"Xatoni toping: «Куда находится банк?»",answer:"Где находится банк?",explanation_uz:"Joylashuv → где."},{id:"m7-q-7",type:"translate",prompt:"Tarjima qiling: «Qaysi shaharda yashaysiz?»",answer:"В каком городе вы живёте?",explanation_uz:"в каком — П.п."},{id:"m7-q-8",type:"choose",prompt:"«Senga bu nimaga kerak?» (maqsad)",answer:"Зачем тебе это?",choices:["Зачем тебе это?","Почему тебе это?","Где тебе это?","Когда тебе это?"],explanation_uz:"Maqsad → зачем."}]},{id:"m7-kotoryj",module:7,order:2,level:"B1",title:"«который» bilan ergash gaplar",subtitle:"девушка, которая поёт",theory:[{heading:"который nima",body:"O'zbekcha '-gan/-adigan' sifatdoshlariga mos: 'qo'shiq aytayotgan qiz' = девушка, которая поёт. который aniqlanayotgan otning rodi va soniga moslashadi, kelishigi esa ergash gapdagi vazifasiga qarab tanlanadi.",table:[["Bosh gap","Ergash gap","Tarjima"],["Вот дом,","кото́рый мы купи́ли","biz sotib olgan uy"],["Вот де́вушка,","кото́рая рабо́тает со мной","men bilan ishlaydigan qiz"],["Вот окно́,","кото́рое мы откры́ли","biz ochgan deraza"],["Вот лю́ди,","кото́рые мне помогли́","menga yordam bergan odamlar"]]},{heading:"Kelishik ergash gapdan",body:"Книга, которую я читаю (men o'qiyotgan kitob — В.п, chunki читаю что?). Друг, которому я звонил (men qo'ng'iroq qilgan do'st — Д.п, chunki звонил кому?). Rod/son — otdan, kelishik — ergash gapdagi fe'ldan!"}],comparisonWithUzbek:"O'zbek tilida sifatdosh otdan OLDIN keladi ('o'qiyotgan kitob'), rus tilida который otdan KEYIN: книга, которую я читаю. Vergul majburiy!",examples:[{ru:"Я зна́ю челове́ка, кото́рый говори́т по-узбе́кски.",uz:"O‘zbekcha gapiradigan odamni bilaman."},{ru:"Э́то фильм, кото́рый мне нра́вится.",uz:"Bu menga yoqadigan film."},{ru:"Кни́га, кото́рую ты дал, о́чень интере́сная.",uz:"Sen bergan kitob juda qiziqarli."},{ru:"Друг, с кото́рым я учи́лся, живёт в Москве́.",uz:"Men birga o‘qigan do‘stim Moskvada yashaydi."}],commonMistakes:[{wrong:"девушка, который поёт",right:"девушка, которая поёт",why_uz:"девушка ж → которая."},{wrong:"книга, которая я читаю",right:"книга, которую я читаю",why_uz:"Ergash gapda 'nimani o'qiyapman' → В.п которую."},{wrong:"vergulsiz yozish",right:"otdan keyin vergul",why_uz:"который oldidan doim vergul."}],exercises:[{id:"m7-kot-1",type:"fillBlank",prompt:"Это дом, котор___ мы купили.",answer:"ый",explanation_uz:"дом м, В.п jonsiz → который."},{id:"m7-kot-2",type:"fillBlank",prompt:"Это девушка, котор___ работает в банке.",answer:"ая",explanation_uz:"девушка ж → которая."},{id:"m7-kot-3",type:"fillBlank",prompt:"Книга, котор___ я читаю, интересная.",answer:"ую",explanation_uz:"читаю что? → В.п которую."},{id:"m7-kot-4",type:"fillBlank",prompt:"Люди, котор___ здесь живут, очень добрые.",answer:"ые",explanation_uz:"ko'plik → которые."},{id:"m7-kot-5",type:"choose",prompt:"Друг, ___ я звонил, не ответил.",answer:"которому",choices:["которому","который","которого","котором"],explanation_uz:"звонить кому → Д.п."},{id:"m7-kot-6",type:"translate",prompt:"Tarjima qiling: «Men ko‘rgan film yaxshi edi» (смотреть)",answer:"Фильм, который я смотрел, был хороший",explanation_uz:"фильм м → который."},{id:"m7-kot-7",type:"errorHunt",prompt:"Xatoni toping: «Это машина, который я хочу купить»",answer:"Это машина, которую я хочу купить",explanation_uz:"машина ж + В.п → которую."}]},{id:"m7-conjunctions",module:7,order:3,level:"B1",title:"Bog'lovchilar: чтобы, потому что, если",subtitle:"Sabab, maqsad va shart",theory:[{heading:"потому что va поэтому",body:"потому что — chunki (sababni keltiradi): Я не пришёл, потому что болел. поэтому — shuning uchun (natijani keltiradi): Я болел, поэтому не пришёл."},{heading:"чтобы — maqsad",body:"'... uchun' ma'nosida: Я учу русский, чтобы работать в России. Ega har xil bo'lsa чтобы + O'TGAN zamon: Я хочу, чтобы ты пришёл (kelishingni xohlayman)."},{heading:"если — shart",body:"Real shart: Если будет время, я приду (vaqt bo'lsa kelaman — kelasi zamon!). Noreal shart: если бы + o'tgan zamon, бы bilan: Если бы у меня были деньги, я бы купил машину."}],comparisonWithUzbek:"'chunki' = потому что, 'shuning uchun' = поэтому, '-sa' (shart) = если, '-ish uchun' = чтобы + infinitiv. 'Kelishingni xohlayman' qolipida чтобы dan keyin o'tgan zamon kelishi — yangi qoida, yodlang!",examples:[{ru:"Я учу́ ру́сский, потому́ что хочу́ рабо́тать в Росси́и.",uz:"Rus tilini o‘rganyapman, chunki Rossiyada ishlamoqchiman."},{ru:"Шёл дождь, поэ́тому мы оста́лись до́ма.",uz:"Yomg‘ir yog‘ayotgan edi, shuning uchun uyda qoldik."},{ru:"Я пришёл, что́бы помо́чь.",uz:"Yordam berish uchun keldim."},{ru:"Я хочу́, что́бы ты позвони́л ма́ме.",uz:"Onangga qo‘ng‘iroq qilishingni xohlayman."},{ru:"Е́сли за́втра бу́дет со́лнце, мы пойдём в парк.",uz:"Ertaga quyosh bo‘lsa, parkka boramiz."},{ru:"Е́сли бы я знал, я бы сказа́л.",uz:"Bilganimda aytardim."}],commonMistakes:[{wrong:"Я хочу, чтобы ты придёшь",right:"Я хочу, чтобы ты пришёл",why_uz:"чтобы dan keyin o'tgan zamon shakli."},{wrong:"Если я буду иметь время... (kalka)",right:"Если у меня будет время...",why_uz:"Egalik у + Р.п qolipida."},{wrong:"потому va поэтому almashtirish",right:"sabab→потому что, natija→поэтому",why_uz:"Yo'nalishi teskari ikki bog'lovchi."}],exercises:[{id:"m7-conj-1",type:"choose",prompt:"Я не пришёл, ___ болел.",answer:"потому что",choices:["потому что","поэтому","чтобы","если"],explanation_uz:"Sabab → потому что."},{id:"m7-conj-2",type:"choose",prompt:"Я болел, ___ не пришёл.",answer:"поэтому",choices:["поэтому","потому что","чтобы","который"],explanation_uz:"Natija → поэтому."},{id:"m7-conj-3",type:"choose",prompt:"Я учу русский, ___ работать в Москве.",answer:"чтобы",choices:["чтобы","потому что","если","когда"],explanation_uz:"Maqsad → чтобы + infinitiv."},{id:"m7-conj-4",type:"fillBlank",prompt:"Я хочу, чтобы ты ___ мне. (помочь, o‘tgan zamon)",answer:"помог",explanation_uz:"чтобы + помог."},{id:"m7-conj-5",type:"choose",prompt:"___ будет время, я приду.",answer:"Если",choices:["Если","Чтобы","Потому что","Поэтому"],explanation_uz:"Shart → если."},{id:"m7-conj-6",type:"fillBlank",prompt:"Если ___ у меня были деньги, я бы купил дом.",answer:"бы",explanation_uz:"Noreal shart: если бы + бы."},{id:"m7-conj-7",type:"errorHunt",prompt:"Xatoni toping: «Я хочу, чтобы ты приходишь завтра»",answer:"Я хочу, чтобы ты пришёл завтра",explanation_uz:"чтобы + o'tgan zamon."},{id:"m7-conj-8",type:"translate",prompt:"Tarjima qiling: «Vaqtim bo‘lsa, qo‘ng‘iroq qilaman»",answer:"Если у меня будет время, я позвоню",explanation_uz:"Real shart — kelasi zamon."}]},{id:"m7-indirect",module:7,order:4,level:"B1",title:"Bilvosita nutq",subtitle:"Он сказал, что...",theory:[{heading:"Darak gap: что",body:"«Я работаю» → Он сказал, что он работает. Rus tilida zamon MOSLASHTIRILMAYDI (inglizchadan farqli): aytilgan zamon saqlanadi."},{heading:"Savol: ли yoki so'roq so'z",body:"So'roq so'zli savol o'z so'zi bilan: «Где ты живёшь?» → Он спросил, где я живу. Ha/yo'q savoli ли bilan: «Ты придёшь?» → Он спросил, приду ли я."},{heading:"Iltimos: чтобы",body:"«Позвони маме!» → Он попросил, чтобы я позвонил маме. Yoki infinitiv: Он попросил меня позвонить маме."}],comparisonWithUzbek:"O'zbekcha 'U ishlashini aytdi' kabi qisqartirish ruschada yo'q — to'liq ergash gap ishlatiladi: Он сказал, что (он) работает. Zamon o'zgarmasligi o'zbekchaga o'xshaydi, bu oson.",examples:[{ru:"Он сказа́л, что за́втра придёт.",uz:"U ertaga kelishini aytdi."},{ru:"Она́ спроси́ла, где я живу́.",uz:"U qayerda yashashimni so‘radi."},{ru:"Я не зна́ю, придёт ли он.",uz:"U keladimi-yo‘qmi, bilmayman."},{ru:"Ма́ма попроси́ла, что́бы я купи́л хлеб.",uz:"Onam non olib kelishimni so‘radi."}],commonMistakes:[{wrong:"Он сказал, что он работал (hozir ishlayotganini aytgan bo‘lsa)",right:"Он сказал, что работает",why_uz:"Rus tilida zamon moslashuvi YO‘Q."},{wrong:"Он спросил, что я приду",right:"Он спросил, приду ли я",why_uz:"Ha/yo'q savoli → ли."}],exercises:[{id:"m7-ind-1",type:"transform",prompt:"Bilvosita qiling: Он сказал: «Я работаю в банке»",answer:"Он сказал, что работает в банке",explanation_uz:"что bilan, zamon saqlanadi."},{id:"m7-ind-2",type:"transform",prompt:"Bilvosita qiling: Она спросила: «Где ты живёшь?»",answer:"Она спросила, где я живу",explanation_uz:"So'roq so'z saqlanadi."},{id:"m7-ind-3",type:"choose",prompt:"Я не знаю, ___ он придёт.",answer:"придёт ли",choices:["придёт ли","что","чтобы","если"],explanation_uz:"Ha/yo'q savol → ли (fe'ldan keyin)."},{id:"m7-ind-4",type:"errorHunt",prompt:"Xatoni toping: «Он сказал, что он работал в банке» (hozir ham ishlaydi)",answer:"Он сказал, что работает в банке",explanation_uz:"Zamon moslashuvi qilinmaydi."},{id:"m7-ind-5",type:"translate",prompt:"Tarjima qiling: «U kelishini aytdi»",answer:"Он сказал, что придёт",explanation_uz:"что придёт."}]},{id:"m7-numbers",module:7,order:5,level:"B1",title:"Sonlar, vaqt va sana",subtitle:"в два часа, пятого мая",theory:[{heading:"Soat nechada?",body:"в + son + час/часа/часов: в час (soat birda), в два часа, в пять часов. Yarim soatlar: в половине третьего (ikki yarimda — diqqat: keyingi soat aytiladi!).",table:[["Savol","Javob","Ma'no"],["Кото́рый час?","Два часа́","Soat ikki"],["Во ско́лько?","В два часа́","Soat ikkida"],["","В полови́не пя́того","To'rt yarimda"]]},{heading:"Sana",body:"Bugun nechanchi? — tartib son И.п: Сегодня пятое мая. Qachon? — tartib son Р.п: пятого мая (beshinchi mayda). Yil: в 2026 году (в две тысячи двадцать шестом году)."},{heading:"Hafta kunlari",body:"в + В.п: в понедельник (dushanba kuni), во вторник, в среду, в четверг, в пятницу, в субботу, в воскресенье."}],comparisonWithUzbek:"'Soat ikkiDA' = в два часа (в + son). 'Beshinchi mayDA' = пятого мая (Р.п, predlogsiz!). 'DushanbaDA' = в понедельник. Uchta turli qolip — yodlab oling.",examples:[{ru:"Уро́к начина́ется в де́вять часо́в.",uz:"Dars soat to‘qqizda boshlanadi."},{ru:"Сего́дня деся́тое ию́ня.",uz:"Bugun o‘ninchi iyun."},{ru:"Я роди́лся пя́того ма́рта.",uz:"Men beshinchi martda tug‘ilganman."},{ru:"Мы встре́тимся в суббо́ту.",uz:"Shanba kuni uchrashamiz."},{ru:"Сейча́с полови́на восьмо́го.",uz:"Hozir yetti yarim."}],commonMistakes:[{wrong:"в пятое мая (qachon?)",right:"пятого мая",why_uz:"Sana «qachon» — predlogsiz Р.п."},{wrong:"в субботе",right:"в субботу",why_uz:"Hafta kuni — в + В.п."},{wrong:"пять часа",right:"пять часов",why_uz:"5+ → Р.п ko‘plik: часов."}],exercises:[{id:"m7-num-1",type:"fillBlank",prompt:"Урок начинается ___ девять часов.",answer:"в",explanation_uz:"в + soat."},{id:"m7-num-2",type:"choose",prompt:"«ikki soat» qanday?",answer:"два часа",choices:["два часа","два часов","два час","две часа"],explanation_uz:"2-4 → Р.п birlik: часа."},{id:"m7-num-3",type:"choose",prompt:"«besh soat» qanday?",answer:"пять часов",choices:["пять часов","пять часа","пять час","пятого часа"],explanation_uz:"5+ → часов."},{id:"m7-num-4",type:"choose",prompt:"«Beshinchi mayda» (qachon?)",answer:"пятого мая",choices:["пятого мая","пятое мая","в пятое мая","пятый май"],explanation_uz:"Qachon → Р.п."},{id:"m7-num-5",type:"fillBlank",prompt:"Мы встретимся ___ субботу.",answer:"в",explanation_uz:"в субботу."},{id:"m7-num-6",type:"translate",prompt:"Tarjima qiling: «Dars soat uchda tugaydi» (заканчиваться)",answer:"Урок заканчивается в три часа",explanation_uz:"в три часа."},{id:"m7-num-7",type:"errorHunt",prompt:"Xatoni toping: «Я родился в десятое июня»",answer:"Я родился десятого июня",explanation_uz:"Sana qachon → predlogsiz Р.п."}]},{id:"m7-modals",module:7,order:6,level:"B1",title:"Modal so‘zlar: можно, нельзя, надо",subtitle:"Ruxsat, taqiq, zarurat",theory:[{heading:"Shaxssiz qoliplar",body:"Bu so'zlar Д.п bilan keladi (kimga — ixtiyoriy): Мне надо идти. Здесь можно курить? Детям нельзя смотреть этот фильм.",table:[["So'z","Ma'no","Misol"],["мо́жно","mumkin","Мо́жно войти́?"],["нельзя́","mumkin emas","Здесь нельзя́ кури́ть"],["на́до / ну́жно","kerak","Мне на́до рабо́тать"],["не на́до","kerak emas","Не на́до волнова́ться"]]},{heading:"O'tgan/kelasi zamonda",body:"было/будет qo'shiladi: Мне надо было позвонить (qo'ng'iroq qilishim kerak edi). Вам нужно будет прийти (kelishingiz kerak bo'ladi)."},{heading:"нельзя + aspekt",body:"нельзя + НСВ = taqiq (mumkin emas, man etilgan): Здесь нельзя парковаться. нельзя + СВ = imkonsiz (iloji yo'q): Эту дверь нельзя открыть (bu eshikni ochib bo'lmaydi)."}],comparisonWithUzbek:"'mumkin' = можно, 'mumkin emas' = нельзя, 'kerak' = надо/нужно. O'zbekchadagidek shaxssiz ishlatiladi. 'ochib bo'lmaydi' (iloji yo'q) uchun нельзя + СВ ishlatilishi nozik farq.",examples:[{ru:"Мо́жно вопро́с?",uz:"Savol bersam mumkinmi?"},{ru:"Здесь нельзя́ фотографи́ровать.",uz:"Bu yerda suratga olish mumkin emas."},{ru:"Мне на́до купи́ть проду́кты.",uz:"Oziq-ovqat olishim kerak."},{ru:"Тебе́ ну́жно отдохну́ть.",uz:"Senga dam olish kerak."},{ru:"На́до бы́ло сказа́ть ра́ньше!",uz:"Oldinroq aytish kerak edi!"}],commonMistakes:[{wrong:"Я надо идти",right:"Мне надо идти",why_uz:"надо bilan shaxs Д.п da: мне."},{wrong:"Можно я войти?",right:"Можно (мне) войти?",why_uz:"можно + infinitiv (+ Д.п)."},{wrong:"не можно",right:"нельзя",why_uz:"'mumkin emas' uchun alohida so'z: нельзя."}],exercises:[{id:"m7-mod-1",type:"choose",prompt:"«mumkin emas» qanday?",answer:"нельзя",choices:["нельзя","не можно","не надо","нет можно"],explanation_uz:"нельзя."},{id:"m7-mod-2",type:"fillBlank",prompt:"___ надо больше спать. (men)",answer:"Мне",explanation_uz:"Д.п: мне надо."},{id:"m7-mod-3",type:"choose",prompt:"«Kirish mumkinmi?»",answer:"Можно войти?",choices:["Можно войти?","Нельзя войти?","Надо войти?","Мочь войти?"],explanation_uz:"Можно + infinitiv."},{id:"m7-mod-4",type:"fillBlank",prompt:"Мне надо ___ позвонить вчера. (edi)",answer:"было",explanation_uz:"надо было."},{id:"m7-mod-5",type:"errorHunt",prompt:"Xatoni toping: «Я надо работать»",answer:"Мне надо работать",explanation_uz:"Мне (Д.п) надо."},{id:"m7-mod-6",type:"translate",prompt:"Tarjima qiling: «Bu yerda chekish mumkin emas»",answer:"Здесь нельзя курить",explanation_uz:"Taqiq → нельзя + НСВ."},{id:"m7-mod-7",type:"choose",prompt:"«Bu eshikni ochib bo‘lmaydi» (iloji yo‘q)",answer:"Эту дверь нельзя открыть",choices:["Эту дверь нельзя открыть","Эту дверь нельзя открывать","Эта дверь не можно открыть","Эту дверь не надо открыть"],explanation_uz:"Imkonsizlik → нельзя + СВ."}]}],p=[{id:"m8-participles",module:8,order:1,level:"B1",title:"Kesim (причастия) — tanishuv",subtitle:"читающий, прочитанный",theory:[{heading:"Faol kesim",body:"-ущ/-ющ/-ащ/-ящ: читающий (o'qiyotgan), говорящий (gapirayotgan). Kitobiy uslubda ishlatiladi; og'zaki nutqda который bilan almashtirish mumkin: человек, читающий книгу = человек, который читает книгу."},{heading:"Majhul kesim",body:"-нн/-т: прочитанный (o'qilgan), сделанный (qilingan), закрытый (yopilgan). Qisqa shakli juda ko'p ishlatiladi: Магазин закрыт (do'kon yopiq). Работа сделана (ish qilingan).",table:[["Fe'l","Kesim","Qisqa shakl"],["закры́ть","закры́тый","закры́т / закры́та / закры́то"],["откры́ть","откры́тый","откры́т"],["сде́лать","сде́ланный","сде́лан"],["написа́ть","напи́санный","напи́сан"]]}],comparisonWithUzbek:"O'zbekcha '-gan' sifatdoshiga mos: 'o'qilGAN kitob' = прочитанная книга, 'yopiq/yopilGAN' = закрыт. Qisqa shakl (закрыт, открыт, написан) kundalik nutqda eng keraklisi.",examples:[{ru:"Магази́н закры́т.",uz:"Do‘kon yopiq."},{ru:"Музе́й откры́т с девяти́ часо́в.",uz:"Muzey soat to‘qqizdan ochiq."},{ru:"Рабо́та уже́ сде́лана.",uz:"Ish allaqachon qilingan."},{ru:"Письмо́ напи́сано вчера́.",uz:"Xat kecha yozilgan."}],commonMistakes:[{wrong:"Магазин закрытый (kesim sifatida)",right:"Магазин закрыт",why_uz:"Holatni qisqa shakl bildiradi."},{wrong:"Работа сделан",right:"Работа сделана",why_uz:"работа ж → сделана."}],exercises:[{id:"m8-part-1",type:"fillBlank",prompt:"Магазин закры___. (yopiq)",answer:"т",explanation_uz:"магазин м → закрыт."},{id:"m8-part-2",type:"fillBlank",prompt:"Дверь закры___. (yopiq)",answer:"та",explanation_uz:"дверь ж → закрыта."},{id:"m8-part-3",type:"choose",prompt:"«Ish qilingan» qanday?",answer:"Работа сделана",choices:["Работа сделана","Работа сделан","Работа сделать","Работа делала"],explanation_uz:"ж → сделана."},{id:"m8-part-4",type:"transform",prompt:"который bilan almashtiring: «человек, читающий книгу»",answer:"человек, который читает книгу",explanation_uz:"Og'zaki uslub: который."},{id:"m8-part-5",type:"translate",prompt:"Tarjima qiling: «Muzey ochiq»",answer:"Музей открыт",explanation_uz:"открыт."}]},{id:"m8-gerund",module:8,order:2,level:"B1",title:"Ravishdosh (деепричастия) — tanishuv",subtitle:"читая, прочитав",theory:[{heading:"НСВ ravishdoshi: -я",body:"Bir paytda bo'layotgan ikkinchi ish: Он шёл, слушая музыку (musiqa tinglaB ketardi). читая (o'qib turib), говоря (gapirib turib), думая."},{heading:"СВ ravishdoshi: -в",body:"Oldin tugagan ish: Прочитав книгу, я лёг спать (kitobni o'qib bo'liB, uxlashga yotdim). сделав (qilib bo'lib), купив (sotib olib)."},{heading:"Og'zaki muqobillar",body:"Og'zaki nutqda ko'pincha когда yoki после того как bilan almashtiriladi: Прочитав книгу... = После того как я прочитал книгу..."}],comparisonWithUzbek:"O'zbekcha '-ib' ravishdoshiga juda mos: 'musiqa tinglab' = слушая музыку, 'o'qib bo'lib' = прочитав. O'zbek tilida bu shakl juda tabiiy — ruschasini ham oson o'zlashtirasiz.",examples:[{ru:"Он за́втракал, чита́я газе́ту.",uz:"U gazeta o‘qib nonushta qilardi."},{ru:"Сде́лав уро́ки, я пошёл гуля́ть.",uz:"Darslarni qilib bo‘lib, sayrga chiqdim."},{ru:"Говоря́ по телефо́ну, она́ гото́вила у́жин.",uz:"Telefonda gaplashib, kechki ovqat tayyorlardi."}],commonMistakes:[{wrong:"Читав книгу...",right:"Читая книгу... / Прочитав книгу...",why_uz:"НСВ → -я, СВ → -в."},{wrong:"Ega farqli bo'lsa ishlatish",right:"Bir gapda bitta ega",why_uz:"Ravishdosh faqat asosiy ega bilan bir xil shaxsga tegishli."}],exercises:[{id:"m8-ger-1",type:"choose",prompt:"«musiqa tinglab» qanday?",answer:"слушая музыку",choices:["слушая музыку","слушав музыку","слушать музыку","слушал музыку"],explanation_uz:"НСВ → слушая."},{id:"m8-ger-2",type:"choose",prompt:"«kitobni o‘qib bo‘lib» qanday?",answer:"прочитав книгу",choices:["прочитав книгу","прочитая книгу","читав книгу","прочитал книгу"],explanation_uz:"СВ → -в: прочитав."},{id:"m8-ger-3",type:"transform",prompt:"Ravishdosh bilan qisqartiring: «Когда он шёл домой, он думал о работе»",answer:"Идя домой, он думал о работе",explanation_uz:"идти → идя."},{id:"m8-ger-4",type:"translate",prompt:"Tarjima qiling: «Ishni tugatib, men uyga ketdim» (закончить работу)",answer:"Закончив работу, я пошёл домой",explanation_uz:"СВ ravishdosh: закончив."}]},{id:"m8-particles",module:8,order:3,level:"B1",title:"Yuklamalar: же, ли, ведь, -то/-нибудь",subtitle:"Nutqqa jon kirituvchi mayda so'zlar",theory:[{heading:"-то va -нибудь",body:"кто-то — kimdir (aniq, lekin men bilmayman): Кто-то звонил. кто-нибудь — kimdir bo'lsa ham/har qanday: Кто-нибудь может помочь? Savol va iltimosda -нибудь, darak gapda -то.",table:[["-то (aniq noma’lum)","-нибудь (istalgan)",""],["кто́-то","кто́-нибудь","kimdir"],["что́-то","что́-нибудь","nimadir"],["где́-то","где́-нибудь","qayerdadir"],["когда́-то","когда́-нибудь","qachondir"]]},{heading:"же, ведь, ну",body:"же — ta'kid/sabrsizlik: Где же ты был?! (qayerda eding axir?!). ведь — axir: Ты ведь знал! (axir bilarding-ku!). ну — xo'sh/qani: Ну, пошли! Bu yuklamalar nutqni tabiiy qiladi."}],comparisonWithUzbek:"'-dir' = -то, 'biror' = -нибудь: 'kimDIR keldi' = кто-то пришёл, 'BIROR kim bormi?' = есть кто-нибудь? же/ведь o'zbekcha 'axir/-ku' ga mos: 'bilarding-KU' = ты ведь знал.",examples:[{ru:"Кто́-то стучи́т в дверь.",uz:"Kimdir eshik taqillatyapti."},{ru:"Дай мне что́-нибудь почита́ть.",uz:"O‘qishga biror narsa ber."},{ru:"Когда́-нибудь я пое́ду в Япо́нию.",uz:"Qachondir Yaponiyaga boraman."},{ru:"Ты же обеща́л!",uz:"Va’da bergan eding-ku!"},{ru:"Э́то ведь про́сто.",uz:"Axir bu oson-ku."}],commonMistakes:[{wrong:"Кто-то может помочь? (savol)",right:"Кто-нибудь может помочь?",why_uz:"Savolda -нибудь."},{wrong:"Я видел кого-нибудь (darak)",right:"Я видел кого-то",why_uz:"Darak gapda aniq noma’lum → -то."}],exercises:[{id:"m8-pt-1",type:"choose",prompt:"___ звонил тебе утром. (darak gap)",answer:"Кто-то",choices:["Кто-то","Кто-нибудь","Кто же","Кто ведь"],explanation_uz:"Darak → -то."},{id:"m8-pt-2",type:"choose",prompt:"___ хочет чай? (taklif)",answer:"Кто-нибудь",choices:["Кто-нибудь","Кто-то","Кто же","Никто"],explanation_uz:"Savol/taklif → -нибудь."},{id:"m8-pt-3",type:"fillBlank",prompt:"Расскажи мне что-___ интересное. (biror narsa)",answer:"нибудь",explanation_uz:"Iltimos → -нибудь."},{id:"m8-pt-4",type:"choose",prompt:"«Axir bilarding-ku!» qanday?",answer:"Ты ведь знал!",choices:["Ты ведь знал!","Ты ли знал!","Ты-нибудь знал!","Ты то знал!"],explanation_uz:"ведь — axir/-ku."},{id:"m8-pt-5",type:"translate",prompt:"Tarjima qiling: «Qachondir Moskvaga boraman»",answer:"Когда-нибудь я поеду в Москву",explanation_uz:"Kelajak orzu → когда-нибудь."}]},{id:"m8-etiquette",module:8,order:4,level:"B1",title:"Muloqot odobi",subtitle:"Iltimos, uzr, minnatdorchilik, telefon",theory:[{heading:"Iltimos qilish",body:"Oddiy: Дайте, пожалуйста... Muloyim: Не могли бы вы...? (bera olmasmidingiz?), Будьте добры... (marhamat qilib...). Можно...? (mumkinmi?)"},{heading:"Uzr va javoblar",body:"Извините / Простите — kechirasiz. Извините за опоздание — kechikkanim uchun uzr. Javob: Ничего страшного (hechqisi yo'q), Не за что (arzimaydi — rahmatga javob).",table:[["Vaziyat","Ibora","Ma'no"],["Rahmat","Спаси́бо большо́е","Katta rahmat"],["Javob","Пожа́луйста / Не́ за что","Marhamat / Arzimaydi"],["Uzr","Извини́те, пожа́луйста","Kechirasiz"],["Javob","Ничего́ стра́шного","Hechqisi yo'q"],["Tabrik","Поздравля́ю!","Tabriklayman!"]]},{heading:"Telefonda",body:"Алло! / Слушаю (eshitaman). Можно Ивана? (Ivan bormi?) — Его нет, перезвоните позже (u yo'q, keyinroq qo'ng'iroq qiling). Вы ошиблись номером (notog'ri raqam terdingiz)."}],comparisonWithUzbek:"пожалуйста uch vazifada: 1) iltimos (please), 2) marhamat (rahmatga javob), 3) mana, oling. O'zbek tilidagi 'iltimos/marhamat' ikkalasini ham qoplaydi.",examples:[{ru:"Бу́дьте добры́, переда́йте соль.",uz:"Marhamat qilib, tuzni uzating."},{ru:"Не могли́ бы вы мне помо́чь?",uz:"Menga yordam bera olmasmidingiz?"},{ru:"Извини́те за беспоко́йство.",uz:"Bezovta qilganim uchun uzr."},{ru:"Спаси́бо огро́мное! — Не́ за что!",uz:"Katta rahmat! — Arzimaydi!"},{ru:"Алло́, мо́жно Дильшо́да? — Его́ нет до́ма.",uz:"Allo, Dilshod bormi? — U uyda yo‘q."}],commonMistakes:[{wrong:"Дай соль (notanishga)",right:"Дайте, пожалуйста, соль",why_uz:"Notanishga вы shakli + пожалуйста."},{wrong:"Спасибо → Да",right:"Спасибо → Пожалуйста / Не за что",why_uz:"Rahmatga to'g'ri javob bor."}],exercises:[{id:"m8-et-1",type:"choose",prompt:"Rahmatga qanday javob beriladi?",answer:"Пожалуйста",choices:["Пожалуйста","Спасибо","Извините","Хорошо"],explanation_uz:"Пожалуйста yoki Не за что."},{id:"m8-et-2",type:"choose",prompt:"«Hechqisi yo‘q» qanday?",answer:"Ничего страшного",choices:["Ничего страшного","Не за что","Всё плохо","Никогда"],explanation_uz:"Uzrga javob."},{id:"m8-et-3",type:"translate",prompt:"Tarjima qiling: «Kechikkanim uchun uzr»",answer:"Извините за опоздание",explanation_uz:"извинить за + В.п."},{id:"m8-et-4",type:"choose",prompt:"Muloyim iltimos qaysi?",answer:"Не могли бы вы помочь?",choices:["Не могли бы вы помочь?","Помоги!","Надо помочь!","Вы поможете."],explanation_uz:"Не могли бы вы — eng muloyim shakl."},{id:"m8-et-5",type:"fillBlank",prompt:"Алло! ___ Ивана? (chaqirib bering)",answer:"Можно",explanation_uz:"Можно Ивана? — telefon odobi."}],miniDialogue:[{speaker:"A",ru:"Извините, не могли бы вы сказать, как пройти к метро?",uz:"Kechirasiz, metroga qanday borishni ayta olmasmidingiz?"},{speaker:"B",ru:"Конечно! Идите прямо, метро будет слева.",uz:"Albatta! To‘g‘riga yuring, metro chap tomonda bo‘ladi."},{speaker:"A",ru:"Спасибо большое!",uz:"Katta rahmat!"},{speaker:"B",ru:"Не за что! Удачи!",uz:"Arzimaydi! Omad!"}]},{id:"m8-dialogues",module:8,order:5,level:"B1",title:"Real vaziyatlar: do‘kon, taksi, shifoxona",subtitle:"Hayotiy dialoglar grammatika bilan",theory:[{heading:"Do'konda",body:"Сколько стоит...? (qancha turadi?), Покажите, пожалуйста... (ko'rsating), У вас есть...? (sizlarda ... bormi?), Я возьму это (men buni olaman), Можно картой? (karta bilan mumkinmi?)"},{heading:"Taksida",body:"Мне нужно на вокзал (menga vokzalga kerak), Остановите здесь, пожалуйста (shu yerda to'xtating), Сколько с меня? (mendan qancha?)"},{heading:"Shifokorda",body:"У меня болит голова/живот/горло (boshim/qornim/tomog'im og'riyapti — болит + И.п!), У меня температура (haroratim bor), Мне плохо (o'zimni yomon his qilyapman).",table:[["Ibora","Ma'no"],["У меня́ боли́т голова́","Boshim og'riyapti"],["У меня́ боля́т но́ги","Oyoqlarim og'riyapti (ko'plik → болят)"],["Вы́зовите врача́!","Shifokor chaqiring!"],["Мне ну́жно лека́рство","Menga dori kerak"]]}],comparisonWithUzbek:"'Boshim og'riyapti' = У меня болит голова — so'zma-so'z 'menda bosh og'riyapti'. Og'riyotgan a'zo И.п da (ega!), odam esa у + Р.п da. Bu qolip o'zbekchadan farq qiladi, alohida yodlang.",examples:[{ru:"Ско́лько сто́ит э́та руба́шка?",uz:"Bu ko‘ylak qancha turadi?"},{ru:"У вас есть хлеб? — Да, коне́чно.",uz:"Sizlarda non bormi? — Ha, albatta."},{ru:"Мне ну́жно в аэропо́рт.",uz:"Menga aeroportga kerak."},{ru:"У меня́ боли́т зуб.",uz:"Tishim og‘riyapti."},{ru:"Останови́те на сле́дующей, пожа́луйста.",uz:"Keyingisida to‘xtating, iltimos."}],commonMistakes:[{wrong:"Моя голова болит у меня",right:"У меня болит голова",why_uz:"Qolip: У + Р.п + болит + И.п."},{wrong:"У меня болит ноги",right:"У меня болят ноги",why_uz:"Ko'plik ega → болят."},{wrong:"Сколько стоят эта книга?",right:"Сколько стоит эта книга?",why_uz:"Birlik → стоит."}],exercises:[{id:"m8-dlg-1",type:"translate",prompt:"Tarjima qiling: «Bu qancha turadi?»",answer:"Сколько это стоит?",explanation_uz:"Сколько стоит?"},{id:"m8-dlg-2",type:"translate",prompt:"Tarjima qiling: «Boshim og‘riyapti»",answer:"У меня болит голова",explanation_uz:"У меня болит + И.п."},{id:"m8-dlg-3",type:"fillBlank",prompt:"У меня бол___ ноги. (og‘riyapti)",answer:"ят",explanation_uz:"Ko'plik → болят."},{id:"m8-dlg-4",type:"choose",prompt:"Taksida: «Shu yerda to‘xtating»",answer:"Остановите здесь, пожалуйста",choices:["Остановите здесь, пожалуйста","Стойте здесь всегда","Здесь стоп","Остановка здесь"],explanation_uz:"Остановите — buyruq вы shakli."},{id:"m8-dlg-5",type:"choose",prompt:"Do‘konda: «Karta bilan to‘lasam bo‘ladimi?»",answer:"Можно картой?",choices:["Можно картой?","Можно карта?","Карта есть?","Я карта."],explanation_uz:"картой — Т.п (vosita)."},{id:"m8-dlg-6",type:"translate",prompt:"Tarjima qiling: «Sizlarda sut bormi?» (молоко)",answer:"У вас есть молоко?",explanation_uz:"У вас есть...?"},{id:"m8-dlg-7",type:"sentenceBuilder",prompt:"Gap tuzing: «Menga vokzalga kerak»",answer:"Мне нужно на вокзал",tokens:["нужно","Мне","вокзал","на"],explanation_uz:"Мне нужно на вокзал."}],miniDialogue:[{speaker:"Sotuvchi",ru:"Здравствуйте! Что вы хотите?",uz:"Assalomu alaykum! Nima xohlaysiz?"},{speaker:"Siz",ru:"Покажите, пожалуйста, эту рубашку. Сколько она стоит?",uz:"Iltimos, bu ko‘ylakni ko‘rsating. U qancha turadi?"},{speaker:"Sotuvchi",ru:"Две тысячи рублей. Хороший выбор!",uz:"Ikki ming rubl. Yaxshi tanlov!"},{speaker:"Siz",ru:"Хорошо, я возьму её. Можно картой?",uz:"Yaxshi, men uni olaman. Karta bilan mumkinmi?"},{speaker:"Sotuvchi",ru:"Конечно. Спасибо за покупку!",uz:"Albatta. Xaridingiz uchun rahmat!"}]}],y=[{id:"m9-participles-full",module:9,order:1,level:"B2",title:"To'liq kesim tizimi",subtitle:"читающий, читавший, читаемый, прочитанный",theory:[{heading:"4 xil kesim",body:"Rus tilida 4 turdagi kesim bor: faol hozirgi (-ущ/-ющ/-ащ/-ящ), faol o'tgan (-вш/-ш), majhul hozirgi (-ем/-им), majhul o'tgan (-нн/-енн/-т). Hammasi sifatdek turlanadi.",table:[["Turi","Yasalishi","Misol","Ma'no"],["Faol hozirgi","-ющ-","чита́ющий","o'qiyotgan"],["Faol o'tgan","-вш-","чита́вший","o'qigan (o'zi)"],["Majhul hozirgi","-ем-","чита́емый","o'qilayotgan"],["Majhul o'tgan","-нн-","прочи́танный","o'qilgan"]]},{heading:"Kesim oborotlari",body:"Kesimli birikma otdan keyin kelsa vergul bilan ajratiladi: Книга, прочитанная мной вчера, очень интересная. Otdan oldin kelsa vergulsiz: прочитанная мной книга."},{heading:"Og'zaki muqobil",body:"Og'zaki nutqda kesim o'rniga который ishlatiladi: студент, изучающий русский = студент, который изучает русский. Kesim — yozma va rasmiy uslub belgisi."}],comparisonWithUzbek:"O'zbekcha '-ayotgan' (faol hozirgi) = -ющий, '-gan' (faol o'tgan) = -вший, '-layotgan/-ilayotgan' = -емый, '-ilgan' = -нный. O'zbek tilida bu shakllar juda faol — ruschada esa asosan yozma nutqda.",examples:[{ru:"студе́нт, изуча́ющий ру́сский язы́к",uz:"rus tilini o'rganayotgan talaba"},{ru:"писа́тель, написа́вший э́тот рома́н",uz:"bu romanni yozgan yozuvchi"},{ru:"пробле́ма, обсужда́емая на конфере́нции",uz:"konferensiyada muhokama qilinayotgan muammo"},{ru:"пи́сьма, напи́санные в про́шлом ве́ке",uz:"o'tgan asrda yozilgan xatlar"},{ru:"Челове́к, сде́лавший э́то, геро́й.",uz:"Buni qilgan odam — qahramon."}],commonMistakes:[{wrong:"студент, который изучающий",right:"студент, изучающий / студент, который изучает",why_uz:"который va kesim birga kelmaydi — bittasini tanlang."},{wrong:"прочитанная книга мной",right:"прочитанная мной книга",why_uz:"Bajaruvchi (Т.п) kesimdan keyin, otdan oldin turadi."},{wrong:"написавшая письмо (xat haqida)",right:"написанное письмо",why_uz:"Xat YOZILGAN (majhul), yozuvchi YOZGAN (faol) — yo‘nalishni adashtirmang."}],exercises:[{id:"m9-part-1",type:"choose",prompt:"«o'qiyotgan talaba» qanday?",answer:"читающий студент",choices:["читающий студент","читавший студент","читаемый студент","прочитанный студент"],explanation_uz:"Faol hozirgi: -ющий."},{id:"m9-part-2",type:"choose",prompt:"«yozilgan xat» qanday?",answer:"написанное письмо",choices:["написанное письмо","написавшее письмо","пишущее письмо","писавшее письмо"],explanation_uz:"Majhul o'tgan: -нное."},{id:"m9-part-3",type:"transform",prompt:"который bilan almashtiring: «человек, сделавший это»",answer:"человек, который сделал это",explanation_uz:"Faol kesim → который + fe’l."},{id:"m9-part-4",type:"choose",prompt:"«обсуждаемый вопрос» nimani bildiradi?",answer:"muhokama qilinayotgan masala",choices:["muhokama qilinayotgan masala","muhokama qilgan masala","muhokama qilinadigan edi","muhokama tugagan masala"],explanation_uz:"Majhul hozirgi -емый."},{id:"m9-part-5",type:"fillBlank",prompt:"Книга, прочитанн___ мной вчера, интересная.",answer:"ая",explanation_uz:"книга ж → прочитанная."},{id:"m9-part-6",type:"errorHunt",prompt:"Xatoni toping: «девушка, которая поющая на сцене»",answer:"девушка, поющая на сцене",explanation_uz:"которая ortiqcha — kesimning o‘zi yetadi."},{id:"m9-part-7",type:"transform",prompt:"Kesim bilan qisqartiring: «студенты, которые изучают русский»",answer:"студенты, изучающие русский",explanation_uz:"изучающие — faol hozirgi ko‘plik."},{id:"m9-part-8",type:"choose",prompt:"Qaysi kesim YOZMA uslubga xos?",answer:"hammasi — kesim kitobiy shakl",choices:["hammasi — kesim kitobiy shakl","faqat -ющий","faqat -нный","hech qaysi"],explanation_uz:"Og'zaki nutqda который afzal."}]},{id:"m9-passive",module:9,order:2,level:"B2",title:"Passiv konstruksiyalar",subtitle:"Дом строится. Дом построен.",theory:[{heading:"НСВ passiv: -ся",body:"Jarayon passivda -ся bilan: Дом строится рабочими (uy quryapti — ishchilar tomonidan). Книга читается. Вопрос обсуждается."},{heading:"СВ passiv: qisqa kesim",body:"Natija passivda qisqa majhul kesim: Дом построен (uy qurilgan/qurib bo'lingan). Письмо написано. Работа сделана. O'tgan/kelasi zamonda быть qo'shiladi: Дом был построен. Дом будет построен.",table:[["Zamon","НСВ (jarayon)","СВ (natija)"],["Hozirgi","Дом стро́ится","—"],["O'tgan","Дом стро́ился","Дом был постро́ен"],["Kelasi","Дом бу́дет стро́иться","Дом бу́дет постро́ен"]]},{heading:"Bajaruvchi — Т.п",body:"Passivda ish bajaruvchi творительный kelishikda: Роман написан Толстым (roman Tolstoy tomonidan yozilgan). Bajaruvchini aytmaslik ham mumkin — bu passivning asosiy maqsadi."}],comparisonWithUzbek:"O'zbekcha '-il' nisbatiga mos: qurILmoqda = строится, qurILgan = построен, 'Tolstoy tomonidan' = Толстым (predlogsiz Т.п!). 'томонидан' so'zini tarjima qilish shart emas.",examples:[{ru:"Э́тот вопро́с сейча́с обсужда́ется.",uz:"Bu masala hozir muhokama qilinmoqda."},{ru:"Рома́н «Война́ и мир» напи́сан Толсты́м.",uz:"«Urush va tinchlik» romani Tolstoy tomonidan yozilgan."},{ru:"Магази́н был закры́т на ремо́нт.",uz:"Do'kon ta'mirlash uchun yopilgan edi."},{ru:"Дома́ зде́сь стро́ятся бы́стро.",uz:"Bu yerda uylar tez quriladi."},{ru:"Биле́ты уже́ про́даны.",uz:"Chiptalar allaqachon sotib bo‘lingan."}],commonMistakes:[{wrong:"Роман написан от Толстого",right:"Роман написан Толстым",why_uz:"Bajaruvchi predlogsiz Т.п da."},{wrong:"Дом строен",right:"Дом построен / Дом строится",why_uz:"НСВ → -ся, СВ → to‘liq qisqa kesim."},{wrong:"Письмо написано вчера мной написал",right:"Письмо написано мной вчера",why_uz:"Passivda fe’l takrorlanmaydi."}],exercises:[{id:"m9-pas-1",type:"transform",prompt:"Passivga o‘tkazing: «Рабочие строят дом»",answer:"Дом строится рабочими",explanation_uz:"НСВ → строится + Т.п."},{id:"m9-pas-2",type:"transform",prompt:"Passivga o‘tkazing: «Толстой написал роман»",answer:"Роман написан Толстым",explanation_uz:"СВ → написан + Т.п."},{id:"m9-pas-3",type:"fillBlank",prompt:"Билеты уже про́дан___.",answer:"ы",explanation_uz:"ko'plik → проданы."},{id:"m9-pas-4",type:"choose",prompt:"«Uy qurilmoqda» qanday?",answer:"Дом строится",choices:["Дом строится","Дом построен","Дом строил","Дом будет строен"],explanation_uz:"Jarayon → -ся."},{id:"m9-pas-5",type:"choose",prompt:"«Uy qurib bo‘lingan» qanday?",answer:"Дом построен",choices:["Дом построен","Дом строится","Дом строился","Дом строящийся"],explanation_uz:"Natija → qisqa kesim."},{id:"m9-pas-6",type:"errorHunt",prompt:"Xatoni toping: «Эта книга написана от известного автора»",answer:"Эта книга написана известным автором",explanation_uz:"Bajaruvchi — predlogsiz Т.п."},{id:"m9-pas-7",type:"fillBlank",prompt:"Магазин ___ закрыт вчера. (o‘tgan zamon)",answer:"был",explanation_uz:"был закрыт."}]},{id:"m9-numerals-decl",module:9,order:3,level:"B2",title:"Sonlarning turlanishi",subtitle:"с двумя друзьями, около пятисот",theory:[{heading:"Sonlar ham turlanadi",body:"Kelishik talab qilinganda son ham, ot ham turlanadi: два друга → с двумя друзьями (ikki do'st bilan), к двум друзьям.",table:[["Kelishik","2","5","100"],["И.п","два/две","пять","сто"],["Р.п","двух","пяти́","ста"],["Д.п","двум","пяти́","ста"],["Т.п","двумя́","пятью́","ста"],["П.п","о двух","о пяти́","о ста"]]},{heading:"оба/обе",body:"'ikkalasi': erkak/o'rta rod — оба (обоих, обоим...), ayol rod — обе (обеих, обеим...): обоими руками emas, обеими руками (рука — ж)."},{heading:"Tartib sonlar",body:"Tartib sonlar sifatdek turlanadi, murakkab tartib sonda faqat oxirgisi o'zgaradi: в две тысячи двадцать шестом году (2026-yilda)."}],comparisonWithUzbek:"O'zbek tilida son o'zgarmaydi ('ikki do'st bilan'), rus tilida esa son ham kelishik oladi: с двумя друзьями. Bu B2 darajaning eng mexanik yodlanadigan mavzusi.",examples:[{ru:"Я пришёл с двумя́ друзья́ми.",uz:"Ikki do'stim bilan keldim."},{ru:"В за́ле о́коло пятисо́т челове́к.",uz:"Zalda besh yuzga yaqin odam bor."},{ru:"Он говори́л о трёх пробле́мах.",uz:"U uchta muammo haqida gapirdi."},{ru:"Обе́ими рука́ми держи́сь!",uz:"Ikkala qo‘l bilan ushlan!"},{ru:"Э́то случи́лось в две ты́сячи деся́том году́.",uz:"Bu 2010-yilda sodir bo‘lgan."}],commonMistakes:[{wrong:"с два друзья",right:"с двумя друзьями",why_uz:"с + Т.п: son ham turlanadi."},{wrong:"обоими руками",right:"обеими руками",why_uz:"рука ж → обе/обеими."},{wrong:"в двадцать шестой году",right:"в двадцать шестом году",why_uz:"П.п: -ом."}],exercises:[{id:"m9-num-1",type:"transform",prompt:"Kerakli shaklga: «Я пришёл с (два) друзьями»",answer:"двумя",explanation_uz:"Т.п: двумя."},{id:"m9-num-2",type:"transform",prompt:"Kerakli shaklga: «Он говорил о (три) проблемах»",answer:"трёх",explanation_uz:"П.п: о трёх."},{id:"m9-num-3",type:"choose",prompt:"«ikkala qo‘l bilan» qanday?",answer:"обеими руками",choices:["обеими руками","обоими руками","обе руками","обоих руках"],explanation_uz:"рука ж → обеими."},{id:"m9-num-4",type:"fillBlank",prompt:"У него нет пят___ рублей. (5)",answer:"и",explanation_uz:"Р.п: пяти."},{id:"m9-num-5",type:"choose",prompt:"«2026-yilda» qanday tugaydi?",answer:"в две тысячи двадцать шестом году",choices:["в две тысячи двадцать шестом году","в две тысячи двадцать шесть году","в двух тысяч двадцать шестой год","в две тысячи двадцать шестой году"],explanation_uz:"Faqat oxirgi son turlanadi: шестом (П.п)."},{id:"m9-num-6",type:"errorHunt",prompt:"Xatoni toping: «Мы говорили о два фильма»",answer:"Мы говорили о двух фильмах",explanation_uz:"о + П.п: двух фильмах."}]},{id:"m9-aspect-prefixes",module:9,order:4,level:"B2",title:"Prefikslar ma'nolari",subtitle:"поработать, заговорить, переделать",theory:[{heading:"Prefiks fe'l ma'nosini boyitadi",body:"Bir fe'lga turli prefikslar turli ma'no beradi — bu rus leksikasining yadrosi.",table:[["Prefiks","Ma'no","Misol"],["по-","biroz / qisqa","порабо́тать — biroz ishlamoq"],["за-","boshlanish","заговори́ть — gapira boshlamoq"],["пере-","qayta / ortiqcha","переде́лать — qayta qilmoq"],["до-","oxirigacha","дочита́ть — oxirigacha o‘qimoq"],["недо-","yetarli emas","недоспа́ть — uyquga to‘ymaslik"],["раз-/рас-","tarqalish/kuchayish","рассказа́ть, разгоре́ться"],["от-","tugatish/javob","отрабо́тать, отве́тить"]]},{heading:"Bir ildiz — o'nlab fe'l",body:"писать: написать (yozib bo'lmoq), переписать (qayta yozmoq), записать (yozib olmoq), подписать (imzolamoq), описать (tasvirlamoq), выписать (ko'chirib yozmoq). Prefikslarni bilish lug'atni portlatib kengaytiradi."}],comparisonWithUzbek:"O'zbek ko'makchi fe'llariga mos: 'biroz ishlaB OLmoq' = поработать, 'gapira BOSHLAmoq' = заговорить, 'qaytaDAN qilmoq' = переделать, 'o'qiB CHIQmoq' = дочитать/прочитать.",examples:[{ru:"Дава́й немно́го порабо́таем.",uz:"Kel, biroz ishlaylik."},{ru:"Все вдруг заговори́ли.",uz:"Hamma birdan gapira boshladi."},{ru:"Э́то на́до переде́лать.",uz:"Buni qayta qilish kerak."},{ru:"Я дочита́л кни́гу до конца́.",uz:"Kitobni oxirigacha o‘qib chiqdim."},{ru:"Запиши́ мой но́мер.",uz:"Raqamimni yozib ol."}],commonMistakes:[{wrong:"написать (yozib olmoq ma’nosida)",right:"записать",why_uz:"написать — yozib tugatmoq, записать — qayd qilib olmoq."},{wrong:"переписать (imzolamoq)",right:"подписать",why_uz:"под- = ostiga (imzo), пере- = qayta."}],exercises:[{id:"m9-pref-1",type:"choose",prompt:"«gapira boshladi» qanday?",answer:"заговорил",choices:["заговорил","поговорил","переговорил","договорил"],explanation_uz:"за- = boshlanish."},{id:"m9-pref-2",type:"choose",prompt:"«qayta qilmoq» qanday?",answer:"переделать",choices:["переделать","доделать","заделать","поделать"],explanation_uz:"пере- = qayta."},{id:"m9-pref-3",type:"choose",prompt:"«raqamni yozib ol» qanday?",answer:"запиши номер",choices:["запиши номер","напиши номер","подпиши номер","опиши номер"],explanation_uz:"записать — qayd qilmoq."},{id:"m9-pref-4",type:"choose",prompt:"«hujjatni imzolamoq»?",answer:"подписать документ",choices:["подписать документ","написать документ","переписать документ","выписать документ"],explanation_uz:"под- + писать = imzolamoq."},{id:"m9-pref-5",type:"fillBlank",prompt:"Я ___читал книгу до конца. (oxirigacha)",answer:"до",explanation_uz:"дочитать — oxirigacha."},{id:"m9-pref-6",type:"choose",prompt:"по- prefiksining asosiy ma’nosi?",answer:"biroz / qisqa muddat",choices:["biroz / qisqa muddat","boshlanish","qayta","tugatish"],explanation_uz:"погулять — biroz sayr qilmoq."},{id:"m9-pref-7",type:"translate",prompt:"Tarjima qiling: «Kel, biroz sayr qilaylik» (гулять)",answer:"Давай погуляем",explanation_uz:"по- + гулять."}]},{id:"m9-subjunctive",module:9,order:5,level:"B2",title:"Shart mayli chuqur: бы",subtitle:"Я бы хотел..., если бы..., чтобы...",theory:[{heading:"бы + o‘tgan zamon",body:"Istak, noreal holat, muloyim taklif — hammasi бы + o'tgan zamon shakli: Я бы хотел кофе (kofe olardim). Было бы хорошо... (yaxshi bo'lardi). На твоём месте я бы... (sening o'rningda men...)."},{heading:"если бы — noreal shart",body:"Ikkala qismda ham бы: Если бы у меня было время, я бы пришёл (vaqtim bo'lganida kelardim). O'tgan, hozirgi, kelasi — kontekstdan: rus tilida noreal shartda zamon farqi yo'q!"},{heading:"чтобы + бы ichida",body:"чтобы o'zi что+бы dan yasalgan, shuning uchun undan keyin doim o'tgan zamon: Я хочу, чтобы ты знал. Скажи ему, чтобы он не опаздывал."}],comparisonWithUzbek:"O'zbekcha '-ardi' shakliga mos: 'kelARDIm' = я бы пришёл, 'bo'lgANIDA' = если бы было. Muloyimlik uchun ham: 'xohlARDIm' = я бы хотел — bu xizmat ko'rsatishda juda foydali.",examples:[{ru:"Я бы хоте́л зарезерви́ровать сто́лик.",uz:"Stol band qilmoqchi edim. (muloyim)"},{ru:"Е́сли бы я знал, я бы помо́г.",uz:"Bilganimda yordam berardim."},{ru:"Бы́ло бы здо́рово встре́титься!",uz:"Uchrashsak zo‘r bo‘lardi!"},{ru:"На твоём ме́сте я бы извини́лся.",uz:"Sening o'rningda uzr so'rardim."},{ru:"Что бы ты сде́лал с миллио́ном?",uz:"Million bilan nima qilarding?"}],commonMistakes:[{wrong:"Если бы я буду знать",right:"Если бы я знал",why_uz:"бы dan keyin faqat o'tgan zamon shakli."},{wrong:"Я бы хочу",right:"Я бы хотел",why_uz:"бы + хотел (o‘tgan shakl), хочу emas."},{wrong:"Если я бы знал, я помог",right:"Если бы я знал, я бы помог",why_uz:"Noreal shartda ikkala qismda ham бы."}],exercises:[{id:"m9-subj-1",type:"fillBlank",prompt:"Я ___ хотел чашку кофе. (muloyim istak)",answer:"бы",explanation_uz:"Я бы хотел — muloyim."},{id:"m9-subj-2",type:"transform",prompt:"Noreal shartga: «Если у меня есть время, я приду»",answer:"Если бы у меня было время, я бы пришёл",explanation_uz:"если бы + было, я бы + пришёл."},{id:"m9-subj-3",type:"choose",prompt:"Qaysi gap to'g'ri?",answer:"Если бы я знал, я бы сказал",choices:["Если бы я знал, я бы сказал","Если бы я знаю, я бы скажу","Если бы я буду знать, я скажу","Если я бы знал, я сказал"],explanation_uz:"Ikkala qism ham бы + o'tgan zamon."},{id:"m9-subj-4",type:"translate",prompt:"Tarjima qiling: «Sening o‘rningda men kutardim» (ждать)",answer:"На твоём месте я бы ждал",explanation_uz:"на твоём месте я бы..."},{id:"m9-subj-5",type:"errorHunt",prompt:"Xatoni toping: «Я хочу, чтобы ты придёшь»",answer:"Я хочу, чтобы ты пришёл",explanation_uz:"чтобы + o‘tgan shakl."},{id:"m9-subj-6",type:"fillBlank",prompt:"Было ___ хорошо поехать на море.",answer:"бы",explanation_uz:"Было бы хорошо — orzu."}]},{id:"m9-bookish-preps",module:9,order:6,level:"B2",title:"Kitobiy predloglar",subtitle:"благодаря, несмотря на, в течение",theory:[{heading:"Rasmiy uslub predloglari",body:"B2+ matnlarda (yangiliklar, hujjatlar) keng ishlatiladi:",table:[["Predlog","Kelishik","Ma'no","Misol"],["благодаря́","Д.п","tufayli (ijobiy)","благодаря́ тебе́"],["из-за","Р.п","sababli (salbiy)","из-за дождя́"],["несмотря́ на","В.п","-ga qaramay","несмотря́ на пого́ду"],["в тече́ние","Р.п","davomida","в тече́ние го́да"],["по́сле","Р.п","keyin","по́сле рабо́ты"],["всле́дствие","Р.п","oqibatida","всле́дствие ава́рии"],["согла́сно","Д.п","muvofiq","согла́сно пла́ну"]]},{heading:"благодаря vs из-за",body:"Ikkalasi ham 'sababli', lekin благодаря — yaxshi natija (rahmat aytgudek sabab), из-за — yomon natija: Благодаря тебе мы успели. Из-за тебя мы опоздали."}],comparisonWithUzbek:"'tufayli' (ijobiy) = благодаря + Д.п, 'sababli/dastidan' (salbiy) = из-за + Р.п, '-ga qaramay' = несмотря на + В.п, 'davomida' = в течение + Р.п, 'muvofiq' = согласно + Д.п (Р.п EMAS — eng keng tarqalgan xato!).",examples:[{ru:"Благодаря́ учи́телю я сдал экза́мен.",uz:"O'qituvchi tufayli imtihondan o'tdim."},{ru:"Из-за про́бок я опозда́л.",uz:"Tirbandlik sababli kechikdim."},{ru:"Несмотря́ на дождь, мы пошли́ гуля́ть.",uz:"Yomg'irga qaramay sayrga chiqdik."},{ru:"В тече́ние неде́ли всё бу́дет гото́во.",uz:"Bir hafta davomida hammasi tayyor bo‘ladi."},{ru:"Согла́сно догово́ру, опла́та в конце́ ме́сяца.",uz:"Shartnomaga muvofiq to'lov oy oxirida."}],commonMistakes:[{wrong:"благодаря дождя (kechikish sababi)",right:"из-за дождя",why_uz:"Salbiy sabab — из-за; благодаря faqat ijobiy."},{wrong:"согласно договора",right:"согласно договору",why_uz:"согласно + Д.п (rus tilida ham mashhur xato!)."},{wrong:"несмотря на дождя",right:"несмотря на дождь",why_uz:"несмотря на + В.п."}],exercises:[{id:"m9-bp-1",type:"choose",prompt:"___ тебе мы выиграли! (tufayli)",answer:"Благодаря",choices:["Благодаря","Из-за","Несмотря на","Вследствие"],explanation_uz:"Ijobiy natija → благодаря."},{id:"m9-bp-2",type:"choose",prompt:"___ дождя мы опоздали. (sababli)",answer:"Из-за",choices:["Из-за","Благодаря","Согласно","В течение"],explanation_uz:"Salbiy → из-за."},{id:"m9-bp-3",type:"fillBlank",prompt:"Несмотря ___ холод, он пришёл.",answer:"на",explanation_uz:"несмотря на + В.п."},{id:"m9-bp-4",type:"transform",prompt:"Kerakli shaklga: «согласно (план)»",answer:"плану",explanation_uz:"согласно + Д.п."},{id:"m9-bp-5",type:"transform",prompt:"Kerakli shaklga: «в течение (год)»",answer:"года",explanation_uz:"в течение + Р.п."},{id:"m9-bp-6",type:"errorHunt",prompt:"Xatoni toping: «Благодаря пробкам я опоздал на работу»",answer:"Из-за пробок я опоздал на работу",explanation_uz:"Kechikish — salbiy → из-за."},{id:"m9-bp-7",type:"translate",prompt:"Tarjima qiling: «Sovuqqa qaramay biz keldik» (холод)",answer:"Несмотря на холод, мы пришли",explanation_uz:"несмотря на + В.п."}]},{id:"m9-word-order",module:9,order:7,level:"B2",title:"So'z tartibi va urg'u mantiqlari",subtitle:"Yangi axborot gap oxirida",theory:[{heading:"Erkin, lekin mantiqli",body:"Rus tilida so'z tartibi erkin, lekin ma'no soyasini o'zgartiradi. Asosiy qoida: YANGI va MUHIM axborot gap OXIRIDA turadi: Книга на столе (kitob QAYERDA? — stolda) vs На столе книга (stolda NIMA bor? — kitob).",table:[["Gap","Savol-javob mantiqi"],["Кни́га на столе́.","Kitob qayerda? — Stolda."],["На столе́ кни́га.","Stolda nima bor? — Kitob."],["Я е́ду за́втра.","Qachon ketaman? — Ertaga."],["За́втра е́ду я.","Ertaga kim ketadi? — Men."]]},{heading:"Inversiya his-tuyg‘uda",body:"She'riy/emotsional nutqda tartib buziladi: Хорошая сегодня погода! (qanday yaxshi havo!). Bu og'zaki nutqqa joziba beradi."}],comparisonWithUzbek:"O'zbek tilida tartib qat'iyroq (ega-to'ldiruvchi-kesim). Ruschada kesim o'rtada erkin yuradi, lekin 'yangi axborot oxirida' qoidasi o'zbek tiliga ham xos — shu intuitsiyangizga ishoning.",examples:[{ru:"В э́том до́ме живёт мой друг.",uz:"Bu uyda do'stim yashaydi. (KIM yashashi yangi)"},{ru:"Мой друг живёт в э́том до́ме.",uz:"Do'stim shu uyda yashaydi. (QAYERDA yangi)"},{ru:"За́втра бу́дет экза́мен.",uz:"Ertaga imtihon bo‘ladi."},{ru:"Экза́мен бу́дет за́втра.",uz:"Imtihon ertaga bo‘ladi."}],commonMistakes:[{wrong:"Har doim bir xil qolip ishlatish",right:"Yangi axborotni oxiriga qo'yish",why_uz:"Savolga qarab tartib o'zgaradi — javob doim oxirida."}],exercises:[{id:"m9-wo-1",type:"choose",prompt:"«Stolda NIMA bor?» javobiga mos gap:",answer:"На столе книга",choices:["На столе книга","Книга на столе","Стол на книге","Книга стол на"],explanation_uz:"Yangi axborot (книга) oxirida."},{id:"m9-wo-2",type:"choose",prompt:"«Kitob QAYERDA?» javobiga mos gap:",answer:"Книга на столе",choices:["Книга на столе","На столе книга","На книге стол","Стол книга на"],explanation_uz:"Yangi axborot (на столе) oxirida."},{id:"m9-wo-3",type:"choose",prompt:"«Ertaga KIM ketadi?» javobi:",answer:"Завтра еду я",choices:["Завтра еду я","Я еду завтра","Еду я завтра","Я завтра еду"],explanation_uz:"я — yangi axborot, oxirida."},{id:"m9-wo-4",type:"sentenceBuilder",prompt:"«Bu shaharda buvim yashaydi» (KIM — yangi)",answer:"В этом городе живёт моя бабушка",tokens:["живёт","В","городе","бабушка","этом","моя"],explanation_uz:"Yangi axborot — бабушка — gap oxirida."},{id:"m9-wo-5",type:"choose",prompt:"Emotsional gap qaysi?",answer:"Хорошая сегодня погода!",choices:["Хорошая сегодня погода!","Сегодня хорошая погода.","Погода сегодня хорошая.","Сегодня погода хорошая."],explanation_uz:"Sifatni boshga chiqarish — his-tuyg‘u."}]},{id:"m9-verb-government",module:9,order:8,level:"B2",title:"Fe'l boshqaruvi",subtitle:"ждать кого? гордиться чем? зависеть от чего?",theory:[{heading:"Har fe'l o'z kelishigini talab qiladi",body:"Fe'lni kelishigi va predlogi bilan birga yodlash — B2 ning oltin qoidasi.",table:[["Fe'l","Boshqaruv","Misol"],["жда́ть","кого/что (В/Р)","жду дру́га, жду отве́та"],["горди́ться","кем/чем (Т)","горжу́сь сы́ном"],["зави́сеть","от кого/чего (Р)","зави́сит от пого́ды"],["ве́рить","кому (Д) / во что (В)","ве́рю тебе́, ве́рю в успе́х"],["боя́ться","кого/чего (Р)","бою́сь темноты́"],["поздравля́ть","кого с чем","поздравля́ю с пра́здником"],["уча́ствовать","в чём (П)","уча́ствую в конку́рсе"],["привыка́ть","к чему (Д)","привы́к к хо́лоду"]]}],comparisonWithUzbek:"O'zbekchadan to'g'ridan-to'g'ri ko'chirish ishlamaydi: 'senGA ishonaman' = верю тебе (Д.п — mos!), lekin 'muvaffaqiyatGA ishonaman' = верю В успех (в + В.п). 'imtihonDAN qo'rqaman' = боюсь экзамена (Р.п, -dan predlogsiz).",examples:[{ru:"Я горжу́сь свое́й семьёй.",uz:"Men oilam bilan faxrlanaman."},{ru:"Всё зави́сит от тебя́.",uz:"Hammasi senga bog'liq."},{ru:"Поздравля́ю тебя́ с днём рожде́ния!",uz:"Tug'ilgan kuning bilan tabriklayman!"},{ru:"Он бои́тся выступа́ть пе́ред людьми́.",uz:"U odamlar oldida chiqishdan qo‘rqadi."},{ru:"Я привы́к к ра́ннему подъёму.",uz:"Erta turishga o‘rganib qolganman."}],commonMistakes:[{wrong:"горжусь на сына",right:"горжусь сыном",why_uz:"гордиться + Т.п predlogsiz."},{wrong:"зависит на погоды",right:"зависит от погоды",why_uz:"зависеть от + Р.п."},{wrong:"поздравляю тебя на праздник",right:"поздравляю тебя с праздником",why_uz:"поздравлять с + Т.п."},{wrong:"верю в тебе",right:"верю тебе / верю в тебя",why_uz:"верить кому (Д.п) yoki верить в кого (В.п)."}],exercises:[{id:"m9-vg-1",type:"fillBlank",prompt:"Я горжусь сво___ работой. (Т.п)",answer:"ей",explanation_uz:"гордиться чем — своей работой."},{id:"m9-vg-2",type:"fillBlank",prompt:"Всё зависит ___ погоды.",answer:"от",explanation_uz:"зависеть от + Р.п."},{id:"m9-vg-3",type:"fillBlank",prompt:"Поздравляю тебя ___ Новым годом!",answer:"с",explanation_uz:"поздравлять с + Т.п."},{id:"m9-vg-4",type:"transform",prompt:"Kerakli shaklga: «Я боюсь (экзамен)»",answer:"экзамена",explanation_uz:"бояться + Р.п."},{id:"m9-vg-5",type:"transform",prompt:"Kerakli shaklga: «Мы участвуем в (конкурс)»",answer:"конкурсе",explanation_uz:"участвовать в + П.п."},{id:"m9-vg-6",type:"errorHunt",prompt:"Xatoni toping: «Я верю в тебе»",answer:"Я верю тебе",explanation_uz:"верить кому — Д.п (yoki верю в тебя)."},{id:"m9-vg-7",type:"fillBlank",prompt:"Он привык ___ холоду.",answer:"к",explanation_uz:"привыкать к + Д.п."},{id:"m9-vg-8",type:"translate",prompt:"Tarjima qiling: «Men javobingni kutyapman» (ждать, ответ)",answer:"Я жду твоего ответа",explanation_uz:"ждать + mavhum narsa Р.п."}]}],g=[{id:"m10-complex-syntax",module:10,order:1,level:"C1",title:"Murakkab kitobiy sintaksis",subtitle:"причём, вследствие чего, поскольку",theory:[{heading:"Kitobiy bog‘lovchilar",body:"C1 matnlarda oddiy потому что o'rniga boyroq vositalar ishlatiladi:",table:[["Bog'lovchi","Ma'no","Misol"],["поско́льку","modomiki","Поско́льку вре́мени ма́ло, начнём."],["причём","shu bilan birga","Он рабо́тает, причём о́чень мно́го."],["всле́дствие чего́","oqibatida","Шёл дождь, всле́дствие чего́ матч отмени́ли."],["в то вре́мя как","holbuki","Он молча́л, в то вре́мя как все говори́ли."],["и́бо","zero (eskirgan)","Бу́дь терпели́в, и́бо успе́х тре́бует вре́мени."],["благодаря́ тому́ что","tufayli","Благодаря́ тому́ что он помо́г..."]]},{heading:"Murakkab to'ldiruvchili gaplar",body:"то bilan kengaytirilgan qoliplar: дело в том, что... (gap shundaki...), речь идёт о том, что... (gap ... haqida ketyapti), я уверен в том, что... — predlog kelishik talab qilganda что oldidan то keladi."}],comparisonWithUzbek:"'gap shundaki' = дело в том, что; 'shu bilan birga' = причём; 'modomiki' = поскольку. O'zbek kitobiy uslubidagi 'zero', 'binobarin' kabi so'zlarning ruscha muqobillari shular.",examples:[{ru:"Де́ло в том, что я уже́ купи́л биле́ты.",uz:"Gap shundaki, men allaqachon chipta olganman."},{ru:"Он отли́чный специали́ст, причём о́чень скро́мный.",uz:"U zo'r mutaxassis, shu bilan birga juda kamtar."},{ru:"Поско́льку все согла́сны, начнём.",uz:"Modomiki hamma rozi ekan, boshlaylik."},{ru:"Речь идёт о том, что́бы измени́ть пра́вила.",uz:"Gap qoidalarni o'zgartirish haqida ketyapti."}],commonMistakes:[{wrong:"Я уверен, в что он придёт",right:"Я уверен в том, что он придёт",why_uz:"Predlogdan keyin что emas, то + что: в том, что."},{wrong:"Дело что я занят",right:"Дело в том, что я занят",why_uz:"To'liq qolip: дело в том, что."}],exercises:[{id:"m10-cs-1",type:"fillBlank",prompt:"Дело в ___, что я уже знал ответ.",answer:"том",explanation_uz:"дело в том, что."},{id:"m10-cs-2",type:"choose",prompt:"«modomiki / -ganligi uchun» (kitobiy)?",answer:"поскольку",choices:["поскольку","причём","ибо","зато"],explanation_uz:"поскольку — kitobiy sabab."},{id:"m10-cs-3",type:"choose",prompt:"«shu bilan birga» qaysi so‘z?",answer:"причём",choices:["причём","отчего","поэтому","ибо"],explanation_uz:"причём — qo'shimcha kuchaytiruvchi fakt."},{id:"m10-cs-4",type:"fillBlank",prompt:"Я уверен в ___, что всё получится.",answer:"том",explanation_uz:"уверен в том, что."},{id:"m10-cs-5",type:"errorHunt",prompt:"Xatoni toping: «Речь идёт о что нужно делать»",answer:"Речь идёт о том, что нужно делать",explanation_uz:"о + том, что."},{id:"m10-cs-6",type:"translate",prompt:"Tarjima qiling: «Gap shundaki, vaqtimiz kam»",answer:"Дело в том, что у нас мало времени",explanation_uz:"дело в том, что + sabab."}]},{id:"m10-phraseology",module:10,order:2,level:"C1",title:"Frazeologizmlar va idiomalar",subtitle:"бить баклуши, как рыба в воде",theory:[{heading:"Eng kerakli idiomalar",body:"Idiomalarni so'zma-so'z tarjima qilib bo'lmaydi — yaxlit yodlanadi:",table:[["Idioma","Ma'no","So'zma-so'z"],["бить баклу́ши","bekorchilik qilmoq","cho'p urmoq"],["как ры́ба в воде́","o'z muhitida","suvdagi baliqdek"],["взять себя́ в ру́ки","o'zini qo'lga olmoq","o'zini qo'lga olmoq"],["води́ть за́ нос","laqillatmoq","burnidan yetaklamoq"],["не в свое́й таре́лке","o'zini noqulay sezmoq","o'z likopchasida emas"],["заруби́ть на носу́","quloqqa quyib olmoq","burunga o‘yib yozmoq"],["де́лать из му́хи слона́","pashshadan fil yasamoq","xuddi shu!"],["ни пу́ха ни пера́","omad tilayman","na par, na pat"]]},{heading:"Javob odobi",body:"Ни пуха ни пера! ga javob — К чёрту! (an'anaviy, qo'pollik emas). Спасибо deb javob berish — irim bo'yicha omadni qochirish."}],comparisonWithUzbek:"Ba'zilari o'zbekcha bilan aynan mos: делать из мухи слона = pashshadan fil yasamoq, взять себя в руки = o'zini qo'lga olmoq. Bunday mosliklarni topish idiomani bir umrga yodda qoldiradi.",examples:[{ru:"Хва́тит бить баклу́ши — рабо́тать пора́!",uz:"Bekorchilikni bas qil — ishlash vaqti!"},{ru:"На сце́не она́ как ры́ба в воде́.",uz:"Sahnada u suvdagi baliqdek erkin."},{ru:"Возьми́ себя́ в ру́ки и продолжа́й.",uz:"O'zingni qo'lga ol va davom et."},{ru:"Он во́дит тебя́ за́ нос!",uz:"U seni laqillatyapti!"},{ru:"Не де́лай из му́хи слона́.",uz:"Pashshadan fil yasama."}],commonMistakes:[{wrong:"Idiomani so'zma-so'z tarjima qilish",right:"Yaxlit ekvivalent topish",why_uz:"'бить баклуши' ni 'cho'p urmoq' deb tarjima qilsangiz hech kim tushunmaydi."},{wrong:"Ни пуха ни пера! → Спасибо!",right:"К чёрту!",why_uz:"An'anaviy javob — К чёрту."}],exercises:[{id:"m10-phr-1",type:"choose",prompt:"«бить баклуши» nimani anglatadi?",answer:"bekorchilik qilmoq",choices:["bekorchilik qilmoq","urishmoq","cho'p yig'moq","shoshilmoq"],explanation_uz:"Bekor yurmoq."},{id:"m10-phr-2",type:"choose",prompt:"«pashshadan fil yasamoq» ruscha?",answer:"делать из мухи слона",choices:["делать из мухи слона","водить за нос","бить баклуши","брать быка за рога"],explanation_uz:"Aynan mos idioma."},{id:"m10-phr-3",type:"choose",prompt:"«Ни пуха ни пера!» ga javob?",answer:"К чёрту!",choices:["К чёрту!","Спасибо!","Пожалуйста!","Не за что!"],explanation_uz:"An'anaviy irim-javob."},{id:"m10-phr-4",type:"choose",prompt:"«u seni laqillatyapti» qanday?",answer:"он водит тебя за нос",choices:["он водит тебя за нос","он бьёт тебя баклуши","он берёт тебя в руки","он делает тебя слоном"],explanation_uz:"водить за нос — aldab yurmoq."},{id:"m10-phr-5",type:"fillBlank",prompt:"Возьми себя в ___ и успокойся.",answer:"руки",explanation_uz:"взять себя в руки."},{id:"m10-phr-6",type:"choose",prompt:"«o‘zini noqulay sezmoq»?",answer:"не в своей тарелке",choices:["не в своей тарелке","как рыба в воде","ни пуха ни пера","на носу"],explanation_uz:"чувствовать себя не в своей тарелке."}]},{id:"m10-formal-style",module:10,order:3,level:"C1",title:"Rasmiy va ilmiy uslub",subtitle:"Hujjat, ariza, rasmiy xat tili",theory:[{heading:"Rasmiy uslub belgilari",body:"1) Passiv: Заявление рассматривается (ariza ko'rib chiqilmoqda). 2) Otlashgan fe'llar: рассмотрение, предоставление, осуществление. 3) Qoliplar: в связи с (munosabati bilan), в соответствии с (muvofiq), по причине (sababli).",table:[["Og'zaki","Rasmiy","Ma'no"],["помо́чь","оказа́ть по́мощь","yordam ko'rsatmoq"],["реши́ть","приня́ть реше́ние","qaror qabul qilmoq"],["уча́ствовать","принима́ть уча́стие","ishtirok etmoq"],["спроси́ть","обрати́ться с вопро́сом","savol bilan murojaat qilmoq"]]},{heading:"Rasmiy xat qoliplari",body:"Уважаемый Иван Иванович! (Hurmatli...). Прошу Вас рассмотреть... (... ko'rib chiqishingizni so'rayman). Заранее благодарю (oldindan minnatdorman). С уважением, ... (hurmat bilan). Rasmiy Вы doim bosh harf bilan."}],comparisonWithUzbek:"O'zbek rasmiy uslubidagi 'amalga oshirmoq', 'taqdim etmoq' kabi konstruksiyalarga mos: осуществлять, предоставлять. Ariza yozish qolipi ham o'xshash: 'so'rayman' = Прошу Вас.",examples:[{ru:"Прошу́ Вас предоста́вить мне о́тпуск.",uz:"Menga ta'til berishingizni so'rayman."},{ru:"В свя́зи с боле́знью я не смогу́ прийти́.",uz:"Kasallik munosabati bilan kela olmayman."},{ru:"Ва́ше заявле́ние бу́дет рассмо́трено в тече́ние трёх дней.",uz:"Arizangiz uch kun ichida ko'rib chiqiladi."},{ru:"С уваже́нием, Алише́р Усма́нов.",uz:"Hurmat bilan, Alisher Usmanov."}],commonMistakes:[{wrong:"Привет, директор! (rasmiy xatda)",right:"Уважаемый + ism-sharif!",why_uz:"Rasmiy murojaat qolipi qat’iy."},{wrong:"я хочу отпуск (arizada)",right:"Прошу предоставить мне отпуск",why_uz:"Ariza tili — прошу + infinitiv."}],exercises:[{id:"m10-fs-1",type:"choose",prompt:"Rasmiy xat qanday boshlanadi?",answer:"Уважаемый Иван Иванович!",choices:["Уважаемый Иван Иванович!","Привет, Иван!","Эй, директор!","Здорово, Иваныч!"],explanation_uz:"Уважаемый + ism-sharif."},{id:"m10-fs-2",type:"choose",prompt:"«ishtirok etmoq» rasmiy varianti?",answer:"принимать участие",choices:["принимать участие","участвоваться","быть внутри","делать участие"],explanation_uz:"принимать участие в + П.п."},{id:"m10-fs-3",type:"fillBlank",prompt:"В связи ___ болезнью я отсутствовал.",answer:"с",explanation_uz:"в связи с + Т.п."},{id:"m10-fs-4",type:"translate",prompt:"Tarjima qiling: «Ta’til berishingizni so‘rayman» (отпуск)",answer:"Прошу Вас предоставить мне отпуск",explanation_uz:"Ariza qolipi."},{id:"m10-fs-5",type:"choose",prompt:"Xat oxirida nima yoziladi?",answer:"С уважением",choices:["С уважением","Пока","Целую","Удачи"],explanation_uz:"С уважением — rasmiy yakun."},{id:"m10-fs-6",type:"errorHunt",prompt:"Xatoni toping (rasmiy): «Я хочу что вы дали мне отпуск»",answer:"Прошу Вас предоставить мне отпуск",explanation_uz:"Rasmiy ariza qolipida yoziladi."}]},{id:"m10-colloquial",module:10,order:4,level:"C1",title:"So'zlashuv uslubi",subtitle:"Ну, давай, короче, ладно",theory:[{heading:"Jonli nutq so'zlari",body:"Real suhbatni tushunish uchun shart:",table:[["So'z","Ma'no","Misol"],["ну","xo'sh / eh","Ну, что де́лать бу́дем?"],["дава́й","kel / xayr","Дава́й встре́тимся! / Ну всё, дава́й!"],["коро́че","qisqasi","Коро́че, я не приду́."],["ла́дно","mayli","Ла́дно, договори́лись."],["ка́жется","shekilli","Он, ка́жется, ушёл."],["вро́де","aftidan","Вро́де всё гото́во."],["чуть не","sal qoldi","Я чуть не упа́л."],["да ну!","yo'g'-e!","Да ну! Не мо́жет быть!"]]},{heading:"Ellipsis — tushirib qoldirish",body:"Og'zaki nutqda gap qisqaradi: Ты куда? (idёшь tushirilgan — qayoqqa ketyapsan?). Мне два кофе (дайте tushirilgan). Вы выходите? (avtobusda). Bu xato emas — jonli norma."}],comparisonWithUzbek:"'qisqasi' = короче, 'mayli' = ладно, 'shekilli' = кажется, 'sal qoldi' = чуть не, 'yo'g'-e' = да ну. 'Давай' xayrlashuvda ham ishlatiladi — o'zbekcha 'bo'pti, ko'rishamiz' kabi.",examples:[{ru:"Ну что, пошли́?",uz:"Xo'sh, ketdikmi?"},{ru:"Коро́че, де́ло бы́ло так...",uz:"Qisqasi, ish bunday bo'lgan edi..."},{ru:"Я чуть не опозда́л на по́езд!",uz:"Poyezdga sal qolsa kechikardim!"},{ru:"Ла́дно, дава́й, до за́втра!",uz:"Mayli, bo'pti, ertagacha!"},{ru:"Ты куда́? — Домо́й.",uz:"Qayoqqa? — Uyga."}],commonMistakes:[{wrong:"Rasmiy xatda 'короче' ishlatish",right:"Faqat og'zaki nutqda",why_uz:"So'zlashuv so'zlari yozma rasmiy matnga kirmaydi."},{wrong:"давай ni faqat «kel» deb tushunish",right:"xayrlashuvda ham: Ну всё, давай!",why_uz:"Kontekstga qarang."}],exercises:[{id:"m10-col-1",type:"choose",prompt:"«qisqasi» qanday?",answer:"короче",choices:["короче","длиннее","ладно","вроде"],explanation_uz:"короче — qisqasi."},{id:"m10-col-2",type:"choose",prompt:"«Я чуть не упал» nimani anglatadi?",answer:"sal qolsa yiqilardim",choices:["sal qolsa yiqilardim","ozgina yiqildim","umuman yiqilmadim","sekin yiqildim"],explanation_uz:"чуть не — sal qoldi (sodir bo‘lmadi)."},{id:"m10-col-3",type:"choose",prompt:"Suhbat oxirida «Ну всё, давай!» nimani bildiradi?",answer:"xayrlashuv",choices:["xayrlashuv","biror narsa berishni so‘rash","jahl","taklif boshlanishi"],explanation_uz:"давай — og'zaki xayrlashuv."},{id:"m10-col-4",type:"choose",prompt:"«mayli» qanday?",answer:"ладно",choices:["ладно","плохо","строго","трудно"],explanation_uz:"ладно — rozi bo‘lish."},{id:"m10-col-5",type:"fillBlank",prompt:"Он, ка___, уже ушёл. (shekilli)",answer:"жется",explanation_uz:"кажется — shekilli."},{id:"m10-col-6",type:"translate",prompt:"Tarjima qiling (og‘zaki): «Qayoqqa?» (ketayotgan odamga)",answer:"Ты куда?",explanation_uz:"Ellipsis: идёшь tushiriladi."}]},{id:"m10-modal-particles",module:10,order:5,level:"C1",title:"Modal yuklamalar chuqur",subtitle:"разве, неужели, уж, ведь, же",theory:[{heading:"Hayrat va shubha",body:"разве — shubhali savol (nahotki, menimcha unday emas): Разве он врач? неужели — kuchli hayrat (nahotki?!): Неужели ты выиграл?!"},{heading:"Ta'kid yuklamalari",body:"же — axir/o'sha: Я же говорил! (men aytgandim-ku!). ведь — axir (sababga ishora): Оденься, ведь холодно. уж — kuchaytirish: Уж он-то знает (u-ku aniq biladi). -ка — buyruqni yumshatish: Скажи-ка... (ayt-chi...).",table:[["Yuklama","Ma'no","Misol"],["ра́зве","nahotki (shubha)","Ра́зве э́то пра́вда?"],["неуже́ли","nahotki?! (hayrat)","Неуже́ли ты не знал?!"],["же","-ku / axir","Ты же обеща́л!"],["ведь","axir (sabab)","Не спеши́, ведь вре́мя есть."],["-ка","-chi (yumshatish)","Посмотри́-ка сюда́!"]]}],comparisonWithUzbek:"O'zbek tilida aynan mos yuklamalar bor: '-ku' = же, 'axir' = ведь, 'nahotki' = неужели/разве, '-chi' = -ка. Ayt-chi = скажи-ка, bilarding-ku = ты же знал. Bu mosliklar tufayli C1 yuklamalari o'zbeklar uchun oson!",examples:[{ru:"Ра́зве ты не слы́шал но́вость?",uz:"Nahotki yangilikni eshitmagan bo‘lsang?"},{ru:"Неуже́ли э́то всё беспла́тно?!",uz:"Nahotki bularning hammasi bepul?!"},{ru:"Я же тебе́ говори́л!",uz:"Men senga aytgandim-ku!"},{ru:"Не волну́йся, ведь всё хорошо́.",uz:"Xavotir olma, axir hammasi yaxshi."},{ru:"Расскажи́-ка, что случи́лось.",uz:"Aytib ber-chi, nima bo‘ldi."}],commonMistakes:[{wrong:"же ni gap boshiga qo‘yish",right:"ta'kidlangan so'zdan keyin",why_uz:"же doim urg‘u tushgan so‘zdan keyin: Я же / Ты же."},{wrong:"разве va неужели ni farqlamaslik",right:"разве — yengil shubha, неужели — kuchli hayrat",why_uz:"Intonatsiya darajasi har xil."}],exercises:[{id:"m10-mp-1",type:"fillBlank",prompt:"Я ___ тебе говорил! (-ku)",answer:"же",explanation_uz:"же — ta’kid."},{id:"m10-mp-2",type:"choose",prompt:"«Nahotki yutgan bo‘lsang?!» (kuchli hayrat)",answer:"Неужели ты выиграл?!",choices:["Неужели ты выиграл?!","Разве ты выиграл?","Ведь ты выиграл!","Ты же выиграл."],explanation_uz:"Kuchli hayrat → неужели."},{id:"m10-mp-3",type:"fillBlank",prompt:"Оденься теплее, ___ на улице мороз. (axir)",answer:"ведь",explanation_uz:"ведь — sababga ishora."},{id:"m10-mp-4",type:"choose",prompt:"«ayt-chi» qanday?",answer:"скажи-ка",choices:["скажи-ка","скажи же","разве скажи","скажи ведь"],explanation_uz:"-ка buyruqni yumshatadi."},{id:"m10-mp-5",type:"choose",prompt:"же qayerda turadi?",answer:"ta'kidlangan so'zdan keyin",choices:["ta'kidlangan so'zdan keyin","doim gap boshida","doim gap oxirida","fe'ldan oldin"],explanation_uz:"Я же, ты же, он же..."},{id:"m10-mp-6",type:"translate",prompt:"Tarjima qiling: «Sen va’da bergan eding-ku!» (обещать)",answer:"Ты же обещал!",explanation_uz:"же = -ku."}]},{id:"m10-word-formation",module:10,order:6,level:"C1",title:"So'z yasalishi",subtitle:"-ость, -ние, -тель, без-, не-",theory:[{heading:"Suffikslar tizimi",body:"Suffiksni bilish notanish so'zni 'ochadi':",table:[["Suffiks","Yasaydi","Misol"],["-ость","mavhum ot (-lik)","но́вый → но́вость, ста́рый → ста́рость"],["-ние/-тие","ish-harakat oti","чита́ть → чте́ние, разви́ть → разви́тие"],["-тель","bajaruvchi (-chi)","учи́ть → учи́тель, писа́ть → писа́тель"],["-ик/-ник","shaxs/predmet","исто́рия → исто́рик, чай → ча́йник"],["-ка","ayol shaxs / kichraytirish","студе́нт → студе́нтка"],["-оват-","biroz (-roq)","сла́дкий → сладкова́тый"]]},{heading:"Prefiks + sifat",body:"без-/бес- = -siz: безрабо́тный (ishsiz), бесполе́зный (foydasiz). не- = inkor: неинтере́сный. пре- = juda: премудрый. анти-, сверх-, меж- — xalqaro prefikslar."}],comparisonWithUzbek:"-ость = '-lik' (yangiLIK = новость), -тель = '-chi' (yozuvCHI = писатель), без- = '-siz' (ishSIZ = безработный), -оват = '-roq' (shirinROQ = сладковатый). Bu paralellarni bilish lug'atsiz o'qish imkonini beradi.",examples:[{ru:"ста́рость — не ра́дость",uz:"qarilik — quvonch emas (maqol)"},{ru:"безрабо́тица растёт",uz:"ishsizlik oshyapti"},{ru:"чте́ние развива́ет мышле́ние",uz:"o'qish tafakkurni rivojlantiradi"},{ru:"э́тот суп солонова́тый",uz:"bu sho'rva sho'rroq"},{ru:"преподава́тель университе́та",uz:"universitet o'qituvchisi"}],commonMistakes:[{wrong:"новость ni faqat «yangilik xabari» deb bilish",right:"-ость = mavhum '-lik'",why_uz:"Suffiks ma'nosini bilsangiz molodость, смелость... hammasi ochiladi."},{wrong:'бесполезный → "juda foydali"',right:"foydaSIZ",why_uz:"без-/бес- inkor, kuchaytirish emas."}],exercises:[{id:"m10-wf-1",type:"transform",prompt:"Ot yasang: молодой → (yoshlik)",answer:"молодость",explanation_uz:"-ость."},{id:"m10-wf-2",type:"transform",prompt:"Bajaruvchi yasang: строить → (quruvchi)",answer:"строитель",explanation_uz:"-тель."},{id:"m10-wf-3",type:"choose",prompt:"«ishsiz» qanday?",answer:"безработный",choices:["безработный","неработа","распработный","околоработный"],explanation_uz:"без- = -siz."},{id:"m10-wf-4",type:"choose",prompt:"«сладковатый» nimani anglatadi?",answer:"shirinroq / biroz shirin",choices:["shirinroq / biroz shirin","juda shirin","shirin emas","eng shirin"],explanation_uz:"-оват- = biroz."},{id:"m10-wf-5",type:"transform",prompt:"Ish-harakat oti: читать → ...",answer:"чтение",explanation_uz:"чтение — o‘qish (jarayon)."},{id:"m10-wf-6",type:"choose",prompt:"«чайник» so‘zi qanday yasalgan?",answer:"чай + -ник (predmet)",choices:["чай + -ник (predmet)","чайн + ик","ча + йник","bu yasama so'z emas"],explanation_uz:"-ник predmet yasaydi: choynak."},{id:"m10-wf-7",type:"translate",prompt:"Suffiks orqali toping: «jasorat/dadillik» (смелый)",answer:"смелость",explanation_uz:"смелый + -ость."}]},{id:"m10-synonyms-register",module:10,order:7,level:"C1",title:"Sinonimlar va registr",subtitle:"говорить / сказать / болтать / заявить",theory:[{heading:"Bir ma'no — turli bo'yoq",body:"C1 daraja — to'g'ri so'zni to'g'ri vaziyatda tanlash:",table:[["So'z","Registr","Bo'yoq"],["говори́ть","neytral","gapirmoq"],["болта́ть","so'zlashuv","valaqlamoq"],["бесе́довать","kitobiy","suhbatlashmoq"],["заяви́ть","rasmiy","bayon qilmoq"],["про́изнести́","kitobiy","talaffuz etmoq / nutq aytmoq"]]},{heading:"Yana misollar",body:"smотреть (neytral) / глазеть (qo'pol — bakrayib qaramoq) / созерцать (poetik). есть (neytral) / кушать (bolalarga/mehmonga muloyim) / жрать (dag'al). дом (neytral) / жильё (rasmiy) / хата (sleng)."}],comparisonWithUzbek:"O'zbekcha 'gapirmoq/valaqlamoq/suhbatlashmoq/bayon qilmoq' qatori ruscha говорить/болтать/беседовать/заявить ga aynan mos. Registrni adashtirish — ma'noni emas, OBRO'ni buzadi: rasmiy yig'ilishda болтать deyish kulgili.",examples:[{ru:"Мы до́лго бесе́довали о жи́зни.",uz:"Biz hayot haqida uzoq suhbatlashdik. (kitobiy)"},{ru:"Хва́тит болта́ть, рабо́тай!",uz:"Valaqlashni bas qil, ishla! (so‘zlashuv)"},{ru:"Мини́стр заяви́л о но́вой рефо́рме.",uz:"Vazir yangi islohot haqida bayonot berdi. (rasmiy)"},{ru:"Куша́йте, пожа́луйста!",uz:"Marhamat, yeb oling! (mehmonga muloyim)"}],commonMistakes:[{wrong:"Министр болтал о реформе",right:"Министр заявил о реформе",why_uz:"Rasmiy kontekst — rasmiy fe’l."},{wrong:"Я кушаю (kattalar o‘zi haqida)",right:"Я ем",why_uz:"кушать — boshqalarga muloyim taklif; o'zi haqida есть."}],exercises:[{id:"m10-syn-1",type:"choose",prompt:"Rasmiy bayonot uchun qaysi fe’l?",answer:"заявить",choices:["заявить","болтать","поболтать","трепаться"],explanation_uz:"заявить — rasmiy."},{id:"m10-syn-2",type:"choose",prompt:"«valaqlamoq» qanday?",answer:"болтать",choices:["болтать","беседовать","произнести","заявить"],explanation_uz:"болтать — so'zlashuv."},{id:"m10-syn-3",type:"choose",prompt:"Mehmonga muloyim: «yeb oling»",answer:"Кушайте, пожалуйста",choices:["Кушайте, пожалуйста","Жрите, пожалуйста","Ешь давай","Поглощайте"],explanation_uz:"кушать — mehmondorchilik odobi."},{id:"m10-syn-4",type:"choose",prompt:"O'zi haqida to'g'ri shakl:",answer:"Я ем",choices:["Я ем","Я кушаю","Я жру","Я вкушаю"],explanation_uz:"O'z nutqida neytral есть."},{id:"m10-syn-5",type:"errorHunt",prompt:"Registr xatosini toping: «Президент поболтал с народом о налогах»",answer:"Президент побеседовал с народом о налогах",explanation_uz:"Rasmiy shaxs — беседовать/заявить."},{id:"m10-syn-6",type:"choose",prompt:"Neytral «uy» rasmiy hujjatda?",answer:"жильё",choices:["жильё","хата","домик","берлога"],explanation_uz:"жильё — rasmiy termin."}]},{id:"m10-gerund-advanced",module:10,order:8,level:"C1",title:"Ravishdosh oborotlari va tinish belgilari",subtitle:"Murakkab gapni to'g'ri yozish",theory:[{heading:"Ravishdosh oboroti doim vergulda",body:"Ravishdosh va unga bog'liq so'zlar har doim verguldan ajratiladi: Прочитав письмо, он улыбнулся. Он шёл, не спеша, по улице. Bitta yolg'iz ravishdosh ham: Улыбаясь, она вошла."},{heading:"Asosiy xato: ega mosligi",body:"Ravishdosh faqat gap egasining ishini bildiradi. «Подъезжая к станции, у меня слетела шляпа» — XATO (shlyapa stansiyaga yaqinlashmagan!). To'g'ri: Подъезжая к станции, я потерял шляпу."},{heading:"Turg‘un birikmalar vergulsiz",body:"Frazeologik ravishdoshlar ajratilmaydi: работать спустя рукава (chala ishlamoq), бежать сломя голову (boshini olib qochmoq), сидеть сложа руки (qo'l qovushtirib o'tirmoq)."}],comparisonWithUzbek:"O'zbekcha '-ib' oboroti ham faqat ega bilan bog'lanadi: 'Xatni o'qib, u jilmaydi' — to'g'ri; 'Xatni o'qib, shlyapam uchdi' — xuddi ruschadagidek mantiqsiz. Ona tilingizdagi shu sezgi ruschada ham ishlaydi.",examples:[{ru:"Прочита́в письмо́, он улыбну́лся.",uz:"Xatni o'qib, u jilmaydi."},{ru:"Не зна́я пра́вил, тру́дно игра́ть.",uz:"Qoidalarni bilmay turib o'ynash qiyin."},{ru:"Он сиде́л сложа́ ру́ки.",uz:"U qo'l qovushtirib o'tirardi.",note:"frazeologizm — vergulsiz"},{ru:"Верну́вшись домо́й, я сра́зу лёг спать.",uz:"Uyga qaytib, darrov uxlashga yotdim."}],commonMistakes:[{wrong:"Подъезжая к станции, у меня слетела шляпа",right:"Подъезжая к станции, я потерял шляпу",why_uz:"Ravishdosh egasi gap egasi bilan bir xil bo‘lishi shart."},{wrong:"Прочитав письмо он улыбнулся",right:"Прочитав письмо, он улыбнулся",why_uz:"Oborot verguldan ajratiladi."},{wrong:"Он бежал, сломя голову",right:"Он бежал сломя голову",why_uz:"Frazeologizm vergulsiz."}],exercises:[{id:"m10-ga-1",type:"choose",prompt:"Qaysi gap to'g'ri?",answer:"Прочитав письмо, он улыбнулся",choices:["Прочитав письмо, он улыбнулся","Прочитав письмо, письмо понравилось","Прочитав письмо, у него улыбка","Прочитав письмо улыбнулся он сразу же"],explanation_uz:"Ega (он) ravishdosh ishini ham bajargan."},{id:"m10-ga-2",type:"errorHunt",prompt:"Mantiqiy xatoni toping: «Открыв окно, в комнату влетела птица»",answer:"Когда я открыл окно, в комнату влетела птица",explanation_uz:"Qush oynani ochmagan — ega mos emas, gapni qayta qurish kerak."},{id:"m10-ga-3",type:"choose",prompt:"«сидеть сложа руки» nimani anglatadi?",answer:"qo'l qovushtirib (bekor) o'tirmoq",choices:["qo'l qovushtirib (bekor) o'tirmoq","qo'lni jarohatlamoq","tez ishlamoq","qo'l silkitmoq"],explanation_uz:"Frazeologizm: hech narsa qilmay o‘tirmoq."},{id:"m10-ga-4",type:"choose",prompt:"Qaysi birikma VERGULSIZ yoziladi?",answer:"бежал сломя голову",choices:["бежал сломя голову","прочитав письмо","вернувшись домой","не зная правил"],explanation_uz:"Frazeologik ravishdosh ajratilmaydi."},{id:"m10-ga-5",type:"transform",prompt:"Ravishdosh bilan birlashtiring: «Я вернулся домой. Я сразу лёг спать»",answer:"Вернувшись домой, я сразу лёг спать",explanation_uz:"вернувшись — СВ ravishdoshi."},{id:"m10-ga-6",type:"translate",prompt:"Tarjima qiling: «Qoidani bilmay turib o‘ynama» (знать, играть)",answer:"Не зная правил, не играй",explanation_uz:"не зная — inkor ravishdosh."}]}],k=[{id:1,title:"Asos",subtitle:"Alifbo, talaffuz, eng sodda gaplar",level:"A1",icon:"А"},{id:2,title:"Ot va rod",subtitle:"Rod, ko'plik, egalik",level:"A1",icon:"Р"},{id:3,title:"Kelishiklar",subtitle:"6 kelishik — poydevor",level:"A1",icon:"П"},{id:4,title:"Fe'l",subtitle:"Tuslanish, zamonlar, aspekt",level:"A2",icon:"Г"},{id:5,title:"Harakat fe'llari",subtitle:"идти/ходить, prefikslar",level:"A2",icon:"И"},{id:6,title:"Sifat va ravish",subtitle:"Moslashuv, qiyoslash",level:"A2",icon:"С"},{id:7,title:"Sintaksis",subtitle:"Murakkab gap, sonlar, modallar",level:"B1",icon:"К"},{id:8,title:"Nutq amaliyoti",subtitle:"Kesim, yuklamalar, muloqot",level:"B1",icon:"Д"},{id:9,title:"Ileri grammatika",subtitle:"Kesimlar, passiv, sonlar, бы",level:"B2",icon:"В"},{id:10,title:"Mahorat",subtitle:"Uslublar, idiomalar, yuklamalar",level:"C1",icon:"М"}],r=[...t,...s,...l,...m,...h,...u,...d,...p,...y,...g],b=new Map(r.map(a=>[a.id,a]));function z(a){return r.filter(i=>i.module===a).sort((i,o)=>i.order-o.order)}function q(a,i){const o=z(a);if(!o.length)return 0;const n=o.filter(e=>i[e.id]?.completed).length;return Math.round(n/o.length*100)}function c(a){const i=Date.now();return r.filter(o=>{const n=a[o.id];return!n||!n.completed?!1:new Date(n.next_review).getTime()<=i})}function _(a){return r.find(i=>!a[i.id]?.completed)}const w=[{id:"active-recall",title:"Active Recall",goal:"Qoidani o'qib qo'ymasdan, javobni xotiradan chiqarish.",steps:["Savolni ko'ring","Javobni yozing yoki ayting","Keyin to'g'ri javob bilan solishtiring"],bestFor:"So'z, kelishik, fe'l tuslash"},{id:"pattern-drill",title:"Pattern Drill",goal:"Bitta grammatik qolipni ko'p variantda avtomatlashtirish.",steps:["Qolipni ko'ring","So'zni almashtiring","Gapni ovoz chiqarib ayting"],bestFor:"Я хочу..., Мне нужно..., У меня есть..."},{id:"sentence-transform",title:"Sentence Transformation",goal:"Gapni zamon, shaxs yoki kelishik bo'yicha o'zgartirish.",steps:["Berilgan gapni o'qing","Talab qilingan shaklga o'tkazing","Xatoni izoh bilan tuzating"],bestFor:"Fe'l zamonlari, savol/inkor gap"},{id:"shadowing",title:"Shadowing",goal:"Ruscha gap ritmini va talaffuzini ko'chirish.",steps:["Gapni tinglang","Darhol ortidan ayting","3 marta takrorlang"],bestFor:"Speaking va listening"},{id:"dictation",title:"Mini Dictation",goal:"Eshitilgan ruscha gapni yozish orqali listening va spellingni kuchaytirish.",steps:["Gapni eshiting","Yozing","So'zma-so'z tekshiring"],bestFor:"Harflar, yumshoq belgi, predloglar"},{id:"role-play",title:"Role Play",goal:"Grammatikani real vaziyatda ishlatish.",steps:["Vaziyat tanlang","Ruscha javob bering","AI yoki app xatoni tuzatsin"],bestFor:"Do'kon, restoran, taksi, ish, telefon"}];export{k as G,w as L,b as T,r as a,c as d,q as m,_ as n,z as t};
